-- paket 8: 4d3n-manado-highlights-tour
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '8', 'es', '4 Días Tour Highlights de Manado', '<h2><strong>Tour Highlights de Manado 4D3N: ¡Descubre las Maravillas de la Naturaleza y la Cultura en Sulawesi del Norte!</strong></h2><p>Embárcate en una aventura inolvidable de 4 días y 3 noches en Manado y sus alrededores. Este tour combina belleza submarina de clase mundial, encanto montañoso refrescante y una cultura local única en un solo viaje exclusivo diseñado para tu máxima comodidad.</p><h3><strong>Puntos Destacados:</strong></h3><ul><li><strong>Lugares Icónicos:</strong> Visita el histórico <strong>Templo Ban Hin Kiong</strong> y el majestuoso <strong>Monumento de Jesús Bendiciendo</strong> que domina la ciudad.</li><li><strong>Paraíso Marino de Bunaken:</strong> Explora el legendario <strong>Parque Marino Nacional de Bunaken</strong>, hogar de coloridos arrecifes de coral y diversa vida marina.</li><li><strong>Encanto del Altiplano de Minahasa:</strong> Disfruta del aire fresco de Tomohon, descubre el único <strong>Mercado Extremo</strong> y relájate en el <strong>Lago Linow</strong> de colores cambiantes.</li><li><strong>Lugares Perfectos para Instagram:</strong> Captura vistas de 360 grados desde la <strong>Colina de Makatete</strong> y el estético bosque de palmeras de <strong>Tuur Maasering</strong>.</li></ul>', '<ul><li data-list-item-id="e471204a79d04f381b4df48abd3568538">Transporte con aire acondicionado según el tamaño del grupo</li><li data-list-item-id="e5b23337d0965051bf73eab7da059f4d6">Barco privado a la <strong>isla de Bunaken&nbsp;</strong></li><li data-list-item-id="ee8b3c0ce962717687e5c7022da4a5338">3 noches de alojamiento en el hotel seleccionado – habitación twin/doble</li><li data-list-item-id="eb352e4cf3b88e05f28979629bdbb9af3">Guía experto &amp; conductor</li><li data-list-item-id="e15fdff726b9e0d6b7522d89e853d30c7">Entradas a las atracciones turísticas &amp; estacionamiento</li><li data-list-item-id="eea1816d36947b4e805dd272a628cdf0e">Comidas según el programa</li><li data-list-item-id="eb97366b44df314dee7b6f99ac3ca6044">Servicios turísticos según el itinerario</li><li data-list-item-id="e15fff39ee2756b1703ce5cb3c6a898cf">Agua mineral 1 botella/persona/día</li><li data-list-item-id="e96b7b72b91c673e978df24be855f3346">Servicio de recepción</li></ul>', '<ul><li data-list-item-id="e1dc181d36af8406f97796d1769568909">Boleto de avión de ida y vuelta</li><li data-list-item-id="e71726909053b640df3cf3fad15a8fa02">Propinas para el guía &amp; el conductor</li><li data-list-item-id="e11be5b6ad773248b059620b238aee9b8">Excursiones opcionales</li><li data-list-item-id="e2d93bfcb857f4cecda93f3d73f2629ee">Gastos personales fuera del paquete (comidas/bebidas adicionales, etc.)</li><li data-list-item-id="ef7dd221a222f7b6c5b9e01cefa4cc2e4">Servicio de mozos, impuesto aeroportuario &amp; exceso de equipaje</li><li data-list-item-id="ebadfd3cab7dc05d402522ac0ce442654">Gastos personales (lavandería, minibar, servicio a la habitación, etc.)</li><li data-list-item-id="e81328aad0a1b986831eed337f4f20e9b">Seguro de viaje</li><li data-list-item-id="e59c4a681478a9f8e689ec94ec3db1a1d">Otros gastos no mencionados en el programa del tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 9: 4d3n-manado-island-gateway
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '9', 'es', '4 Días Escape Insular de Manado', '<h2><strong>Escape Insular de Manado 4D3N: ¡Explora el Encanto Tropical de Sulawesi del Norte!</strong></h2><p>Vive el escape perfecto de 4 días y 3 noches a través de la belleza marina y la rica cultura de Manado. Desde la majestuosidad submarina de clase mundial del <strong>Parque Marino Nacional de Bunaken</strong> hasta la suave arena blanca de la <strong>Isla de Lihaga</strong>, este paquete está diseñado para unas vacaciones inolvidables.</p><h3><strong>Puntos Destacados:</strong></h3><ul><li><strong>Lugares Icónicos:</strong> Visita <strong>Ban Hin Kiong</strong>, el templo más antiguo de Manado, y el majestuoso <strong>Monumento de Jesús Bendiciendo</strong>.</li><li><strong>Paraíso Marino:</strong> Explora los coloridos arrecifes de coral en <strong>Bunaken</strong> y relájate en la <strong>Isla de Lihaga</strong>, perfecta para Instagram.</li><li><strong>Panoramas Impresionantes:</strong> Disfruta de vistas de la ciudad y las islas desde la <strong>Colina de Makatete</strong> y un atardecer sereno en el <strong>Pueblo Turístico de Budo</strong>.</li><li><strong>Sabores Locales:</strong> Prueba el auténtico café de Sulawesi del Norte y compra especialidades únicas de Manado.</li></ul>', '<ul><li data-list-item-id="e471204a79d04f381b4df48abd3568538">Transporte con aire acondicionado según el tamaño del grupo</li><li data-list-item-id="e5b23337d0965051bf73eab7da059f4d6">Barco privado a <strong>la isla de Bunaken &amp; la isla de Lihaga</strong></li><li data-list-item-id="ee8b3c0ce962717687e5c7022da4a5338">3 noches de alojamiento en el hotel seleccionado – habitación twin/doble</li><li data-list-item-id="eb352e4cf3b88e05f28979629bdbb9af3">Guía experto &amp; conductor</li><li data-list-item-id="e15fdff726b9e0d6b7522d89e853d30c7">Entradas a las atracciones turísticas &amp; estacionamiento</li><li data-list-item-id="eea1816d36947b4e805dd272a628cdf0e">Comidas según el programa</li><li data-list-item-id="eb97366b44df314dee7b6f99ac3ca6044">Servicios turísticos según el itinerario</li><li data-list-item-id="e15fff39ee2756b1703ce5cb3c6a898cf">Agua mineral 1 botella/persona/día</li><li data-list-item-id="e96b7b72b91c673e978df24be855f3346">Servicio de recepción</li></ul>', '<ul><li data-list-item-id="e1dc181d36af8406f97796d1769568909">Boleto de avión de ida y vuelta</li><li data-list-item-id="e71726909053b640df3cf3fad15a8fa02">Propinas para el guía &amp; el conductor</li><li data-list-item-id="e11be5b6ad773248b059620b238aee9b8">Excursiones opcionales</li><li data-list-item-id="e2d93bfcb857f4cecda93f3d73f2629ee">Gastos personales fuera del paquete (comidas/bebidas adicionales, etc.)</li><li data-list-item-id="ef7dd221a222f7b6c5b9e01cefa4cc2e4">Servicio de mozos, impuesto aeroportuario &amp; exceso de equipaje</li><li data-list-item-id="ebadfd3cab7dc05d402522ac0ce442654">Gastos personales (lavandería, minibar, servicio a la habitación, etc.)</li><li data-list-item-id="e81328aad0a1b986831eed337f4f20e9b">Seguro de viaje</li><li data-list-item-id="e59c4a681478a9f8e689ec94ec3db1a1d">Otros gastos no mencionados en el programa del tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 10: 5d4n-tropical-wonders-of-manado
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '10', 'es', '5 Días Maravillas Tropicales de Manado', '<h2><strong>Maravillas Tropicales de Manado: Una Exploración de 5 Días por los Paraísos Exóticos de Sulawesi del Norte</strong></h2><p>Descubre la armonía perfecta entre aventuras submarinas de clase mundial y la belleza serena del altiplano. El paquete <strong>5D4N Maravillas Tropicales de Manado</strong> es una invitación exclusiva a explorar cada rincón mágico de Sulawesi del Norte — desde la historia de la ciudad antigua y las aguas cristalinas de la Isla de Lihaga hasta el símbolo de paz en Bukit Kasih.</p><h3><strong>Puntos Destacados del Tour:</strong></h3><ul><li><strong>Exploración Icónica de la Ciudad de Manado:</strong> Sigue la historia en Ban Hin Kiong (el templo más antiguo de Manado), visita el Monumento de la Segunda Guerra Mundial, y contempla la majestuosidad de la Estatua de Jesús Bendiciendo con vista al mar.</li><li><strong>Maravillas Marinas de Bunaken:</strong> Vive un tour de avistamiento en el legendario Parque Marino de Bunaken, hogar de enormes paredes de coral y miles de vibrantes especies de peces tropicales.</li><li><strong>El Esplendor de la Isla de Lihaga:</strong> Disfruta de un paraíso insular deshabitado con arena blanca suave y aguas cristalinas — un lugar perfecto para relajarse y momentos perfectos para Instagram.</li><li><strong>Armonía en Bukit Kasih (Colina del Amor):</strong> Respira el aire fresco del Altiplano de Minahasa y visita el centro de tolerancia de Sulawesi del Norte. Sube las escaleras hasta la cima para ver cinco lugares de culto uno junto al otro como símbolo de unidad.</li><li><strong>El Encanto del Lago Linow:</strong> Termina tu día relajándote junto a un lago de azufre único donde el agua cambia de color de forma mágica, creando una atmósfera profundamente serena.</li></ul><h3><strong>¿Por Qué Elegir Este Paquete?</strong></h3><ul><li><strong>Destinos Completos:</strong> Combina el patrimonio urbano, aventuras de isla en isla y la belleza del altiplano en un solo viaje sin interrupciones.</li><li><strong>Sabiduría Local:</strong> Visita casas locales de producción de café y observa el proceso auténtico de preparación de bocadillos tradicionales de Manado.</li><li><strong>Itinerario Equilibrado:</strong> Un programa bien ritmado que garantiza disfrutar de cada destino sin sentirte apresurado.</li></ul>', '<ul><li data-list-item-id="eea05a0fde3c9ad132dbf48ce720f5561">Transporte con aire acondicionado según el tamaño del grupo</li><li data-list-item-id="e35785e5ddfb6a5dbd4ed40faf695693a">Barco privado a <strong>la isla de Bunaken &amp; la isla de Lihaga</strong></li><li data-list-item-id="e11a26ee9d49a5ac1820047c130a6dfd5">4 noches de alojamiento en el hotel seleccionado – habitación twin/doble</li><li data-list-item-id="ed5854fe627dc7e654934ab1e976947b9">Guía experto &amp; conductor</li><li data-list-item-id="e81a3939bb0ae47c432179a015b5820f9">Entradas a las atracciones turísticas &amp; estacionamiento</li><li data-list-item-id="eabab84f65a739c80174326ae687d6b04">Comidas según el programa</li><li data-list-item-id="ecc87f33179f708ea4e88eab3be33ec4b">Servicios turísticos según el itinerario</li><li data-list-item-id="e103e760176de41ca65afc60d31e98ff4">Agua mineral 1 botella/persona/día</li><li data-list-item-id="ef790cc1f991b5e82333a286a94bd3e06">Servicio de recepción</li></ul>', '<ul><li data-list-item-id="ef5d685346305b0f7f7808e0b74584d12">Boleto de avión de ida y vuelta</li><li data-list-item-id="e94d1cf8dad2496875a013333c9a2fb20">Propinas para el guía &amp; el conductor</li><li data-list-item-id="e78256fbdd7f99f311466b507bd7703f6">Excursiones opcionales</li><li data-list-item-id="e3cd0374398d870ebbfd590981eab8338">Gastos personales fuera del paquete (comidas/bebidas adicionales, etc.)</li><li data-list-item-id="e863d09a2873702f66d5a57da029388d2">Servicio de mozos, impuesto aeroportuario &amp; exceso de equipaje</li><li data-list-item-id="ec55c74e4c2067333dd4c54aa28d879f1">Gastos personales (lavandería, minibar, servicio a la habitación, etc.)</li><li data-list-item-id="ee355dc061e586232a936ec63b0305405">Seguro de viaje</li><li data-list-item-id="e321a09c3a477e2305453ecd7e331735d">Otros gastos no mencionados en el programa del tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 11: 4d3n-exotic-manado-explorer
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '11', 'es', '4 Días Exploración Exótica de Manado', '<h2><strong>Manado Sin Fronteras: Un Viaje de 4 Días a Paraísos Escondidos desde el Altiplano hasta Lihaga</strong></h2><p>¿Estás listo para escapar a un paraíso tropical que combina maravillas submarinas, colinas verdes exuberantes y un patrimonio cultural único? El paquete <strong>4D3N Exploración Exótica de Manado</strong> está meticulosamente diseñado para quienes buscan una experiencia vacacional completa e inolvidable. Desde el encanto de la ciudad antigua hasta islas exóticas con arena blanca suave, te llevaremos a explorar lo mejor de Sulawesi del Norte.</p><h3><strong>Puntos Destacados del Tour:</strong></h3><ul><li><strong>Exploración Icónica de la Ciudad:</strong> Visita la majestuosa Estatua de Jesús Bendiciendo en CitraLand y sigue la historia en Ban Hin Kiong, el templo más antiguo de Manado.</li><li><strong>Maravillas del Altiplano de Minahasa:</strong> Siente la brisa fresca de Tomohon, visita el mercado extremo mundialmente famoso, y relájate con café o té junto a las aguas cambiantes del Lago Linow.</li><li><strong>Paraíso Tropical de la Isla de Lihaga:</strong> Deleita tus sentidos con la impresionante arena blanca y las aguas cristalinas de la Isla de Lihaga — un lugar perfecto para hacer snorkel, buceo o capturar momentos perfectos para Instagram.</li><li><strong>Atardecer en el Pueblo Turístico de Budo:</strong> Concluye tu aventura insular con un atardecer impresionante mientras disfrutas de delicias locales como plátanos fritos y coco fresco.</li><li><strong>Auténtica Sabiduría Local:</strong> Observa la producción tradicional del licor "Cap Tikus" y mira demostraciones de cocina en vivo de deliciosos bocadillos locales de Manado</li></ul>', '<ul><li data-list-item-id="e11c918e1af328b6b0e6bd2c3d6c46e5d">Transporte con aire acondicionado según el tamaño del grupo</li><li data-list-item-id="ebc2761735faa295be9869faeba5ef9c3">Barco privado a la isla de Lihaga</li><li data-list-item-id="e1f7e9ade1181eb30404b6c4f7263c2b1">3 noches de alojamiento en el hotel seleccionado – habitación twin/doble</li><li data-list-item-id="ebbdb40dd9308cc6ba65794e075cced2f">Guía experto &amp; conductor</li><li data-list-item-id="e2279728b3feae8fdd9a4669a3cecffd3">Entradas a las atracciones turísticas &amp; estacionamiento</li><li data-list-item-id="e827fd57d3a5e570b5b508c9fc5e721fa">Comidas según el programa</li><li data-list-item-id="e8468f13ea9c16c3b266d42594e607992">Servicios turísticos según el itinerario</li><li data-list-item-id="e10fb1ed65e37365dbfff95f53601fbdb">Agua mineral 1 botella/persona/día</li><li data-list-item-id="ed4846e433289ae5057f860554a9f6f0d">Servicio de recepción</li></ul>', '<ul><li data-list-item-id="ef8f2361176c16ceca608dff85850a599">Boleto de avión de ida y vuelta</li><li data-list-item-id="ea8a90f748b0acc8d8c682bc6aba46c8f">Propinas para el guía &amp; el conductor</li><li data-list-item-id="e018e34ac8cbe045803a46d616e48d4aa">Excursiones opcionales</li><li data-list-item-id="ed2e1a8df37b435a7b0217ea2351babdd">Gastos personales fuera del paquete (comidas/bebidas adicionales, etc.)</li><li data-list-item-id="e0b26c90da4e226af6c485c66f215a053">Servicio de mozos, impuesto aeroportuario &amp; exceso de equipaje</li><li data-list-item-id="e892a7a71628c913e7c40d29cad4c8939">Gastos personales (lavandería, minibar, servicio a la habitación, etc.)</li><li data-list-item-id="eb026a0cc55dc3225736ba4099fbe22c9">Seguro de viaje</li><li data-list-item-id="e0d7036afa0726248cfb0462f1cd28859">Otros gastos no mencionados en el programa del tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 12: 3d2n-manado-bliss-gateway
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '12', 'es', '3 Días Escape al Altiplano de Manado', '<h2><strong>Escape al Altiplano de Manado: Viaje por la Naturaleza &amp; la Cultura Minahasa (3D2N)</strong></h2><p>Relájate y respira el aire fresco de montaña de Sulawesi del Norte en un viaje que reconforta el alma. Este paquete te invita a explorar el patrimonio icónico de la Ciudad de Manado y la impresionante belleza del Altiplano de Minahasa. Desde vistas majestuosas desde la cima de la colina hasta lagos volcánicos serenos, cada momento está diseñado para unas vacaciones relajantes e inolvidables.</p><h3><strong>Puntos Destacados del Tour:</strong></h3><ul><li><strong>Íconos de la Ciudad de Manado:</strong> Sigue la historia en el <strong>Templo Ban Hin Kiong</strong> (el más antiguo de Manado), la iglesia colonial de Sentrum, y el magnífico <strong>Monumento de Jesús Bendiciendo</strong>, símbolo de la protección de la ciudad.</li><li><strong>Panorama de la Colina de Makatete:</strong> Disfruta de una vista de "360 grados" desde las alturas, con vista a la Ciudad de Manado, las islas del Parque Marino de Bunaken y el imponente Monte Klabat.</li><li><strong>La Fresca Ciudad de las Flores de Tomohon:</strong> Vive el aire fresco al pie del <strong>Monte Mahawu</strong>. Visita el <strong>Lago Linow</strong>, un lago volcánico cuyas aguas cambian de color según la luz del sol.</li><li><strong>Almuerzo junto al Lago Tondano:</strong> Saborea platos locales auténticos mientras contemplas las aguas tranquilas del Lago Tondano, el lago más grande de Sulawesi del Norte, rodeado de colinas verdes exuberantes.</li><li><strong>Estilo de Vida &amp; Compras:</strong> Relájate en <strong>SunBae</strong>, un punto de encuentro de moda junto al mar, y visita una casa local de producción de café para llevar a casa el aroma auténtico de Sulawesi.</li></ul><p><strong>«Escapa a las alturas – Descubre el alma de Minahasa y la serenidad del altiplano.»</strong></p>', '<ul><li data-list-item-id="e8e6883a6e56a2407f008c457746ff1b6">Transporte con aire acondicionado según el tamaño del grupo</li><li data-list-item-id="e8de14905ae06a64f87cc60b7707f22d0">2 noches de alojamiento en el hotel seleccionado – habitación twin/doble</li><li data-list-item-id="e4bb6b6d5246389f96275d7a9a8a82136">Comidas según el programa</li><li data-list-item-id="eea1dca8498d90beff0733fbed2b12b77">Guía experto &amp; conductor</li><li data-list-item-id="ec02237fe232f55cc706fb1297ad87fad">Entradas a las atracciones turísticas &amp; estacionamiento</li><li data-list-item-id="ed6a3feef8a8add362060ccd621024e6d">Servicios turísticos según el itinerario</li><li data-list-item-id="ec668e506dcb5e72b186b8387ab536b9a">Agua mineral 1 botella/persona/día</li><li data-list-item-id="e532893443396609a2ad9f6b124a36b95">Servicio de recepción</li></ul>', '<ul><li data-list-item-id="e3b523e8375ebb8c9d79946b95b626000">Boleto de avión de ida y vuelta</li><li data-list-item-id="ebb59df0fa48ba937a21926c9d7e1f3dd">Propinas para el guía &amp; el conductor</li><li data-list-item-id="e3ce39bff4df98057a82869976df231d7">Excursiones opcionales</li><li data-list-item-id="e3f219b92323c9770103f518bec22b1ba">Gastos personales fuera del paquete (comidas/bebidas adicionales, etc.)</li><li data-list-item-id="e11ba73fd8e73eef138f3ca4ad9edebf4">Servicio de mozos, impuesto aeroportuario &amp; exceso de equipaje</li><li data-list-item-id="ec1219e9200318981e942067b191d0e19">Gastos personales (lavandería, minibar, servicio a la habitación, etc.)</li><li data-list-item-id="eeb6d510ef8ff5842d69e6e91a30b5aa4">Seguro de viaje</li><li data-list-item-id="e0bf84136b233377c9c534be5adbe9757">Otros gastos no mencionados en el programa del tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 13: 3d2n-manado-highland-escape
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '13', 'es', '3 Días Escapada Serena a Manado', '<h2><strong>Escapada Serena a Manado: Encanto Urbano, Vistas del Altiplano &amp; Maravillas Submarinas (3D2N)</strong></h2><p>¡Explora la magia de Sulawesi del Norte en un paquete vacacional corto pero memorable! Desde sitios históricos en el corazón de Manado y panoramas espectaculares desde las cimas de las colinas hasta el reconocido Parque Marino de Bunaken. Este paquete es la elección perfecta para quienes buscan una armonía entre cultura, relajación y aventura en la naturaleza.</p><h3><strong>Puntos Destacados del Tour:</strong></h3><ul><li><strong>Exploración Histórica &amp; Cultural:</strong> Sigue el pasado de Manado en el icónico <strong>Templo Ban Hin Kiong</strong> (el templo más antiguo del siglo XVIII), la iglesia colonial de Sentrum, y el magnífico <strong>Monumento de Jesús Bendiciendo</strong> en CitraLand.</li><li><strong>Panoramas desde la Colina de Makatete:</strong> Disfruta de una vista de "360 grados" de la Ciudad de Manado, la Isla de Bunaken y el Monte Klabat desde el altiplano. Un lugar perfecto para la fotografía y el aire fresco de montaña.</li><li><strong>Magia Submarina de Bunaken:</strong> Vive un tour de avistamiento en catamarán para ver hermosos arrecifes de coral y vida marina sin mojarte, o elige hacer snorkel para observar más de cerca tortugas marinas y peces coloridos.</li><li><strong>Estilo de Vida Local:</strong> Relájate en <strong>SunBae</strong>, un punto de encuentro de moda junto al mar, y visita una casa local de producción de café para probar el aroma auténtico del café de Sulawesi.</li><li><strong>Compras de Recuerdos:</strong> Completa tu viaje buscando deliciosos y únicos bocadillos y regalos tradicionales de Manado antes de regresar a casa.</li></ul><p><strong>«Vive la serenidad de Manado – donde la historia, las alturas y las aguas cristalinas se encuentran.»</strong></p>', '<ul><li data-list-item-id="e06181f8916c033d055bf431ea9bb507d">Transporte con aire acondicionado según el tamaño del grupo</li><li data-list-item-id="ec74f2f93cf89580ce2eba2c1def0a181">Barco privado a la <strong>isla de Bunaken</strong></li><li data-list-item-id="e8e4a93b41c7a6ed50ed3813194bd6e59">2 noches de alojamiento en el hotel seleccionado – habitación twin/doble</li><li data-list-item-id="e91c056088dcfc8c669ef740833e245c5">Comidas según el programa</li><li data-list-item-id="e065c54e6af38a7ad1bd490f01b5b5818">Guía experto &amp; conductor</li><li data-list-item-id="ee0e35b2c23993c0791e055d49f1f6f9d">Entradas a las atracciones turísticas &amp; estacionamiento</li><li data-list-item-id="e76df34d52a6a29e995f5d9be291dd79b">Servicios turísticos según el itinerario</li><li data-list-item-id="e620b8eda8fdcede4f1fbaf8c0908a778">Agua mineral 1 botella/persona/día</li><li data-list-item-id="e2640041a620be5c0b2575af63aa0074e">Servicio de recepción</li></ul>', '<ul><li data-list-item-id="e6fe90ccd0d08c5ebfa1c0966f14e1e37">Boleto de avión de ida y vuelta</li><li data-list-item-id="ee405bf5b6e9984c12726b290bcf96832">Propinas para el guía &amp; el conductor</li><li data-list-item-id="e54a6f1381c6ba9c3e26eb7685fcccedb">Excursiones opcionales</li><li data-list-item-id="e202c477f749dc16522c760ea26ce63fe">Gastos personales fuera del paquete (comidas/bebidas adicionales, etc.)</li><li data-list-item-id="e3eee6b6c5ec03bcbabcb277307efbc5f">Servicio de mozos, impuesto aeroportuario &amp; exceso de equipaje</li><li data-list-item-id="edd02c634ddc4057311fbdaabd045c0cb">Gastos personales (lavandería, minibar, servicio a la habitación, etc.)</li><li data-list-item-id="e054a8fc0bec74542de93820aa5038d72">Seguro de viaje</li><li data-list-item-id="ed8953b086fc7833fe1607e7f3df48f49">Otros gastos no mencionados en el programa del tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 14: paragliding-adventure-at-mount-tumpa
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '14', 'es', 'Aventura de Parapente en el Monte Tumpa', '<h2><strong>Volar Sobre el Horizonte: Aventura de Parapente en el Monte Tumpa</strong></h2><p>¿Alguna vez has soñado con volar libremente como un pájaro sobre un paisaje extraordinario? Haz realidad ese sueño con el <strong>parapente en el Monte Tumpa</strong>, el destino ideal para elevar tu adrenalina mientras deleitas tus ojos con el impresionante horizonte de Sulawesi del Norte.</p><h3><strong>¿Por Qué Deberías Probar Esta Aventura?</strong></h3><ul><li><strong>Una Emoción a 1.000 Metros:</strong> Siente cómo se acelera tu corazón al despegar a una altitud de aproximadamente 1.000 metros. Disfruta de una libertad absoluta mientras te deslizas sobre majestuosos paisajes montañosos.</li><li><strong>Panorama de Triple Vista:</strong> Desde el aire, disfrutarás de una vista espectacular que combina exuberantes bosques verdes, cadenas montañosas y el mar azul cristalino a lo lejos.</li><li><strong>Seguro para Principiantes &amp; Profesionales:</strong> El Monte Tumpa es reconocido por su clima estable y vientos suaves, convirtiéndolo en un lugar muy seguro tanto para principiantes como para quienes buscan perfeccionar sus habilidades.</li><li><strong>Guía Profesional:</strong> Tu seguridad es nuestra prioridad. Estarás acompañado por un instructor de parapente certificado y equipado con equipo de seguridad de estándar internacional.</li></ul><p><strong>«¡Siente la emoción, contempla la belleza, y haz que tu viaje a Manado sea realmente inolvidable!»</strong></p>', '<ul><li data-list-item-id="ea1013fe641dbc74405bab4a89c5269d4">Instructor profesional de parapente</li><li data-list-item-id="e270763c5cc1b5c10062db7e71349a127">Entradas a las atracciones</li><li data-list-item-id="e0c8e90b12db6655ee96a9b9c53a48929">Servicios turísticos según el programa</li></ul>', '<ul><li data-list-item-id="e09808b568f0f7cf8b77bb2460fbf04c1">Boleto de avión</li><li data-list-item-id="e7861cd3a295b5e9e7e7e32ec1bb61a65">Automóvil (recogida &amp; devolución) opcional</li><li data-list-item-id="eb8cd71ddf1d59066b0fe144c54b66278">Impuesto aeroportuario</li><li data-list-item-id="e571d4f230715ed2fbe507807bb77544d">Mozos&nbsp;</li><li data-list-item-id="e11238ef8ad6bdc98761802c20dafcd49">Hotel</li><li data-list-item-id="edcff8a0aeff894bd3a8e1024cb208edb">Guía</li><li data-list-item-id="e68946d32764504f4bc586c60286973e8">Propina del conductor</li><li data-list-item-id="ed0f9917e71858b2d5a6c5bc0a3788568">Excursiones opcionales</li><li data-list-item-id="ea0fb1478644b3360fcfc07c2524c963e">Otros gastos fuera del programa del tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 15: tarsius-canoe-adventure-highland-sunset
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '15', 'es', 'Aventura en Canoa de los Tarsios &amp; Atardecer en el Altiplano', '<h2><strong>Aventura en Canoa &amp; al Anochecer: Canoa de los Tarsios &amp; Atardecer en el Altiplano</strong></h2><p>Descubre un lado escondido de las maravillas naturales de Sulawesi del Norte en un viaje que combina una serena exploración acuática con un impresionante atardecer. Desde observar al primate más pequeño del mundo en el corazón de un bosque de manglares hasta vivir la hora dorada desde el altiplano, este paquete ofrece momentos verdaderamente inolvidables.</p><h3><strong>Puntos Destacados del Tour:</strong></h3><ul><li><strong>Exploración de Manglares en Canoa:</strong> Vive la tranquilidad de deslizarte por las aguas cristalinas de la <strong>Playa Rap-Rap</strong> en una canoa tradicional. Deja que los sonidos de la naturaleza te acompañen a través del exuberante e intacto bosque de manglares.</li><li><strong>Conoce al Tarsio en Su Hábitat Natural:</strong> Disfruta de la rara oportunidad de ver al <strong>Tarsio</strong>, un fascinante primate diminuto con encantadores ojos grandes, que habita entre los árboles de manglar. ¡Eres libre de capturar estos momentos mágicos tanto como quieras!</li><li><strong>Atardecer Icónico en el Monte Tumpa:</strong> Termina tu día viendo cómo el majestuoso sol se hunde bajo el horizonte desde el altiplano del <strong>Monte Tumpa</strong>. Esta vista panorámica de la costa y el horizonte es una de las mejores de Manado.</li><li><strong>Sabores Locales:</strong> Mientras esperas el atardecer, puedes disfrutar de varios bocadillos tradicionales de Manado, como el legendario Plátano Frito con Salsa Picante Roa o el Hielo de Frijoles Rojos (opcional).</li></ul><p><strong>«Desde los silenciosos manglares hasta las alturas doradas – descubre el alma escondida de Sulawesi del Norte.»</strong></p>', '<ul><li data-list-item-id="e7bc9e1165c9336d08f046154ec23b677">Transporte con aire acondicionado según el número de participantes</li><li data-list-item-id="ea7af70bb2a82bcea77255af2e5bee5f8">Guía experto de manglares y conductor</li><li data-list-item-id="eae204140fa5bb1dcce46af8f50941376">Canoa</li><li data-list-item-id="e80f346479d08bc79ba631e2cd3b91eb6">Entradas a las atracciones turísticas&nbsp;</li><li data-list-item-id="e464bfce6ecdcffccb9875ff5346cfc6b">Estacionamiento</li><li data-list-item-id="e276d3b05d37581d3fd4159c5dd2f2075">1 botella de agua mineral por persona</li><li data-list-item-id="e285b78b0ee79f6f91b8f1fc2b17ac847">Servicios turísticos según el programa</li></ul>', '<ul><li data-list-item-id="e08be48cb4f21a5377ce9748c0ca49109">Boleto de avión</li><li data-list-item-id="ed90b677285985025078bdb06a9cf6c45">Impuesto aeroportuario</li><li data-list-item-id="ea142622087caa49b2ff7e4c53a07b979">Mozos</li><li data-list-item-id="eb25e5a10849163e000f250df28b0b66d">Comidas</li><li data-list-item-id="e6afc882721d3368dc426447ed90c3af0">Hotel</li><li data-list-item-id="edb5d4d26a2cfe5fde84d5a34dde54592">Propinas para el guía &amp; el conductor</li><li data-list-item-id="eab39da60f0dd66cad430d5382fc5acdc">Excursiones opcionales</li><li data-list-item-id="e4ce6a2be042d0929991d5051e57283ca">Otros gastos fuera del programa del tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 16: tangkoko-nature-reserve-tour-tunan-waterfall
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '16', 'es', 'Tour a la Reserva Natural de Tangkoko &amp; Cascada de Tunan', '<h2><strong>Naturaleza &amp; Vida Salvaje: Un Viaje a Tangkoko y Tunan</strong></h2><p>¡Prepara tu cámara y tu espíritu de aventura! Este paquete te lleva fuera de los caminos habituales al corazón de una de las mejores áreas de conservación de Indonesia y maravillas de cascadas escondidas. Desde el primate más pequeño del mundo hasta el rugido de una cascada de 86 metros de altura, esta experiencia será el punto culminante de tu viaje por Sulawesi del Norte.</p><h3><strong>Puntos Destacados del Tour:</strong></h3><ul><li><strong>La Majestuosidad de la Cascada de Tunan:</strong> Comienza tu aventura en el Pueblo de Talawaan. Siente la fresca bruma de una cascada de 86 metros de altura cayendo en medio de un bosque prístino e intacto.</li><li><strong>Conoce a los Habitantes Originales de Tangkoko:</strong> Explora la <strong>Reserva Natural de Tangkoko</strong>, hogar de una fauna endémica única. Descubre al <strong>Tarsio</strong> (el primate más pequeño del mundo con adorables ojos grandes) y al <strong>Yaki</strong> (Macaco Negro de Sulawesi) deambulando libremente.</li><li><strong>Rica Biodiversidad:</strong> Más allá de los Tarsios, prepárate para descubrir icónicos Cálaos y Cuscús en su hábitat natural, guiado por guardaparques forestales profesionales.</li><li><strong>Un Viaje Relajante:</strong> Disfruta de una ruta panorámica que pasa por encantadores pueblos pequeños con vistas relajantes de valles y colinas en el camino hacia Bitung.</li></ul><p><strong>«Un encuentro cercano con la naturaleza – descubre la fauna única y las cascadas prístinas de Sulawesi del Norte.»</strong></p>', '<ul><li data-list-item-id="e3a6d5c7a95824505fcc7169d19c68b06">Transporte totalmente con aire acondicionado según el número de participantes</li><li data-list-item-id="ec6d02de779b3cf721615c06630e5b3a2">Guardaparques en la reserva natural de Tangkoko</li><li data-list-item-id="eed59092e3fde448a5e5a4fb756ab6e44">Guía y conductor expertos</li><li data-list-item-id="e1fbf9e5db829006a3fc211fef7a86ec5">Entradas a las atracciones turísticas</li><li data-list-item-id="ec1827a81cbe7feb5e6c155dc5f41899e">Estacionamiento</li><li data-list-item-id="eb65edb1a96b3c032f8f825315f9c7209">Almuerzo</li><li data-list-item-id="e5971d7bd5ebcae0985b7b12074916355">Una botella de agua mineral por persona</li><li data-list-item-id="ef7e51ca1230476f54d606b374973afb1">Servicios turísticos según el programa</li></ul>', '<ul><li data-list-item-id="ed1003d6a37aa7b1fbafe39f48ba09598">Boleto de avión</li><li data-list-item-id="e9101a0e59598b6ff7f1e74ede3ede14f">Impuesto aeroportuario</li><li data-list-item-id="efd4176d12238c02b80f1e80ada630810">Mozos</li><li data-list-item-id="ea6ec6622fd640f8ae2aff46bc2e3b6e6">Hotel,&nbsp;</li><li data-list-item-id="ee0e2b05c5dcca53d84e69986e0eec301">Propinas para el guía y el conductor</li><li data-list-item-id="e5de631515d01a36e9bf58f056fac2003">Excursiones opcionales</li><li data-list-item-id="eebc3a63adc6760f98d268bc5875c1aac">Cualquier otro gasto fuera del programa del tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 17: mt-lokon-volcano-trek
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '17', 'es', 'Trekking al Volcán Mt. Lokon', '<h2><strong>Explora el Cráter Activo: Experiencia de Trekking al Volcán Mt. Lokon</strong></h2><p>Vive la emoción de escalar uno de los volcanes activos más icónicos de Sulawesi del Norte. El <strong>Monte Lokon</strong> ofrece una auténtica aventura de trekking para quienes desean ser testigos del poder crudo de la naturaleza a través de su impresionante cráter sin una ascensión demasiado extrema.</p><h3><strong>Puntos Destacados del Tour:</strong></h3><ul><li><strong>Exploración del Cráter Tompaluan:</strong> Sigue un sendero de 2 horas que conduce al borde del <strong>Cráter Tompaluan</strong>. Aquí podrás observar la actividad volcánica desde una distancia segura pero lo suficientemente cercana como para sentir su magnificencia.</li><li><strong>Panorama de la Ciudad de Tomohon:</strong> Disfruta de las vistas refrescantes de la Ciudad de Tomohon desde las laderas de la montaña, ofreciendo una perspectiva diferente de la belleza natural de Minahasa.</li><li><strong>Un Desafío Equilibrado:</strong> A 1.580 metros sobre el nivel del mar, el camino hacia el cráter es perfecto tanto para principiantes como para excursionistas experimentados que buscan una actividad física matutina refrescante.</li><li><strong>Descanso &amp; Cocina Local:</strong> Después de tu trekking, hemos preparado un delicioso almuerzo en un restaurante local para concluir perfectamente tu aventura.</li></ul>', '<ul><li data-list-item-id="e9e914bf2ff11c00c2a9db3b87ca22efe">Transporte totalmente con aire acondicionado según el número de participantes</li><li data-list-item-id="e680c0b8aea08452cbae884c6d5e2d572">Guía y conductor expertos</li><li data-list-item-id="ebca155750890997c3be20cf7a2196305">Entradas a las atracciones turísticas</li><li data-list-item-id="e8d8fd8ee171bb996d9ee4419d568d989">Estacionamiento</li><li data-list-item-id="e8b60764be181f21f1778af2b47681999">Almuerzo</li><li data-list-item-id="ec2d301ad37ffc7057334aefa9fe2257e">Una botella de agua mineral por persona</li><li data-list-item-id="e041e6dc48bc42dd9524a3df956c00c0c">Servicios turísticos según el programa</li></ul>', '<ul><li data-list-item-id="e97188319fb5536c010e7d1ddc597336f">Boleto de avión</li><li data-list-item-id="e23e09bdcb623c333c317c7b6299f8759">Impuesto aeroportuario</li><li data-list-item-id="e83a0664f8844283c0c4348456a9dfb3b">Mozos</li><li data-list-item-id="e1bd92c6b00cb5ea95a1c37639c97543e">Hotel</li><li data-list-item-id="ef148c59f0c1f718ac34fb13f0e1dbe4a">Propinas para el guía y el conductor</li><li data-list-item-id="e8cb793f90a845b4dfd6bf1f1b2b42a80">Excursiones opcionales</li><li data-list-item-id="e763128880b466113267e760ee5d194f5">Cualquier otro gasto fuera del programa del tour.</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 18: mt-mahawu-volcano-tetetana-hill
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '18', 'es', 'Volcán Mt. Mahawu &amp; Colina de Tetetana', '<h2><strong>Las Cumbres de Minahasa: Tour al Mt. Mahawu &amp; la Colina de Tetetana</strong></h2><p>Disfruta de la combinación perfecta entre una aventura ligera y panoramas naturales extraordinarios. Este paquete está diseñado para quienes desean experimentar la sensación de estar en la cima de un volcán y colinas exuberantes sin necesidad de una escalada agotadora.</p><h3><strong>¿Por Qué Elegir Este Tour?</strong></h3><ul><li><strong>Caminata Accesible para Todos:</strong> Explora el <strong>Monte Mahawu</strong> con acceso fácil. Hay aproximadamente 150 escalones de cemento con barandillas de seguridad, lo que facilita a cualquiera alcanzar la cima y ver su cráter único.</li><li><strong>Horizonte Tridimensional:</strong> Desde la cima del Mahawu, disfrutarás de vistas espectaculares de la Isla de Manado Tua, Bunaken y el extenso paisaje urbano de Manado.</li><li><strong>El Encanto de la Colina de Tetetana:</strong> Visita la <strong>Cima de Tetetana</strong>, el destino de moda más reciente en Tomohon. Aquí puedes contemplar simultáneamente cuatro regiones de Sulawesi del Norte desde un solo punto, rodeado de hermosos jardines de flores y aire fresco de montaña.</li><li><strong>Momentos Fotográficos Estéticos:</strong> Cada rincón de este viaje ofrece un fondo perfecto para Instagram, desde el exuberante camino de escalones hasta los jardines de flores en la colina.</li><li><strong>Deliciosa Cocina Local:</strong> Refréscate después de la exploración con un auténtico almuerzo local en un restaurante seleccionado.</li></ul>', '<ul><li data-list-item-id="ee0a07c9cb24323f7ce891a99fae8befb">Transporte totalmente con aire acondicionado según el número de participantes</li><li data-list-item-id="e2294b9fea85a5bb7b3c381229d996538">Guía y conductor expertos, entradas a las atracciones turísticas</li><li data-list-item-id="e91b0f8f940b1ae9746f796b2399f0b12">Estacionamiento</li><li data-list-item-id="e68c9ac84e6c7d75451eaf1e0bd591748">Almuerzo</li><li data-list-item-id="e1a2d571799de05d946edbf79052260d1">Una botella de agua mineral por persona</li><li data-list-item-id="eeeb894126a0e2667e1c122b8daf2a097">Servicios según el programa</li></ul>', '<ul><li data-list-item-id="ed040cc0dd81d42e795600e22a7bf6536">Boleto de avión</li><li data-list-item-id="eb2e43bfc1813f79cdda31725bf97dbad">Impuesto aeroportuario</li><li data-list-item-id="eec4c3bc7fb908919a5b66c97cde714e5">Mozos</li><li data-list-item-id="ef13b7599a238bc82e6bd5620370064d9">Hotel</li><li data-list-item-id="e7a50082855dcc93d44a0d8bbcef795bb">Propinas para el guía y el conductor</li><li data-list-item-id="e2a39ca8ecbefd244e7980a1f24d1bb28">Excursiones opcionales</li><li data-list-item-id="efae7355dae9278ce19d7a043661cdfd1">Otros gastos fuera del programa del tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 19: white-water-rafting
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '19', 'es', 'Rafting en Aguas Bravas', '<h2><strong>Domina los Rápidos: Aventura de Rafting en el Río Nimanga</strong></h2><p>¡Prepárate para la aventura acuática más emocionante de Sulawesi del Norte! Navega rápidos fluviales desafiantes rodeado de una belleza natural impresionante. Este paquete está perfectamente diseñado para quienes buscan una mezcla de desafío físico, emoción y exuberante paisaje tropical.</p><h3><strong>Puntos Destacados del Tour:</strong></h3><ul><li><strong>Los Desafiantes Rápidos de Nimanga:</strong> Vive la emoción de aproximadamente 90 minutos de rafting. Cada curva del río ofrece nuevas sorpresas y desafíos que harán latir tu corazón más rápido.</li><li><strong>El Paisaje del Pueblo de Timbukar:</strong> Ubicado en Sonder, la ruta de rafting ofrece vistas impresionantes de acantilados escarpados y densa vegetación a lo largo del prístino cauce del río.</li><li><strong>La Seguridad Primero:</strong> Antes de partir, recibirás una explicación de seguridad y un entrenamiento básico de remo. Estarás acompañado por dos guías profesionales de rafting durante todo el viaje.</li><li><strong>Equipo de Estándar Internacional:</strong> Garantizamos tu comodidad y seguridad proporcionando equipo de rafting de alta calidad (botes, cascos, chalecos salvavidas) que cumple con los estándares internacionales de seguridad.</li></ul><p><strong>«¡Desafía los rápidos, abraza la naturaleza salvaje, y domina con nosotros el Río Nimanga!»</strong></p>', '<ul><li data-list-item-id="e8f9892615252c1f7113eb1af6758e23d">Transporte totalmente con aire acondicionado según el número de participantes</li><li data-list-item-id="ea3a96d847da9f813d56ea1bf5e5091f0">Guía y conductor expertos</li><li data-list-item-id="e5f704714c2138eff93abd9ef0b451e7c">Equipo de rafting</li><li data-list-item-id="ebef7f400e0d2a286c3753c27ac6b35d5">Entradas a las atracciones turísticas</li><li data-list-item-id="ee7e8a9cdd869251eacb4fee991736ba1">Estacionamiento</li><li data-list-item-id="e51ee15f118665b0e2d33ac03bf6150d0">1 botella de agua mineral por persona</li><li data-list-item-id="e25c6d77eec5df59483c0f7d94f7d0753">Servicios según el programa</li></ul>', '<ul><li data-list-item-id="e64a5c48756da8949a84fc99be24bd499">Boleto de avión</li><li data-list-item-id="e0b3182e85d9f33acc157b85808347961">Impuesto aeroportuario</li><li data-list-item-id="e2cb5bdd5ecfc46fcb144d67bfbd8950f">Comidas</li><li data-list-item-id="ef1153321326a82f3288f350ea4e12772">Mozos</li><li data-list-item-id="e6657bb1483ae99b0ac50275b9a92fefa">Hotel</li><li data-list-item-id="e90f5a9e0c8775eae0dd396d234c2ca6e">Propinas para el guía y el conductor</li><li data-list-item-id="e1bc758f69c0ff547e5c8f8aca100c99e">Excursiones opcionales</li><li data-list-item-id="ed4f1470355a4f65f457a776a07b216c9">Otros gastos no mencionados en el programa del tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 20: minahasa-highland-tour
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '20', 'es', 'Tour del Altiplano de Minahasa', '<h2><strong>Encanto del Altiplano de Minahasa: Una Armonía entre Cultura &amp; Maravillas Naturales</strong></h2><p>Escapa del bullicio de la ciudad y respira el aire fresco de montaña en un viaje de un día completo por el Altiplano de Minahasa. Desde mercados tradicionales únicos hasta relajantes lagos de azufre, este paquete ofrece una mezcla perfecta de aventura cultural y relajación natural que no encontrarás en ningún otro lugar.</p><h3><strong>Puntos Destacados del Tour:</strong></h3><ul><li><strong>Colorida Ciudad de las Flores:</strong> Deleita tus ojos en el <strong>Taman Wisata Pelangi</strong> en Tomohon, un vibrante parque lleno de hermosas flores multicolores.</li><li><strong>Mercado Extremo de Tomohon:</strong> Vive la cultura local de primera mano en este icónico mercado tradicional, famoso por su variedad de carnes de animales salvajes — una experiencia única para los viajeros del mundo.</li><li><strong>Patrimonio &amp; Delicias Culinarias:</strong> Observa la preparación en vivo de pasteles tradicionales de Manado y descubre cómo se produce el licor local \'Cap Tikus\' en el bosque de palmeras de azúcar perfecto para Instagram de <strong>Tuur Maasering</strong>.</li><li><strong>Relajación junto al Lago &amp; Bukit Kasih:</strong> Disfruta del almuerzo junto al <strong>Lago Tondano</strong>, explora cráteres de azufre activos en <strong>Bukit Kasih</strong>, y termina tu día con café o té caliente junto a las aguas cambiantes del <strong>Lago Linow</strong>.</li></ul>', '<ul><li data-list-item-id="e3a6d5c7a95824505fcc7169d19c68b06">Transporte totalmente con aire acondicionado según el número de participantes</li><li data-list-item-id="eed59092e3fde448a5e5a4fb756ab6e44">Guía y conductor expertos</li><li data-list-item-id="e1fbf9e5db829006a3fc211fef7a86ec5">Entradas a las atracciones turísticas</li><li data-list-item-id="ec1827a81cbe7feb5e6c155dc5f41899e">Estacionamiento</li><li data-list-item-id="eb65edb1a96b3c032f8f825315f9c7209">Almuerzo</li><li data-list-item-id="e5971d7bd5ebcae0985b7b12074916355">Una botella de agua mineral por persona</li><li data-list-item-id="ef7e51ca1230476f54d606b374973afb1">Servicios turísticos según el programa</li></ul>', '<ul><li data-list-item-id="ed1003d6a37aa7b1fbafe39f48ba09598">Boleto de avión</li><li data-list-item-id="e9101a0e59598b6ff7f1e74ede3ede14f">Impuesto aeroportuario</li><li data-list-item-id="efd4176d12238c02b80f1e80ada630810">Mozos</li><li data-list-item-id="ea6ec6622fd640f8ae2aff46bc2e3b6e6">Hotel,&nbsp;</li><li data-list-item-id="ee0e2b05c5dcca53d84e69986e0eec301">Propinas para el guía y el conductor</li><li data-list-item-id="e5de631515d01a36e9bf58f056fac2003">Excursiones opcionales</li><li data-list-item-id="eebc3a63adc6760f98d268bc5875c1aac">Cualquier otro gasto fuera del programa del tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 21: bunaken-island-sightseeing-tour
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '21', 'es', 'Tour de Avistamiento de la Isla de Bunaken', '<h3><strong>Explora un Paraíso Submarino: Paquete Tour de la Isla de Bunaken</strong></h3><p>¡Prepárate para una aventura inolvidable en el <strong>Parque Marino de Bunaken</strong>, uno de los destinos de turismo marino más icónicos del mundo! Disfruta de la mezcla perfecta de vibrantes arrecifes de coral, aguas cristalinas y una relajante atmósfera de playa.</p><h3><strong>¿Por Qué Deberías Unirte a Este Tour?</strong></h3><ul><li><strong>El Nuevo Rostro de Bunaken:</strong> Visita el <strong>Nuevo Muelle Turístico de Bunaken</strong>, ahora más encantador y representativo — el mejor lugar para capturar fotos y videos estéticos con un impresionante fondo isleño.</li><li><strong>Maravillas Submarinas:</strong> Descubre miles de especies de peces tropicales y ecosistemas de arrecifes de coral bien preservados a través de actividades opcionales de snorkel o buceo.</li><li><strong>Relájate junto a la Orilla:</strong> Disfruta de tiempo libre para pasear por la playa o simplemente relajarte respirando el aire fresco del mar.</li><li><strong>Almuerzo a la Orilla del Mar:</strong> Vive la sensación de un delicioso almuerzo en un restaurante local ubicado justo al borde del agua.</li></ul>', '<ul><li data-list-item-id="e756cec54195116ff096865a21781571f"><p style="text-align:justify;">Barco privado a la isla de Bunaken</p></li><li data-list-item-id="e00ba750ae031939e7c8465d501457022"><p style="text-align:justify;">Guía turístico experto &amp; timonel</p></li><li data-list-item-id="ed4121d16075b5d5f88c9d38af15c2a27"><p style="text-align:justify;">Entradas a las atracciones turísticas</p></li><li data-list-item-id="e2332fcb6ed90ad0ae25b1e33e756583a"><p style="text-align:justify;">Almuerzo en un restaurante local</p></li><li data-list-item-id="ec3c758171f7de84f46c858a794205a03"><p style="text-align:justify;">Una botella de agua mineral por persona</p></li><li data-list-item-id="e8ced0664ba420cfbfb7f957585b5e359"><p style="text-align:justify;">Servicios turísticos según el itinerario</p></li></ul>', '<ul><li data-list-item-id="e64a5c48756da8949a84fc99be24bd499">Boleto de avión</li><li data-list-item-id="eeec1cfc460047b34d98ccaa46e7a7e79">Transporte terrestre (automóvil)</li><li data-list-item-id="e0b3182e85d9f33acc157b85808347961">Impuesto aeroportuario</li><li data-list-item-id="e2cb5bdd5ecfc46fcb144d67bfbd8950f">Comidas</li><li data-list-item-id="ef1153321326a82f3288f350ea4e12772">Mozos</li><li data-list-item-id="e6657bb1483ae99b0ac50275b9a92fefa">Hotel</li><li data-list-item-id="e90f5a9e0c8775eae0dd396d234c2ca6e">Propinas para el guía y el conductor</li><li data-list-item-id="e1bc758f69c0ff547e5c8f8aca100c99e">Excursiones opcionales</li><li data-list-item-id="ed4f1470355a4f65f457a776a07b216c9">Otros gastos no mencionados en el programa del tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 22: manado-city-tour-luch-with-manados-special-dishes
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '22', 'es', 'Tour de la Ciudad de Manado &amp; Almuerzo con los Platos Especiales de Manado', '<h2><strong>Explora los Encantos de Manado: Un Viaje a través de la Historia, el Sabor y el Horizonte</strong></h2><p>Vive un viaje de un día completo a través del tiempo y la naturaleza en el corazón de Sulawesi del Norte. Nuestro <strong>Tour de la Ciudad de Manado</strong> te invita a sumergirte en un rico patrimonio cultural perfectamente combinado con panoramas majestuosos desde las cimas de las colinas.</p><h3><strong>Puntos Destacados del Tour:</strong></h3><ul><li><strong>Lugares Históricos &amp; Culturales:</strong> Visita el <strong>Templo Ban Hin Kiong</strong>, un sitio histórico de 300 años, junto a la <strong>Iglesia de Sentrum</strong> y el <strong>Monumento de la Segunda Guerra Mundial</strong>.</li><li><strong>Maravillas Icónicas:</strong> Contempla la grandeza del <strong>Monumento de Jesús Bendiciendo</strong>, una estatua única "voladora" que sirve como símbolo de la ciudad.</li><li><strong>Sabores Auténticos:</strong> Deleita tu paladar con un almuerzo tradicional de <strong>Atún al Estilo Manado</strong>, rico en especias locales.</li><li><strong>Alturas Impresionantes:</strong> Termina tu día en la <strong>Colina de Makatete</strong>. Desde 200 metros sobre el nivel del mar, disfruta de vistas espectaculares de la Ciudad de Manado, el Monte Klabat y las impresionantes islas de Bunaken y Siladen.</li></ul>', '<ul><li data-list-item-id="efa0326736a93dbe5b6f2f4886719f0ae"><p style="text-align:justify;">Transporte con aire acondicionado según el número de participantes</p></li><li data-list-item-id="e6f7c213ce63967da3a7674f798318146"><p style="text-align:justify;">Guía experto (de habla inglesa) &amp; conductor</p></li><li data-list-item-id="e31e949b88b66a13c31a285d2ea0fe01b"><p style="text-align:justify;">Entradas &amp; estacionamiento</p></li><li data-list-item-id="e5d9e0c346d759e5a38f90442bd7731c9"><p style="text-align:justify;">Almuerzo en un restaurante local</p></li><li data-list-item-id="e7b7a00f1ee67b67ec041223e00f34a09"><p style="text-align:justify;">Una botella de agua mineral por persona</p></li><li data-list-item-id="e364d522edd138b4fa0906d7379169caa"><p style="text-align:justify;">Servicios turísticos según el programa</p></li></ul>', '<ul><li data-list-item-id="e64a5c48756da8949a84fc99be24bd499">Boleto de avión</li><li data-list-item-id="e0b3182e85d9f33acc157b85808347961">Impuesto aeroportuario</li><li data-list-item-id="e2cb5bdd5ecfc46fcb144d67bfbd8950f">Comidas</li><li data-list-item-id="ef1153321326a82f3288f350ea4e12772">Mozos</li><li data-list-item-id="e6657bb1483ae99b0ac50275b9a92fefa">Hotel</li><li data-list-item-id="e90f5a9e0c8775eae0dd396d234c2ca6e">Propinas para el guía y el conductor</li><li data-list-item-id="e1bc758f69c0ff547e5c8f8aca100c99e">Excursiones opcionales</li><li data-list-item-id="ed4f1470355a4f65f457a776a07b216c9">Otros gastos no mencionados en el programa del tour</li></ul>', NOW(), NOW())
