-- paket 23: 6d5n-tangkoko-adventure-tour
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '23', 'es', '6 Días Tour de Aventura en Tangkoko', '<h2><strong>La Odisea Definitiva de Sulawesi del Norte: Una Gran Aventura de 6 Días a través de Bosques Tropicales &amp; Paraísos Submarinos</strong></h2><p>¡Explora el lado salvaje y hermoso de Sulawesi del Norte con nuestro paquete de expedición más completo! La <strong>Aventura 6D5N en Tangkoko</strong> es mucho más que unas vacaciones; es un viaje épico que combina maravillas terrestres, altiplanos majestuosos y la belleza marina mundialmente famosa de Bunaken. Diseñado para quienes buscan una aventura auténtica y sin límites.</p><h3><strong>Puntos Destacados del Tour:</strong></h3><ul><li><strong>Expedición en la Selva de Tangkoko:</strong> Pasa dos noches en el corazón de Tangkoko en una misión para encontrar fauna salvaje rara — desde el adorable <strong>Tarsio</strong> hasta las exclusivas tropas de <strong>Macacos Negros Crestados</strong>.</li><li><strong>La Maravilla de la Cascada de Tunan:</strong> Sé testigo del poder crudo de la naturaleza en una cascada de 86 metros escondida en lo profundo de un bosque prístino e intacto.</li><li><strong>Encanto del Altiplano de Minahasa:</strong> Respira el aire fresco de Tomohon, explora el cráter del <strong>Volcán Mahawu</strong>, y encuentra serenidad en el <strong>Lago Linow</strong>, famoso por sus aguas que cambian en tres colores.</li><li><strong>Antiguo Patrimonio Cultural:</strong> Retrocede en el tiempo con una visita a <strong>Waruga Sawangan</strong>, un antiguo sitio de tumbas megalíticas rico en historia.</li><li><strong>Paraíso Marino de Bunaken:</strong> Concluye tu viaje con total relajación en la Isla de Bunaken. Haz snorkel o buceo entre paredes de coral gigantes y miles de vibrantes peces tropicales.</li></ul>', '<ul><li data-list-item-id="e003cb081df381c6177f6f6ea22e70670">Transporte con aire acondicionado&nbsp;</li><li data-list-item-id="e0d5c6e19f840ce309c7c0f35dcfac3f4">Barco privado a la isla de Bunaken</li><li data-list-item-id="e4364960109bee572d3a8d9cae7ce2e96">Estancia de 5 noches en hotel, ocupación doble</li><li data-list-item-id="e406c6b2a303d8fc371e9e36db30336f9">Guía experto &amp; conductor</li><li data-list-item-id="ea83df9e88b4d60410713905d99b0773e">Entradas a las atracciones turísticas &amp; estacionamiento</li><li data-list-item-id="ea0513d38795aacb231a0d76a6e389665">Comidas según el programa del tour</li><li data-list-item-id="e1d347a24ac609ef4c151d1e191962bad">Servicios turísticos según el programa</li><li data-list-item-id="e03a02e72cc81325190c8b5844feec80c">Una botella de agua mineral por persona al día</li><li data-list-item-id="e38650055baf01af92b30e8be7c0377e6">Servicio de recepción</li></ul>', '<ul><li data-list-item-id="eb5eba377a627536111f5daaf42cb875e">Boleto de avión de ida y vuelta</li><li data-list-item-id="e9871e63b9fbb46e8e849ba04f66112b4">Propinas para el guía &amp; el conductor</li><li data-list-item-id="e141f97d4f43b25648e15d80a691fd2d7">Excursiones opcionales</li><li data-list-item-id="ecbb5c50e20d10d1311cd91fb730a72f6">Gastos adicionales fuera del paquete (comidas/bebidas adicionales, etc.)</li><li data-list-item-id="ed9e6b7e4a9ad9f99209d34216e79ff72">Mozos, impuesto aeroportuario &amp; exceso de equipaje</li><li data-list-item-id="ee8836b89a60e07a22d2e2038bc73b07d">Gastos personales (lavandería, minibar, servicio a la habitación, etc.)</li><li data-list-item-id="e5dda5c1a16091383138fef6dd26df6ee">Seguro de viaje</li><li data-list-item-id="ed1693c3ccea40a446251d042c65b75e9">Otros gastos fuera del programa del tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 24: tangkoko-adventure-4d3n
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '24', 'es', '4 Días Aventura en Tangkoko', '<h2><strong>La Expedición Definitiva a Tangkoko: Una Gran Aventura de 4 Días en la Naturaleza Salvaje de Sulawesi</strong></h2><p>¿Estás listo para tu propia experiencia "National Geographic"? La <strong>Aventura 4D3N en Tangkoko</strong> es un viaje inmersivo que te lleva a lo profundo del bosque tropical prístino para conocer algunas de las criaturas más únicas de la Tierra. Desde el rugido de cascadas escondidas hasta la mirada del icónico Tarsio, esta aventura es un sueño para todo amante de la naturaleza y fotógrafo.</p><h3><strong>Puntos Destacados del Tour:</strong></h3><ul><li><strong>La Maravilla de la Cascada de Tunan:</strong> Comienza tu viaje en la Cascada de Tunan en el Pueblo de Talawan. Siente la fresca bruma de una cascada de 86 metros escondida en un bosque prístino e intacto.</li><li><strong>Misión para Encontrar "la Gran Estrella":</strong> Emprende una caminata por la tarde para encontrar la estrella principal del parque: el <strong>Tarsio</strong>, el primate más pequeño del mundo, que solo emerge al atardecer.</li><li><strong>Exploración de la Fauna Endémica:</strong> Pasa suficiente tiempo en la Reserva Natural de Tangkoko para observar al <strong>Macaco Negro Crestado</strong>, Osos Cuscús, y la mayor densidad de Cálaos del mundo.</li><li><strong>Expedición en la Selva Profunda:</strong> Con una duración de 4 días, tienes la mejor oportunidad de explorar rincones escondidos del bosque a través de caminatas matutinas y de tarde guiadas por expertos.</li><li><strong>Vida Auténtica de Pueblo:</strong> Vive la genuina hospitalidad local con una estancia en el Pueblo de Batu Putih, ofreciendo un descanso pacífico acompañado por los sonidos de la naturaleza.</li></ul>', '<ul><li data-list-item-id="ef32c0bfe5795561b9ab193cd44c60a01">Transporte con aire acondicionado según el número de participantes</li><li data-list-item-id="e8b6758ced173cafd33eeb47088587315">2 noches en Tangkoko &amp; 1 noche en Tomohon (cama doble/twin)</li><li data-list-item-id="e3b802aad9f6aaa8677df1b6542b2b753">Conductor &amp; guía expertos</li><li data-list-item-id="e0430266106efc4c83295f481a66a272e">Guardaparques en el parque natural de Tangkoko</li><li data-list-item-id="e6263d3892d15802d1cdbba1e1483fc4b">Entradas a las atracciones &amp; estacionamiento</li><li data-list-item-id="e41e80b8e04edeabc44a8949d6f46e507">Comidas según el itinerario del tour</li><li data-list-item-id="e9424305b5471b1307a625f1e394473d3">Servicios turísticos según el programa</li><li data-list-item-id="e5160d2919b1850eff838c550505ea428">2 botellas de agua mineral al día</li><li data-list-item-id="e7c5227391081bd816bd247709adc2fb1">Servicio de recepción</li></ul>', '<ul><li data-list-item-id="eab8e19d9005d7b92a3b55f83e6c406d5">Boleto de avión de ida y vuelta</li><li data-list-item-id="ec89859e61ce5257e8ce597e8b9ed8f95">Propinas para el conductor &amp; el guía</li><li data-list-item-id="eef1817701ed7d1b37d70094c2cf03414">Excursiones opcionales</li><li data-list-item-id="ecc81655adf3b9e759353573a80d75f4b">Gastos fuera del paquete (comidas/bebidas adicionales, etc.)</li><li data-list-item-id="e36914624471dc30595049484fcb9c27e">Mozos, impuesto aeroportuario &amp; exceso de equipaje</li><li data-list-item-id="e0d1bbfc33f8e55265033264d9643f777">Gastos personales (lavandería, minibar, servicio a la habitación, etc.)</li><li data-list-item-id="e581cc90534790d4f6be55537e1415302">Seguro de viaje</li><li data-list-item-id="ee3f094b58737eb29f43eb8a3427ef690">Y otros gastos fuera del programa del tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 25: tangkoko-adventure-3d2n
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '25', 'es', '3 Días Aventura en Tangkoko', '<h2><strong>Odisea de Fauna Salvaje &amp; Volcanes: Un Viaje Épico de 3 Días al Corazón de Tangkoko</strong></h2><p>¡Prepara tu alma aventurera para un viaje profundo a una de las reservas naturales más únicas del mundo! El paquete <strong>3D2N Aventura en Tangkoko</strong> está diseñado para verdaderos amantes de la naturaleza que desean ver fauna endémica rara en su hábitat natural, mientras disfrutan de la majestuosidad de los cráteres volcánicos y la sabiduría cultural de Minahasa.</p><h3><strong>Puntos Destacados del Tour:</strong></h3><ul><li><strong>Cima del Cráter de Mahawu:</strong> Disfruta de una breve caminata de 10 minutos hasta el borde del Monte Mahawu para ser testigo de panoramas espectaculares de Tomohon, Manado y las islas circundantes.</li><li><strong>Maravillas de la Fauna Endémica:</strong> Entra en la Reserva Natural de Tangkoko para conocer al <strong>Tarsio</strong> (el primate más pequeño del mundo), al <strong>Macaco Negro Crestado</strong> (mono negro autóctono), Osos Cuscús, y varias aves exóticas como Cálaos.</li><li><strong>Relajación en el Lago Tricolor:</strong> Relájate en las orillas del Lago Linow, famoso por sus aguas que cambian de color, mientras disfrutas de una tarde pacífica con una taza de café o té.</li><li><strong>Sendero del Patrimonio de Minahasa:</strong> Visita el Pueblo de Woloan, famoso por sus casas de madera tradicionales desmontables, y observa las antiguas tumbas megalíticas en Waruga Sawangan.</li><li><strong>Estancia entre la Naturaleza:</strong> Vive una auténtica pernoctación en la zona de Tangkoko, que te ofrece un acceso más cercano a la vibrante fauna salvaje del bosque tropical de Sulawesi.</li></ul>', '<ul><li data-list-item-id="eb8cd28a724737ab44cc88dd97a389dbe">Transporte con aire acondicionado según el número de participantes</li><li data-list-item-id="e9bac968587895ffae01f8d49356df8d4">2 noches en Tangkoko (cama doble/twin)</li><li data-list-item-id="e48aac6bce52fc7428359e501ff729bba">Conductor &amp; guía expertos</li><li data-list-item-id="ed9fed75b7d0562e8bdb0b2bc32232277">Guardaparques en el parque natural de Tangkoko</li><li data-list-item-id="efc3381224ecde3190b545ad3376102fe">Entradas a las atracciones &amp; estacionamiento</li><li data-list-item-id="e41e80b8e04edeabc44a8949d6f46e507">Comidas según el programa</li><li data-list-item-id="e6d5acca76e2686e9f57b3b7b6aaf5f65">Servicios turísticos según el programa</li><li data-list-item-id="ef45128991ca24a9ae216cd6a2ce70a4a">2 botellas de agua mineral al día</li><li data-list-item-id="ea837f120d87ebda8df3ec40c685d6f66">Servicio de recepción</li></ul>', '<ul><li data-list-item-id="e6b416fd5c6f77881ce45c46173dd1108">Boleto de avión de ida y vuelta</li><li data-list-item-id="ee0319e1248ebd87095dad0bfd8c7d9c9">Propinas para el conductor &amp; el guía</li><li data-list-item-id="eb78e7ef31eabb5138ac00798e975cc2f">&nbsp;Excursión opcional</li><li data-list-item-id="e7da4c8edc74e8fafda56c7e6740a2611">Gastos fuera del paquete (comidas/bebidas adicionales, etc.)</li><li data-list-item-id="ed04c16639d33ef42e9159fc2d3d121c5">Mozos, impuesto aeroportuario &amp; exceso de equipaje</li><li data-list-item-id="eefc6702e5083bfaff7b21c733acbf043">Gastos personales (lavandería, minibar, servicio a la habitación, etc.)</li><li data-list-item-id="e0f2b3f55047546e4fdbba7daadab0de1">Seguro de viaje</li><li data-list-item-id="ecc2d015d15e7b1ce5bbbd590e43ce691">Y otros gastos fuera del programa del tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 26: island-hopping-paradise-bunaken-siladen-nain-escape
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '26', 'es', 'Paraíso de Isla en Isla: Escape a Bunaken, Siladen &amp; Nain', '<h2 style="text-align:justify;"><strong>Paraíso de Isla en Isla: Escape a Bunaken, Siladen &amp; Nain&nbsp;</strong></h2><p style="text-align:justify;">Escapa al paraíso tropical de Sulawesi del Norte y vive una aventura inolvidable de isla en isla.<br>Descubre la belleza mundialmente famosa del <strong>Parque Marino de Bunaken</strong> con sus aguas cristalinas, coloridos arrecifes de coral y miles de peces tropicales nadando a tu alrededor.</p><p style="text-align:justify;">Continúa explorando la pacífica belleza de la <strong>Isla de Siladen</strong>, rodeada de impresionantes vistas del océano azul y una relajante atmósfera tropical.<br>Luego vive la belleza única del <strong>Banco de Arena de Nain</strong> — un paraíso escondido de arena blanca en medio del mar que aparece durante la marea baja y se convierte en el lugar perfecto para fotos de Instagram.</p><p style="text-align:justify;">Más que un simple recorrido, también podrás hacer snorkel, buceo, nadar mientras alimentas peces directamente con la mano, y sumergirte en la atmósfera insular tropical definitiva.</p><p style="text-align:justify;">¿Por qué elegir este viaje?<br>Porque en un solo viaje, vivirás la combinación perfecta de:<br><strong>agua cristalina + islas tropicales + paraíso submarino + vistas de arena blanca + experiencias marinas inolvidables</strong>, todo en un escape a la vez relajante y emocionante.</p><p style="text-align:justify;">Perfecto para ti si deseas:</p><ul><li><p style="text-align:justify;">Un escape tropical estéticamente perfecto</p></li><li><p style="text-align:justify;">Experiencias de snorkel &amp; recorridos de isla en isla</p></li><li><p style="text-align:justify;">Océano azul cristalino y la máxima sensación de renovación</p></li></ul><h3 style="text-align:justify;"><strong>Agua azul. Arena blanca. Atmósfera tropical infinita.</strong>&nbsp;</h3><p style="text-align:justify;">¿Listo para explorar el paraíso marino más hermoso de Manado?</p>', '<ul><li data-list-item-id="e873d778fd1724e641963f19753bd7153">Barco privado a 3 islas</li><li data-list-item-id="e7f8a545844508ac34789fff54c3bf4ec">Guía turístico experto &amp; timonel</li><li data-list-item-id="e837639ed702b4b3d563d754b9784f201">Entradas a las atracciones turísticas</li><li data-list-item-id="eb3047ce26dd07cba53731a349833c934">Estacionamiento</li><li data-list-item-id="e17952c91bc59d3bf5bd394db5c31eba2">Almuerzo</li><li data-list-item-id="e8b809428954656d954fcd1a9e186a600">1 botella de agua mineral por persona</li><li data-list-item-id="e8b6d227b6ff4563e99f57d10b0c0fa1b">Servicios turísticos según el itinerario</li></ul>', '<ul><li data-list-item-id="e8b156627fb0192d631973d4400759fd2">Transporte terrestre (automóvil)&nbsp;</li><li data-list-item-id="e64a5c48756da8949a84fc99be24bd499">Boletos de avión de ida y vuelta</li><li data-list-item-id="e0b3182e85d9f33acc157b85808347961">Impuesto aeroportuario</li><li data-list-item-id="e2cb5bdd5ecfc46fcb144d67bfbd8950f">Comidas</li><li data-list-item-id="ef1153321326a82f3288f350ea4e12772">Mozos</li><li data-list-item-id="e6657bb1483ae99b0ac50275b9a92fefa">Hotel</li><li data-list-item-id="e90f5a9e0c8775eae0dd396d234c2ca6e">Propinas para el guía y el conductor</li><li data-list-item-id="e1bc758f69c0ff547e5c8f8aca100c99e">Excursiones opcionales</li><li data-list-item-id="ed4f1470355a4f65f457a776a07b216c9">Otros gastos no mencionados en el programa del tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 27: mount-soputan-trekking-experience
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '27', 'es', 'Experiencia de Trekking al Monte Soputan', '<h2 style="text-align:justify;">Aventura de Trekking al Volcán Monte Soputan</h2><p style="text-align:justify;">Vive la emoción de explorar uno de los paisajes volcánicos más espectaculares de Sulawesi del Norte, en una aventura que te lleva mucho más allá del sendero turístico habitual. Rodeado de naturaleza intacta, un escenario montañoso dramático y panoramas impresionantes, este viaje ofrece una experiencia al aire libre verdaderamente auténtica para quienes buscan naturaleza, aventura y descubrimiento.</p><p style="text-align:justify;">A medida que te aventuras más profundamente en el altiplano, encontrarás una combinación fascinante de bosques tropicales, vastos paisajes abiertos y un terreno volcánico accidentado, formado por siglos de actividad geológica. El paisaje en constante cambio crea una sensación de exploración y emoción, haciendo de cada paso parte de la aventura.</p><p style="text-align:justify;">Lo que hace que esta experiencia sea verdaderamente especial es la oportunidad de ser testigo del poder crudo y la belleza de un volcán activo mientras disfrutas de algunas de las vistas montañosas más impresionantes de Sulawesi del Norte. Lejos de los destinos turísticos concurridos, el Monte Soputan ofrece un escape pacífico y gratificante para los viajeros que aprecian la naturaleza en su forma más pura.</p><p style="text-align:justify;">Ya sea que seas un entusiasta de la aventura, fotógrafo, o simplemente busques una experiencia al aire libre única, este viaje de trekking promete recuerdos inolvidables y paisajes extraordinarios que pocos visitantes tienen la oportunidad de experimentar.</p><h3 style="text-align:justify;">Por Qué Amarás Este Tour</h3><p style="text-align:justify;">✅ Escala uno de los volcanes activos más icónicos de Sulawesi del Norte<br>✅ Disfruta de panoramas espectaculares de montañas, valles y paisajes volcánicos<br>✅ Vive terrenos diversos, incluyendo bosques tropicales, praderas y campos de lava<br>✅ Perfecto para amantes de la aventura, la naturaleza y fotógrafos<br>✅ Escapa de las multitudes y descubre una joya natural escondida<br>✅ Una de las experiencias de trekking más gratificantes de Sulawesi del Norte</p><h3 style="text-align:justify;"><strong>Si buscas un viaje que combine aventura, logro y una belleza natural impresionante, el Monte Soputan ofrece una experiencia inolvidable en uno de los entornos volcánicos más notables de Indonesia.</strong></h3>', '<ul><li data-list-item-id="ebd5f16f959211ad8d39562d748703cf6"><p style="text-align:justify;">Transporte con aire acondicionado según el número de participantes</p></li><li data-list-item-id="ebd2a4a0200f3a42f13270b474708c55f"><p style="text-align:justify;">Guía y conductor expertos</p></li><li data-list-item-id="ea5540f1e4a6b85032cac1556af6c1e67"><p style="text-align:justify;">Entradas a las atracciones turísticas</p></li><li data-list-item-id="ea7600709e3961af862f436ab5c48d340"><p style="text-align:justify;">Estacionamiento &amp; donativo&nbsp;</p></li><li data-list-item-id="e768ef758df3cfe68e0bef8f3aa45bebf"><p style="text-align:justify;">Una botella de agua mineral por persona&nbsp;</p></li><li data-list-item-id="e1f5a44dadf559c86177cde9fc918bc0b"><p style="text-align:justify;">Servicios turísticos según el programa</p></li></ul>', '<ul><li data-list-item-id="e64a5c48756da8949a84fc99be24bd499">Boleto de avión</li><li data-list-item-id="e0b3182e85d9f33acc157b85808347961">Impuesto aeroportuario</li><li data-list-item-id="e2cb5bdd5ecfc46fcb144d67bfbd8950f">Comidas</li><li data-list-item-id="ef1153321326a82f3288f350ea4e12772">Mozos</li><li data-list-item-id="e6657bb1483ae99b0ac50275b9a92fefa">Hotel</li><li data-list-item-id="e90f5a9e0c8775eae0dd396d234c2ca6e">Propinas para el guía y el conductor</li><li data-list-item-id="e1bc758f69c0ff547e5c8f8aca100c99e">Excursiones opcionales</li><li data-list-item-id="ed4f1470355a4f65f457a776a07b216c9">Otros gastos no mencionados en el programa del tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 28: 4-days-paradise-golf-lihaga-island-escape
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '28', 'es', '4 Días Paradise Golf &amp; Isla de Lihaga', '<h2 style="text-align:justify;">La Combinación Perfecta entre Golf, Ocio Insular y Relajación Tropical</h2><p style="text-align:justify;">Vive lo mejor de Sulawesi del Norte en un viaje único que combina golf de nivel campeonato, paisajes insulares prístinos y hospitalidad tropical relajante. Diseñado para viajeros que buscan más que unas simples vacaciones de golf, este paquete ofrece el equilibrio perfecto entre recreación, naturaleza y ocio.</p><p style="text-align:justify;">Pasa tus días disfrutando de golf de calidad rodeado de exuberantes paisajes tropicales y refrescantes brisas marinas, luego escapa a la espectacular belleza de la Isla de Lihaga, un paraíso escondido famoso por su arena blanca suave, aguas cristalinas y atmósfera pacífica.</p><p style="text-align:justify;">Lejos de los destinos turísticos concurridos, esta experiencia te permite reducir el ritmo y apreciar la belleza natural de Sulawesi del Norte a tu propio paso. Ya sea que estés jugando en un pintoresco campo de golf, relajándote en la playa, nadando en aguas turquesas, o simplemente disfrutando de la comodidad del resort, cada momento está diseñado para refrescar cuerpo y mente.</p><p style="text-align:justify;">Más que un simple paquete de golf, este viaje ofrece un escape tropical completo donde el deporte, la relajación y la aventura insular se combinan en una experiencia inolvidable.</p><h3 style="text-align:justify;">Por Qué Amarás Este Paquete</h3><p style="text-align:justify;">• Disfruta de una combinación única de experiencias de golf y escape insular</p><p style="text-align:justify;">• Juega golf en un hermoso entorno tropical rodeado de naturaleza</p><p style="text-align:justify;">• Visita las impresionantes playas de arena blanca de la Isla de Lihaga</p><p style="text-align:justify;">• Relájate en aguas cristalinas lejos de las zonas turísticas concurridas</p><p style="text-align:justify;">• Hospédate en un cómodo resort de golf con un entorno pacífico</p><p style="text-align:justify;">• Vive atracciones tanto terrestres como marinas en un solo paquete</p><p style="text-align:justify;">• Descubre uno de los destinos insulares más hermosos de Sulawesi del Norte</p><p style="text-align:justify;">• Crea recuerdos inolvidables en un paraíso tropical</p><h3 style="text-align:justify;">Puntos Destacados del Tour</h3><p style="text-align:justify;">• 3 Noches de Estancia en el Paradise Hotel &amp; Golf Resort</p><p style="text-align:justify;">• Experiencia de Golf de 18 Hoyos</p><p style="text-align:justify;">• Excursión en Bote Privado a la Isla de Lihaga</p><p style="text-align:justify;">• Escape a la Playa de Arena Blanca</p><p style="text-align:justify;">• Aguas Tropicales Cristalinas</p><p style="text-align:justify;">• Almuerzo de Mariscos Locales Frescos</p><p style="text-align:justify;">• Traslados al Aeropuerto de Ida y Vuelta Incluidos</p><p style="text-align:justify;">• Snorkel &amp; Actividades Marinas Opcionales</p><h3 style="text-align:justify;"><strong>Vive la combinación perfecta de golf, relajación y belleza insular tropical. Desde exuberantes calles hasta prístinas playas de arena blanca, cada día ofrece una nueva forma de disfrutar del encanto natural de Sulawesi del Norte.</strong></h3>', '<ul><li data-list-item-id="e85fcfeb6216e5a3f9b99dd3a6a7c929c">Traslado al aeropuerto</li><li data-list-item-id="e8de14905ae06a64f87cc60b7707f22d0">3 noches de alojamiento en el hotel seleccionado – habitación twin/doble</li><li data-list-item-id="eb71e5d213f9c14a6db516ba2d4f3f038">Green fee el día 2</li><li data-list-item-id="ed12068b91276f3e93b42223230f12673">Carrito de golf y tarifa de caddie (propina del caddie excluida) el día 2</li><li data-list-item-id="ed97e52152f7c86010c43d5fde2101b87">Barco privado a la isla de Lihaga</li><li data-list-item-id="ec02237fe232f55cc706fb1297ad87fad">Entradas a las atracciones turísticas &amp; estacionamiento</li><li data-list-item-id="e54ee6c6a6a0738fa1e15a08e280faef7">Guía turístico profesional el día 3</li><li data-list-item-id="e4bb6b6d5246389f96275d7a9a8a82136">Comidas según el programa</li></ul>', '<ul><li data-list-item-id="e3b523e8375ebb8c9d79946b95b626000">Boleto de avión de ida y vuelta</li><li data-list-item-id="ebb59df0fa48ba937a21926c9d7e1f3dd">Propinas para el guía &amp; el conductor</li><li data-list-item-id="e3ce39bff4df98057a82869976df231d7">Excursiones opcionales</li><li data-list-item-id="e3f219b92323c9770103f518bec22b1ba">Gastos personales fuera del paquete (comidas/bebidas adicionales, etc.)</li><li data-list-item-id="e11ba73fd8e73eef138f3ca4ad9edebf4">Servicio de mozos, impuesto aeroportuario &amp; exceso de equipaje</li><li data-list-item-id="ec1219e9200318981e942067b191d0e19">Gastos personales (lavandería, minibar, servicio a la habitación, etc.)</li><li data-list-item-id="eeb6d510ef8ff5842d69e6e91a30b5aa4">Seguro de viaje</li><li data-list-item-id="e0bf84136b233377c9c534be5adbe9757">Otros gastos no mencionados en el programa del tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 29: 4-days-paradise-golf-bunaken-escape
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '29', 'es', '4 Días Paradise Golf &amp; Bunaken', '<h2 style="text-align:justify;">Descubre el Mejor Golf y Paraíso Marino de Sulawesi del Norte</h2><p style="text-align:justify;">Vive la combinación perfecta de golf de nivel campeonato, relajación tropical y belleza marina mundialmente famosa en un viaje inolvidable. Diseñado para viajeros que buscan más que unas vacaciones tradicionales, este paquete combina la elegancia de un resort de golf premium con las asombrosas maravillas naturales de la Isla de Bunaken.</p><p style="text-align:justify;">Ubicado en la hermosa costa de Sulawesi del Norte, el Paradise Golf Resort ofrece una atmósfera relajante donde exuberantes calles se encuentran con refrescantes vistas al océano. Disfruta de una experiencia de golf memorable rodeada de paisajes tropicales, un entorno pacífico y la cálida hospitalidad que hace de Sulawesi del Norte un destino favorito para los viajeros de ocio.</p><p style="text-align:justify;">El viaje continúa hacia la legendaria Isla de Bunaken, hogar de algunos de los paisajes costeros y entornos marinos más espectaculares de Indonesia. Conocida por sus aguas cristalinas, su vibrante atmósfera tropical y sus impresionantes vistas al océano, Bunaken ofrece la oportunidad perfecta de vivir la belleza de Sulawesi del Norte más allá del campo de golf.</p><p style="text-align:justify;">Ya sea que estés disfrutando de una ronda de golf relajante, explorando el encanto costero de la isla, o simplemente relajándote en un entorno tropical, cada momento está diseñado para brindar comodidad, relajación y recuerdos inolvidables.</p><p style="text-align:justify;">Más que unas simples vacaciones, esta experiencia combina deporte, naturaleza y ocio en un escape tropical sin interrupciones.</p><h3 style="text-align:justify;">Por Qué Amarás Este Paquete</h3><p style="text-align:justify;">• Disfruta de una combinación única de golf y turismo marino</p><p style="text-align:justify;">• Juega golf en un entorno costero pintoresco rodeado de belleza tropical</p><p style="text-align:justify;">• Visita la mundialmente famosa Isla de Bunaken</p><p style="text-align:justify;">• Vive atracciones tanto terrestres como marinas en un solo viaje</p><p style="text-align:justify;">• Hospédate en cómodos hoteles y resorts con excelentes instalaciones</p><p style="text-align:justify;">• Relájate en una atmósfera tropical pacífica lejos de destinos concurridos</p><p style="text-align:justify;">• Equilibrio perfecto entre recreación, turismo y ocio</p><p style="text-align:justify;">• Descubre lo mejor de Sulawesi del Norte en un solo paquete completo</p><h3 style="text-align:justify;">Puntos Destacados del Tour</h3><p style="text-align:justify;">• 2 Noches de Estancia en el Paradise Hotel &amp; Golf Resort</p><p style="text-align:justify;">• 1 Noche de Estancia en un Hotel Seleccionado en Manado</p><p style="text-align:justify;">• Experiencia de Golf de 18 Hoyos</p><p style="text-align:justify;">• Green Fee, Carrito de Golf &amp; Caddie Incluido</p><p style="text-align:justify;">• Tour de Avistamiento de la Isla de Bunaken</p><p style="text-align:justify;">• Traslado en Bote a la Isla de Bunaken</p><p style="text-align:justify;">• Almuerzo de Pescado a la Parrilla Fresco con Dabu-Dabu de Manado</p><p style="text-align:justify;">• Actividades Opcionales de Snorkel &amp; Buceo</p><p style="text-align:justify;">• Traslado al Aeropuerto de Ida y Vuelta Incluido</p><h3 style="text-align:justify;">Sulawesi del Norte es uno de los pocos destinos donde puedes disfrutar de una experiencia de golf premium y explorar un paraíso marino mundialmente famoso en el mismo viaje. Desde exuberantes calles con vista al mar hasta la espectacular belleza de la Isla de Bunaken, este paquete ofrece un escape refrescante que combina relajación, aventura y paisajes tropicales inolvidables.</h3>', '<ul><li data-list-item-id="e85fcfeb6216e5a3f9b99dd3a6a7c929c">Traslado al aeropuerto</li><li data-list-item-id="e8de14905ae06a64f87cc60b7707f22d0">3 noches de alojamiento en el hotel seleccionado – habitación twin/doble</li><li data-list-item-id="eb71e5d213f9c14a6db516ba2d4f3f038">Green fee el día 2</li><li data-list-item-id="ed12068b91276f3e93b42223230f12673">Carrito de golf y tarifa de caddie (propina del caddie excluida) el día 2</li><li data-list-item-id="ed97e52152f7c86010c43d5fde2101b87">Barco privado a la isla de Bunaken</li><li data-list-item-id="ec02237fe232f55cc706fb1297ad87fad">Entradas a las atracciones turísticas &amp; estacionamiento</li><li data-list-item-id="e54ee6c6a6a0738fa1e15a08e280faef7">Guía turístico profesional el día 3</li><li data-list-item-id="e4bb6b6d5246389f96275d7a9a8a82136">Comidas según el programa</li></ul>', '<ul><li data-list-item-id="e3b523e8375ebb8c9d79946b95b626000">Boleto de avión de ida y vuelta</li><li data-list-item-id="ebb59df0fa48ba937a21926c9d7e1f3dd">Propinas para el guía &amp; el conductor</li><li data-list-item-id="e3ce39bff4df98057a82869976df231d7">Excursiones opcionales</li><li data-list-item-id="e3f219b92323c9770103f518bec22b1ba">Gastos personales fuera del paquete (comidas/bebidas adicionales, etc.)</li><li data-list-item-id="e11ba73fd8e73eef138f3ca4ad9edebf4">Servicio de mozos, impuesto aeroportuario &amp; exceso de equipaje</li><li data-list-item-id="ec1219e9200318981e942067b191d0e19">Gastos personales (lavandería, minibar, servicio a la habitación, etc.)</li><li data-list-item-id="eeb6d510ef8ff5842d69e6e91a30b5aa4">Seguro de viaje</li><li data-list-item-id="e0bf84136b233377c9c534be5adbe9757">Otros gastos no mencionados en el programa del tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 30: 4-days-paradise-golf-weekend-escape
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '30', 'es', '4 Días Escape de Golf de Fin de Semana en el Paraíso', '<h2 style="text-align:justify;">Un Relajante Escape de Golf en el Sulawesi del Norte Tropical</h2><p style="text-align:justify;">Escapa de la rutina y disfruta de unas refrescantes vacaciones de golf rodeado de la belleza natural de Sulawesi del Norte. Combinando golf de calidad, alojamiento cómodo en resort y una atmósfera tropical pacífica, este paquete está diseñado para viajeros que aprecian tanto la recreación como la relajación.</p><p style="text-align:justify;">Ubicado a lo largo de una costa pintoresca, el Paradise Golf Resort ofrece un entorno acogedor donde exuberantes calles, brisas marinas frescas y vistas panorámicas crean el escenario perfecto para una experiencia de golf inolvidable. Cada ronda se ve realzada por la tranquilidad del entorno, permitiéndote concentrarte en el juego mientras disfrutas de la belleza de la naturaleza.</p><p style="text-align:justify;">Más allá del campo, el resort ofrece un refugio cómodo donde los huéspedes pueden relajarse, recargar energías y disfrutar de un ritmo de vida más lento. Ya sea que viajes con compañeros de golf, amigos, colegas o familiares, este viaje ofrece el equilibrio ideal entre deporte y ocio.</p><p style="text-align:justify;">Con múltiples rondas de golf, instalaciones premium del resort y el encanto del paisaje tropical de Sulawesi del Norte, este paquete es perfecto para quienes buscan un escape de golf que va más allá de lo ordinario.</p><h3 style="text-align:justify;">Por Qué Amarás Este Paquete</h3><p style="text-align:justify;">• Disfruta de dos rondas de golf en un entorno tropical pintoresco</p><p style="text-align:justify;">• Hospédate en un cómodo resort de golf frente a la playa</p><p style="text-align:justify;">• Vive refrescantes brisas marinas y un hermoso entorno natural</p><p style="text-align:justify;">• Relájate y descansa lejos de la ajetreada vida de la ciudad</p><p style="text-align:justify;">• Traslados al aeropuerto convenientes incluidos</p><p style="text-align:justify;">• Actividades marinas opcionales disponibles en el resort</p><p style="text-align:justify;">• Una combinación ideal de deporte, comodidad y relajación</p><p style="text-align:justify;">• Descubre uno de los destinos de golf más agradables de Sulawesi del Norte</p><h3 style="text-align:justify;">Puntos Destacados del Tour</h3><p style="text-align:justify;">• 3 Noches de Estancia en el Paradise Hotel &amp; Golf Resort</p><p style="text-align:justify;">• 2 Rondas de Golf (36 Hoyos en Total)</p><p style="text-align:justify;">• Green Fee Incluido</p><p style="text-align:justify;">• Carrito de Golf &amp; Caddie Incluido</p><p style="text-align:justify;">• Traslados al Aeropuerto de Ida y Vuelta</p><p style="text-align:justify;">• Ambiente Pacífico del Resort Tropical</p><p style="text-align:justify;">• Actividades de Snorkel Opcionales</p><p style="text-align:justify;">• Experiencia Opcional en Bote de Fondo de Cristal</p><h3 style="text-align:justify;"><strong>Más que unas simples vacaciones de golf, la Paradise Golf Weekend Escape ofrece la oportunidad de disfrutar de golf de clase mundial en un entorno tropical tranquilo. Desde calles hermosamente cuidadas y refrescantes vistas al océano hasta noches relajantes en el resort, cada detalle está diseñado para crear un escape memorable y gratificante en Sulawesi del Norte.</strong></h3>', '<ul><li data-list-item-id="e85fcfeb6216e5a3f9b99dd3a6a7c929c">Traslado al aeropuerto</li><li data-list-item-id="e8de14905ae06a64f87cc60b7707f22d0">3 noches de alojamiento en el hotel seleccionado – habitación twin/doble</li><li data-list-item-id="eb71e5d213f9c14a6db516ba2d4f3f038">Green fee los días 2 &amp; 3</li><li data-list-item-id="ed12068b91276f3e93b42223230f12673">Carrito de golf y tarifa de caddie (propina del caddie excluida)&nbsp;</li><li data-list-item-id="e4bb6b6d5246389f96275d7a9a8a82136">Comidas según el programa</li></ul>', '<ul><li data-list-item-id="e3b523e8375ebb8c9d79946b95b626000">Boleto de avión de ida y vuelta</li><li data-list-item-id="ebb59df0fa48ba937a21926c9d7e1f3dd">Propinas para el guía &amp; el conductor</li><li data-list-item-id="e3ce39bff4df98057a82869976df231d7">Excursiones opcionales</li><li data-list-item-id="e3f219b92323c9770103f518bec22b1ba">Gastos personales fuera del paquete (comidas/bebidas adicionales, etc.)</li><li data-list-item-id="e11ba73fd8e73eef138f3ca4ad9edebf4">Servicio de mozos, impuesto aeroportuario &amp; exceso de equipaje</li><li data-list-item-id="ec1219e9200318981e942067b191d0e19">Gastos personales (lavandería, minibar, servicio a la habitación, etc.)</li><li data-list-item-id="eeb6d510ef8ff5842d69e6e91a30b5aa4">Seguro de viaje</li><li data-list-item-id="e0bf84136b233377c9c534be5adbe9757">Otros gastos no mencionados en el programa del tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 31: 3-days-paradise-golf-weekend-escape
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '31', 'es', '3 Días Escape de Golf de Fin de Semana en el Paraíso', '<h2 style="text-align:justify;">Donde el Gran Golf Se Encuentra con la Serenidad Tropical</h2><p style="text-align:justify;">Escapa a un destino donde el golf de nivel campeonato, el paisaje costero y la relajación tropical se combinan en perfecta armonía. Ubicado a lo largo de la hermosa costa de Sulawesi del Norte, el Paradise Golf Resort ofrece más que unas simples vacaciones de golf — brinda un refugio refrescante diseñado para recargar cuerpo y mente.</p><p style="text-align:justify;">Imagina despertar con aire marino fresco, caminar sobre exuberantes calles enmarcadas por paisajes tropicales, y disfrutar de cada golpe con un fondo de cielos azules y un entorno pacífico. Lejos de las ciudades concurridas y los horarios ajetreados, este es un lugar donde el tiempo se ralentiza y cada momento puede disfrutarse a tu propio ritmo.</p><p style="text-align:justify;">Ya sea que seas un golfista apasionado que busca un relajante escape de fin de semana o simplemente busques una experiencia de ocio única, el Paradise Golf Resort ofrece el escenario perfecto. Alojamiento cómodo, vistas pintorescas y una atmósfera acogedora crean un equilibrio ideal entre deporte, relajación y hospitalidad tropical.</p><p style="text-align:justify;">Más allá del campo de golf, los huéspedes pueden disfrutar del tranquilo entorno costero, relajarse en el resort, o elegir entre actividades marinas opcionales disponibles cerca. Cada elemento de este viaje está diseñado para ofrecer un escape memorable en uno de los destinos más pacíficos de Sulawesi del Norte.</p><h3 style="text-align:justify;">Por Qué Amarás Este Paquete</h3><p style="text-align:justify;">• Disfruta de unas relajantes vacaciones de golf en un hermoso entorno costero</p><p style="text-align:justify;">• Vive uno de los resorts de golf más agradables de Sulawesi del Norte</p><p style="text-align:justify;">• Juega en medio de un exuberante paisaje tropical y refrescantes brisas marinas</p><p style="text-align:justify;">• Hospédate en un resort pacífico lejos de las zonas turísticas concurridas</p><p style="text-align:justify;">• Equilibrio perfecto entre recreación y relajación</p><p style="text-align:justify;">• Traslados al aeropuerto convenientes incluidos</p><p style="text-align:justify;">• Actividades marinas opcionales para experiencias de ocio adicionales</p><p style="text-align:justify;">• Ideal para entusiastas del golf, parejas, amigos y grupos corporativos</p><h3 style="text-align:justify;">Puntos Destacados del Tour</h3><p style="text-align:justify;">• 2 Noches de Estancia en el Paradise Hotel &amp; Golf Resort</p><p style="text-align:justify;">• 1 Ronda de Golf (18 Hoyos)</p><p style="text-align:justify;">• Green Fee Incluido</p><p style="text-align:justify;">• Carrito de Golf &amp; Caddie Incluido</p><p style="text-align:justify;">• Traslados al Aeropuerto de Ida y Vuelta</p><p style="text-align:justify;">• Atmósfera de Resort Costero Tropical</p><p style="text-align:justify;">• Vistas Pintorescas del Campo de Golf</p><p style="text-align:justify;">• Actividades Opcionales de Snorkel &amp; Bote de Fondo de Cristal</p><h3 style="text-align:justify;"><strong>Más que una simple escapada corta, la Paradise Golf Weekend Escape es una oportunidad para reducir el ritmo, reconectar con la naturaleza y disfrutar de tiempo de calidad en un entorno tropical. Desde el momento de tu llegada hasta tu partida, vivirás la combinación perfecta de golf, comodidad y relajación que hace de Sulawesi del Norte un destino verdaderamente único.</strong></h3>', '<ul><li data-list-item-id="e85fcfeb6216e5a3f9b99dd3a6a7c929c">Traslado al aeropuerto</li><li data-list-item-id="e8de14905ae06a64f87cc60b7707f22d0">2 noches de alojamiento en el hotel seleccionado – habitación twin/doble</li><li data-list-item-id="eb71e5d213f9c14a6db516ba2d4f3f038">Green fee los días 2 &amp; 3</li><li data-list-item-id="ed12068b91276f3e93b42223230f12673">Carrito de golf y tarifa de caddie (propina del caddie excluida)&nbsp;</li><li data-list-item-id="e4bb6b6d5246389f96275d7a9a8a82136">Comidas según el programa</li></ul>', '<ul><li data-list-item-id="e3b523e8375ebb8c9d79946b95b626000">Boleto de avión de ida y vuelta</li><li data-list-item-id="ebb59df0fa48ba937a21926c9d7e1f3dd">Propinas para el guía &amp; el conductor</li><li data-list-item-id="e3ce39bff4df98057a82869976df231d7">Excursiones opcionales</li><li data-list-item-id="e3f219b92323c9770103f518bec22b1ba">Gastos personales fuera del paquete (comidas/bebidas adicionales, etc.)</li><li data-list-item-id="e11ba73fd8e73eef138f3ca4ad9edebf4">Servicio de mozos, impuesto aeroportuario &amp; exceso de equipaje</li><li data-list-item-id="ec1219e9200318981e942067b191d0e19">Gastos personales (lavandería, minibar, servicio a la habitación, etc.)</li><li data-list-item-id="eeb6d510ef8ff5842d69e6e91a30b5aa4">Seguro de viaje</li><li data-list-item-id="e0bf84136b233377c9c534be5adbe9757">Otros gastos no mencionados en el programa del tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 32: 5-days-bangka-archipelago-diving-escape
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '32', 'es', '5 Días Escape de Buceo en el Archipiélago de Bangka', '<h2 style="text-align:justify;">Descubre el Paraíso de Buceo Escondido de Sulawesi del Norte</h2><p style="text-align:justify;">Escapa a uno de los destinos submarinos más notables de Sulawesi del Norte, donde vibrantes jardines de coral, dramáticos paisajes submarinos y una extraordinaria biodiversidad marina se combinan en una experiencia de buceo verdaderamente inolvidable.</p><p style="text-align:justify;">Ubicado entre el mundialmente famoso Parque Marino de Bunaken y el legendario Estrecho de Lembeh, el Archipiélago de Bangka ofrece una combinación única de espectacular buceo de pared, coloridos arrecifes de coral y fascinante vida marina macro. Esta rara mezcla crea un patio de recreo submarino que atrae tanto a buceadores experimentados como a quienes descubren por primera vez las maravillas del mundo marino de Indonesia.</p><p style="text-align:justify;">Rodeado de aguas cristalinas e islas tropicales prístinas, Bangka es hogar de una increíble variedad de entornos de buceo. Explora imponentes pináculos submarinos, paredes de arrecife empinadas, cavernas escondidas, praderas marinas y vibrantes jardines de coral rebosantes de vida. Cada inmersión revela algo diferente, desde bancos de peces tropicales y tortugas marinas hasta especies macro raras buscadas por fotógrafos submarinos de todo el mundo.</p><p style="text-align:justify;">Más allá del buceo, disfruta de la tranquilidad de la vida insular en un resort frente a la playa donde impresionantes atardeceres, frescas brisas marinas y un entorno pacífico crean la atmósfera perfecta para relajarse entre inmersiones.</p><p style="text-align:justify;">Con fácil acceso a numerosos sitios de buceo de clase mundial y algunos de los ecosistemas marinos más ricos de Indonesia, el Archipiélago de Bangka ofrece un escape inolvidable para quienes buscan aventura bajo la superficie y serenidad sobre ella.</p><h3 style="text-align:justify;">Por Qué Amarás Este Paquete</h3><p style="text-align:justify;">• Explora uno de los secretos de buceo mejor guardados de Sulawesi del Norte</p><p style="text-align:justify;">• Vive la combinación única entre buceo de pared al estilo Bunaken y muck diving al estilo Lembeh</p><p style="text-align:justify;">• Descubre vibrantes arrecifes de coral y excepcional biodiversidad marina</p><p style="text-align:justify;">• Sumérgete entre pináculos submarinos, paredes de arrecife, cavernas y pendientes arenosas</p><p style="text-align:justify;">• Hospédate en un pacífico resort de buceo frente a la playa</p><p style="text-align:justify;">• Accede a numerosos sitios de buceo ubicados a solo minutos del resort</p><p style="text-align:justify;">• Ideal para los entusiastas de la fotografía submarina</p><p style="text-align:justify;">• Disfruta de un equilibrio perfecto entre aventura y relajación insular</p><h3 style="text-align:justify;"><strong>Más que unas simples vacaciones de buceo, la Exploración del Archipiélago de Bangka es la oportunidad de vivir uno de los entornos marinos más diversos de Indonesia. Desde coloridos jardines de coral y dramáticos paisajes submarinos hasta el pacífico encanto de un refugio insular tropical, cada momento está diseñado para dejarte inspirado por la belleza de Sulawesi del Norte.</strong></h3>', '<ul><li data-list-item-id="eebc7b4e396e8f7cf17ef8a660054c9c3"><p style="text-align:justify;">Traslado al aeropuerto&nbsp;</p></li><li data-list-item-id="e07c8a95ee6f8b05f18abc3c068904131"><p style="text-align:justify;">Habitación (ocupación doble – camas doble/twin)</p></li><li data-list-item-id="ea72b4950372c034d71b5bc788568f7af"><p style="text-align:justify;">Comidas en pensión completa</p></li><li data-list-item-id="e9a36fb5e11ed7803755e801175a21ca7"><p style="text-align:justify;">Paquete de pensión completa (basado en 2 inmersiones matutinas por día durante 3 días de inmersión)</p></li></ul>', '<ul><li data-list-item-id="ec756b43cc417da86cc09e4d40b5fccf2">Alquiler de equipo</li><li data-list-item-id="e18ed9b2769f68528af4b1df7bdda657a">Recargas de nitrox</li><li data-list-item-id="e652fe22505f77dc5bb8cba9be6dee4a2">Inmersiones nocturnas &amp; del pez mandarín</li><li data-list-item-id="ec89e22491c828ef51748a289e4e276f7">Excursiones &amp; actividades opcionales</li><li data-list-item-id="ecb84cba1c33800eb790ef4ec86aa3847">Gastos personales</li><li data-list-item-id="e8eb11ebbeab17718fad53293458bf0da">Impuesto aeroportuario &amp; exceso de equipaje</li><li data-list-item-id="e973813f562b295b4abff7069d5a3fe14">Seguro de viaje</li><li data-list-item-id="e415d746c3ce9f9f2b62c339ce9d53907">Cualquier servicio no mencionado anteriormente</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 33: 5-days-diving-the-wonders-of-lembeh-strait
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '33', 'es', '5 Días Buceando las Maravillas del Estrecho de Lembeh', '<h2 style="text-align:justify;">Explora el Destino de Buceo Macro Más Fascinante del Mundo</h2><p style="text-align:justify;">Descubre un mundo submarino sin igual en la Tierra. Famoso entre buceadores, biólogos marinos y fotógrafos submarinos, el Estrecho de Lembeh es ampliamente considerado el principal destino mundial para el muck diving y encuentros con vida marina rara.</p><p style="text-align:justify;">Bajo sus aguas tranquilas se esconde un universo donde prosperan algunas de las criaturas más extraordinarias del océano. Desde esquivos peces sapo y delicados caballitos de mar hasta coloridos nudibranquios y extrañas criaturas rara vez vistas en otro lugar, cada inmersión revela algo inesperado y notable.</p><p style="text-align:justify;">Lo que hace a Lembeh verdaderamente especial no es el tamaño de su vida marina, sino su increíble diversidad. El fondo marino de arena negra volcánica crea un ecosistema único que atrae una asombrosa variedad de especies macro, convirtiendo cada descenso en una emocionante búsqueda de tesoros bajo la superficie.</p><p style="text-align:justify;">Ya sea que seas un fotógrafo submarino experimentado, un apasionado de la fotografía macro, o simplemente sientas curiosidad por el lado escondido del océano, Lembeh ofrece una experiencia de buceo tan cautivadora como inolvidable. Con condiciones tranquilas, perfiles de inmersión sencillos y sitios de buceo de clase mundial a solo minutos del resort, es el destino perfecto para reducir el ritmo, observar la naturaleza y apreciar la extraordinaria belleza de las pequeñas cosas.</p><p style="text-align:justify;">Más allá del buceo, disfruta de la atmósfera pacífica de un refugio insular tropical donde atardeceres espectaculares, frescas brisas marinas y cálida hospitalidad complementan perfectamente tus aventuras submarinas.</p><h3 style="text-align:justify;">Por Qué Amarás Este Paquete</h3><p style="text-align:justify;">• Sumérgete en uno de los destinos de muck diving más famosos del mundo</p><p style="text-align:justify;">• Encuentra criaturas marinas raras y fascinantes que no se encuentran en otro lugar</p><p style="text-align:justify;">• Perfecto para los entusiastas de la fotografía submarina y la vida marina</p><p style="text-align:justify;">• Explora ecosistemas únicos de arena negra volcánica</p><p style="text-align:justify;">• Disfruta de condiciones de buceo tranquilas adecuadas para varios niveles de experiencia</p><p style="text-align:justify;">• Hospédate en un cómodo resort de buceo frente a la playa</p><p style="text-align:justify;">• Vive un destino celebrado por buceadores de todo el mundo</p><p style="text-align:justify;">• Combina aventura, relajación y descubrimiento marino en un solo viaje</p><h3 style="text-align:justify;"><strong>Más que unas simples vacaciones de buceo, Buceando las Maravillas del Estrecho de Lembeh es la oportunidad de explorar uno de los ecosistemas submarinos más extraordinarios del planeta. Cada inmersión ofrece un nuevo descubrimiento, cada encuentro cuenta una historia, y cada momento te acerca más a la notable biodiversidad que ha hecho de Lembeh un destino legendario entre los buceadores de todo el mundo.</strong></h3>', '<ul><li data-list-item-id="eebc7b4e396e8f7cf17ef8a660054c9c3"><p style="text-align:justify;">Traslado al aeropuerto&nbsp;</p></li><li data-list-item-id="e07c8a95ee6f8b05f18abc3c068904131"><p style="text-align:justify;">Habitación (ocupación doble – camas doble/twin)</p></li><li data-list-item-id="ea72b4950372c034d71b5bc788568f7af"><p style="text-align:justify;">Comidas en pensión completa</p></li><li data-list-item-id="e9a36fb5e11ed7803755e801175a21ca7"><p style="text-align:justify;">Paquete de pensión completa (basado en 2 inmersiones matutinas por día durante 3 días de inmersión)</p></li></ul>', '<ul><li data-list-item-id="ec756b43cc417da86cc09e4d40b5fccf2">Alquiler de equipo</li><li data-list-item-id="e18ed9b2769f68528af4b1df7bdda657a">Recargas de nitrox</li><li data-list-item-id="e652fe22505f77dc5bb8cba9be6dee4a2">Inmersiones nocturnas &amp; del pez mandarín</li><li data-list-item-id="ec89e22491c828ef51748a289e4e276f7">Excursiones &amp; actividades opcionales</li><li data-list-item-id="ecb84cba1c33800eb790ef4ec86aa3847">Gastos personales</li><li data-list-item-id="e8eb11ebbeab17718fad53293458bf0da">Impuesto aeroportuario &amp; exceso de equipaje</li><li data-list-item-id="e973813f562b295b4abff7069d5a3fe14">Seguro de viaje</li><li data-list-item-id="e415d746c3ce9f9f2b62c339ce9d53907">Cualquier servicio no mencionado anteriormente</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 34: 5-days-bunaken-tangkoko-nature-escape
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '34', 'es', '5 Días Escape a la Naturaleza de Bunaken &amp; Tangkoko', '<h2 style="text-align:justify;">Explora Sulawesi del Norte Sobre y Bajo la Superficie</h2><p style="text-align:justify;">Descubre un viaje que combina dos de los mayores tesoros naturales de Sulawesi del Norte — el espectacular mundo submarino del Parque Marino de Bunaken y la extraordinaria vida salvaje de la Reserva Natural de Tangkoko.</p><p style="text-align:justify;">Esta aventura única está diseñada para viajeros que buscan más que unas simples vacaciones de buceo. Bajo las aguas cristalinas de Bunaken se esconde uno de los ecosistemas marinos más celebrados del mundo, donde dramáticas paredes de coral, vibrantes arrecifes, tortugas marinas e innumerables peces tropicales crean una experiencia submarina inolvidable.</p><p style="text-align:justify;">Más allá del océano, la aventura continúa en los exuberantes bosques tropicales de Tangkoko, uno de los santuarios de vida salvaje más importantes de Indonesia. Aquí, los entusiastas de la naturaleza tienen la rara oportunidad de observar algunas de las especies endémicas más icónicas de Sulawesi, incluyendo al fascinante Tarsio, el Macaco Negro Crestado, Cálaos y Cuscús en su hábitat natural.</p><p style="text-align:justify;">Desde coloridos jardines de coral y una asombrosa biodiversidad marina hasta bosques tropicales llenos de fauna única, este viaje muestra la increíble diversidad que hace de Sulawesi del Norte uno de los destinos más notables de Indonesia.</p><p style="text-align:justify;">Ya sea que seas buceador, entusiasta de la vida salvaje, fotógrafo o amante de la naturaleza, esta experiencia ofrece la combinación perfecta de exploración marina, descubrimiento del bosque tropical y relajación tropical.</p><h3 style="text-align:justify;">Por Qué Amarás Este Paquete</h3><p style="text-align:justify;">• Vive dos de las atracciones naturales más icónicas de Sulawesi del Norte en un solo viaje</p><p style="text-align:justify;">• Sumérgete en el mundialmente famoso Parque Marino de Bunaken</p><p style="text-align:justify;">• Encuentra tortugas marinas, paredes de coral y vibrante biodiversidad marina</p><p style="text-align:justify;">• Explora el bosque tropical de la Reserva Natural de Tangkoko</p><p style="text-align:justify;">• Observa fauna endémica rara que solo se encuentra en Sulawesi</p><p style="text-align:justify;">• Ideal para los entusiastas de la fotografía submarina y de vida salvaje</p><p style="text-align:justify;">• Combina aventura marina con exploración del bosque tropical</p><p style="text-align:justify;">• Disfruta de un equilibrio perfecto entre naturaleza, aventura y relajación</p><h3 style="text-align:justify;"><strong>Más que unas simples vacaciones, la Aventura de Buceo en Bunaken &amp; Vida Salvaje en Tangkoko ofrece la oportunidad de vivir lo mejor de Sulawesi del Norte. Desde impresionantes paisajes submarinos hasta extraordinarios encuentros con la vida salvaje, cada día revela un lado diferente de este fascinante paraíso tropical.</strong></h3>', '<ul><li data-list-item-id="eebc7b4e396e8f7cf17ef8a660054c9c3"><p style="text-align:justify;">Traslado al aeropuerto&nbsp;</p></li><li data-list-item-id="e07c8a95ee6f8b05f18abc3c068904131"><p style="text-align:justify;">Habitación (ocupación doble – camas doble/twin)</p></li><li data-list-item-id="ea72b4950372c034d71b5bc788568f7af"><p style="text-align:justify;">Comidas en pensión completa</p></li><li data-list-item-id="e9a36fb5e11ed7803755e801175a21ca7"><p style="text-align:justify;">Paquete de pensión completa (basado en 2 inmersiones matutinas por día durante 3 días de inmersión)</p><p><i><strong>Tour a Tangkoko</strong></i>:&nbsp;</p></li><li data-list-item-id="ee940554db6d2888b5bb336fc3adcacdd">Guardaparques en el parque natural de Tangkoko</li><li data-list-item-id="ee45511db7425bb0a055e829f59fba41b">Transporte a Tangkoko &amp; la cascada de Tunan</li><li data-list-item-id="e30412c6835047afc69dff857179d3527">1x almuerzo en un restaurante local</li><li data-list-item-id="ea8818d92b289888451c817f79249fabe">Guía experto &amp; conductor</li><li data-list-item-id="ec3ec6d7bb147e07c82d795805c6ecbc9">Todas las entradas&nbsp;</li><li data-list-item-id="e5a9edd557416c1a3372568c67fdfc9a5">Una botella de agua mineral por persona.</li></ul>', '<ul><li data-list-item-id="ec756b43cc417da86cc09e4d40b5fccf2">Alquiler de equipo de buceo</li><li data-list-item-id="e18ed9b2769f68528af4b1df7bdda657a">Recargas de nitrox</li><li data-list-item-id="e652fe22505f77dc5bb8cba9be6dee4a2">Inmersiones nocturnas &amp; del pez mandarín</li><li data-list-item-id="ec89e22491c828ef51748a289e4e276f7">Excursiones &amp; actividades opcionales</li><li data-list-item-id="ecb84cba1c33800eb790ef4ec86aa3847">Gastos personales</li><li data-list-item-id="e8eb11ebbeab17718fad53293458bf0da">Impuesto aeroportuario &amp; exceso de equipaje</li><li data-list-item-id="e973813f562b295b4abff7069d5a3fe14">Seguro de viaje</li><li data-list-item-id="e415d746c3ce9f9f2b62c339ce9d53907">Cualquier servicio no mencionado anteriormente</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 35: 4-days-discover-bangkas-underwater-paradise
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '35', 'es', '4 Días Descubre el Paraíso Submarino de Bangka', '<h2 style="text-align:justify;">Descubre un Paraíso de Buceo Escondido en Sulawesi del Norte</h2><p style="text-align:justify;">Escapa a las aguas tranquilas del Archipiélago de Bangka, un destino insular tropical donde arrecifes prístinos, mares cristalinos y una extraordinaria biodiversidad marina crean una aventura submarina inolvidable.</p><p style="text-align:justify;">Ubicado entre el legendario Parque Marino de Bunaken y el mundialmente famoso Estrecho de Lembeh, Bangka ofrece una rara combinación de dramático buceo de pared, vibrantes jardines de coral, fascinante vida macro y espectaculares paisajes submarinos. Esta mezcla única hace que el archipiélago sea uno de los destinos más gratificantes de Sulawesi del Norte para buceadores de todos los niveles de experiencia.</p><p style="text-align:justify;">Bajo la superficie, descubre coloridos arrecifes de coral blando y duro, imponentes pináculos submarinos, cavernas escondidas, praderas marinas y prósperos ecosistemas marinos. Cada inmersión presenta una nueva perspectiva del océano, desde bancos de peces tropicales y tortugas marinas hasta especies macro raras que atraen a fotógrafos submarinos de todo el mundo.</p><p style="text-align:justify;">Sobre el agua, vive el pacífico encanto de la vida insular. Rodeado de mares turquesas y paisajes tropicales intactos, Bangka ofrece el escenario perfecto para relajarse, reconectar con la naturaleza y disfrutar de un ritmo más lento lejos de los destinos turísticos concurridos.</p><p style="text-align:justify;">Ya sea que seas un buceador experimentado, un entusiasta de la vida marina, o simplemente busques un escape insular tropical, el Archipiélago de Bangka ofrece una excepcional mezcla de aventura, belleza natural y relajación.</p><h3 style="text-align:justify;">Por Qué Amarás Este Paquete</h3><p style="text-align:justify;">• Descubre uno de los secretos de buceo mejor guardados de Sulawesi del Norte</p><p style="text-align:justify;">• Vive tanto el buceo de pared como el buceo macro en un solo destino</p><p style="text-align:justify;">• Explora vibrantes arrecifes de coral y rica biodiversidad marina</p><p style="text-align:justify;">• Accede a numerosos sitios de buceo ubicados cerca del resort</p><p style="text-align:justify;">• Adecuado tanto para buceadores principiantes como experimentados</p><p style="text-align:justify;">• Disfruta de una pacífica atmósfera insular tropical</p><p style="text-align:justify;">• Ideal para los entusiastas de la fotografía submarina</p><p style="text-align:justify;">• Combina buceo de clase mundial con relajación insular</p><h3 style="text-align:justify;"><strong>Más que unas simples vacaciones de buceo, la Exploración del Archipiélago de Bangka te invita a descubrir la notable diversidad del mundo marino de Sulawesi del Norte. Desde coloridos arrecifes de coral y fascinantes encuentros marinos hasta la serenidad de un refugio insular tropical, cada momento está diseñado para inspirar, relajar y crear recuerdos duraderos.</strong></h3>', '<ul><li data-list-item-id="eebc7b4e396e8f7cf17ef8a660054c9c3"><p style="text-align:justify;">Traslado al aeropuerto&nbsp;</p></li><li data-list-item-id="e07c8a95ee6f8b05f18abc3c068904131"><p style="text-align:justify;">Habitación (ocupación doble – camas doble/twin)</p></li><li data-list-item-id="ea72b4950372c034d71b5bc788568f7af"><p style="text-align:justify;">Comidas en pensión completa</p></li><li data-list-item-id="e9a36fb5e11ed7803755e801175a21ca7"><p style="text-align:justify;">Paquete de pensión completa (basado en 2 inmersiones matutinas por día durante 2 días de inmersión)</p></li></ul>', '<ul><li data-list-item-id="ec756b43cc417da86cc09e4d40b5fccf2">Alquiler de equipo</li><li data-list-item-id="e18ed9b2769f68528af4b1df7bdda657a">Recargas de nitrox</li><li data-list-item-id="e652fe22505f77dc5bb8cba9be6dee4a2">Inmersiones nocturnas &amp; del pez mandarín</li><li data-list-item-id="ec89e22491c828ef51748a289e4e276f7">Excursiones &amp; actividades opcionales</li><li data-list-item-id="ecb84cba1c33800eb790ef4ec86aa3847">Gastos personales</li><li data-list-item-id="e8eb11ebbeab17718fad53293458bf0da">Impuesto aeroportuario &amp; exceso de equipaje</li><li data-list-item-id="e973813f562b295b4abff7069d5a3fe14">Seguro de viaje</li><li data-list-item-id="e415d746c3ce9f9f2b62c339ce9d53907">Cualquier servicio no mencionado anteriormente</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 36: 4-days-lembeh-macro-diving-escape
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '36', 'es', '4 Días Escape de Buceo Macro en Lembeh', '<h2 style="text-align:justify;">Descubre la Capital Mundial del Buceo Macro</h2><p style="text-align:justify;">Entra en uno de los entornos submarinos más extraordinarios de la Tierra, donde cada inmersión revela un mundo escondido de vida marina rara, comportamientos fascinantes y descubrimientos inolvidables.</p><p style="text-align:justify;">Ubicado entre el territorio continental de Sulawesi del Norte y la Isla de Lembeh, el legendario Estrecho de Lembeh ha ganado reconocimiento mundial como el principal destino del mundo para el muck diving y la fotografía macro submarina. Bajo sus aguas tranquilas se esconde un ecosistema notable donde la arena negra volcánica proporciona el hábitat perfecto para algunas de las criaturas más inusuales y buscadas del océano.</p><p style="text-align:justify;">A diferencia de los destinos de buceo tradicionales conocidos por sus grandes especies pelágicas, Lembeh ofrece algo completamente diferente. Aquí, la emoción proviene de descubrir los detalles extraordinarios del mundo submarino. Desde peces sapo perfectamente camuflados y delicados caballitos de mar pigmeos hasta coloridos nudibranquios e innumerables criaturas raras, cada inmersión se convierte en una fascinante búsqueda de tesoros bajo la superficie.</p><p style="text-align:justify;">Reconocido entre fotógrafos submarinos, biólogos marinos y buceadores experimentados de todo el mundo, Lembeh ofrece una experiencia que combina exploración, paciencia y la emoción de encontrar especies marinas rara vez vistas en otro lugar.</p><p style="text-align:justify;">Más allá del buceo, disfruta de la atmósfera pacífica de un refugio insular tropical. Rodeado de aguas tranquilas y un exuberante paisaje costero, Lembeh ofrece el escenario perfecto para relajarse entre inmersiones y sumergirte por completo en la belleza de Sulawesi del Norte.</p><p style="text-align:justify;">Ya sea que seas un fotógrafo submarino, un buceador apasionado, o simplemente sientas curiosidad por las maravillas escondidas del océano, el Estrecho de Lembeh promete un viaje inolvidable a uno de los ecosistemas marinos más únicos del planeta.</p><h3 style="text-align:justify;">Por Qué Amarás Este Paquete</h3><p style="text-align:justify;">• Sumérgete en uno de los destinos de muck diving más famosos del mundo</p><p style="text-align:justify;">• Encuentra especies marinas raras que se encuentran en muy pocos lugares de la Tierra</p><p style="text-align:justify;">• Explora el ecosistema único de arena negra volcánica del Estrecho de Lembeh</p><p style="text-align:justify;">• Ideal para los entusiastas de la fotografía macro y la vida marina submarina</p><p style="text-align:justify;">• Descubre peces sapo, caballitos de mar, nudibranquios y otras fascinantes criaturas marinas</p><p style="text-align:justify;">• Disfruta de condiciones de buceo tranquilas adecuadas para varios niveles de experiencia</p><p style="text-align:justify;">• Hospédate en un pacífico entorno insular tropical</p><p style="text-align:justify;">• Vive un destino celebrado por buceadores y fotógrafos de todo el mundo</p><h3 style="text-align:justify;">Más que unas simples vacaciones de buceo, Buceando las Maravillas del Estrecho de Lembeh ofrece la oportunidad de vislumbrar un lado escondido del océano que pocas personas llegan a experimentar. Desde extraordinarios encuentros marinos hasta la serenidad de la vida insular, cada momento revela por qué Lembeh sigue siendo uno de los destinos de buceo más respetados del mundo.</h3>', '<ul><li data-list-item-id="eebc7b4e396e8f7cf17ef8a660054c9c3"><p style="text-align:justify;">Traslado al aeropuerto&nbsp;</p></li><li data-list-item-id="e07c8a95ee6f8b05f18abc3c068904131"><p style="text-align:justify;">Habitación (ocupación doble – camas doble/twin)</p></li><li data-list-item-id="ea72b4950372c034d71b5bc788568f7af"><p style="text-align:justify;">Comidas en pensión completa</p></li><li data-list-item-id="e9a36fb5e11ed7803755e801175a21ca7"><p style="text-align:justify;">Paquete de pensión completa (basado en 2 inmersiones matutinas por día durante 2 días de inmersión)</p></li></ul>', '<ul><li data-list-item-id="ec756b43cc417da86cc09e4d40b5fccf2">Alquiler de equipo</li><li data-list-item-id="e18ed9b2769f68528af4b1df7bdda657a">Recargas de nitrox</li><li data-list-item-id="e652fe22505f77dc5bb8cba9be6dee4a2">Inmersiones nocturnas &amp; del pez mandarín</li><li data-list-item-id="ec89e22491c828ef51748a289e4e276f7">Excursiones &amp; actividades opcionales</li><li data-list-item-id="ecb84cba1c33800eb790ef4ec86aa3847">Gastos personales</li><li data-list-item-id="e8eb11ebbeab17718fad53293458bf0da">Impuesto aeroportuario &amp; exceso de equipaje</li><li data-list-item-id="e973813f562b295b4abff7069d5a3fe14">Seguro de viaje</li><li data-list-item-id="e415d746c3ce9f9f2b62c339ce9d53907">Cualquier servicio no mencionado anteriormente</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 37: 4-days-bunaken-marine-park-experience
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '37', 'es', '4 Días Experiencia en el Parque Marino de Bunaken', '<h2 style="text-align:justify;">Descubre el Paraíso Submarino Mundialmente Famoso de Sulawesi del Norte</h2><p style="text-align:justify;">Vive la impresionante belleza del Parque Marino de Bunaken, uno de los destinos de buceo más celebrados de Indonesia y un verdadero paraíso para los amantes del océano.</p><p style="text-align:justify;">Rodeado de cristalinas aguas tropicales, Bunaken es famoso por sus dramáticas paredes submarinas, vibrantes arrecifes de coral y extraordinaria biodiversidad marina. Bajo la superficie se encuentra un próspero ecosistema donde las tortugas marinas se deslizan sin esfuerzo por el azul, coloridos peces de arrecife llenan los jardines de coral, y espectaculares paisajes submarinos crean experiencias de buceo inolvidables.</p><p style="text-align:justify;">Reconocido como una de las áreas de conservación marina más importantes del Sudeste Asiático, Bunaken ofrece una visibilidad excepcional y una increíble variedad de entornos de buceo. Desde paredes de coral verticales y prósperos sistemas de arrecife hasta fascinante vida macro escondida entre los corales, cada inmersión revela una perspectiva diferente de este maravilloso mundo submarino.</p><p style="text-align:justify;">Más allá del océano, disfruta de la atmósfera pacífica de un escape insular tropical. Relájate junto a aguas turquesas, admira impresionantes atardeceres, y vive el ritmo más lento de la vida insular rodeado de la belleza natural de Sulawesi del Norte.</p><p style="text-align:justify;">Ya sea que seas un buceador certificado, un fotógrafo submarino, o simplemente alguien que aprecia la belleza del mar, Bunaken ofrece un viaje inolvidable a uno de los ecosistemas marinos más notables del mundo.</p><h3 style="text-align:justify;">Por Qué Amarás Este Paquete</h3><p style="text-align:justify;">• Sumérgete en uno de los parques marinos más famosos de Indonesia</p><p style="text-align:justify;">• Explora espectaculares paredes de coral y coloridos sistemas de arrecife</p><p style="text-align:justify;">• Encuentra tortugas marinas y abundante vida marina tropical</p><p style="text-align:justify;">• Disfruta de aguas cristalinas con excelente visibilidad</p><p style="text-align:justify;">• Vive uno de los principales destinos de buceo del Sudeste Asiático</p><p style="text-align:justify;">• Adecuado tanto para buceadores principiantes como experimentados</p><p style="text-align:justify;">• Perfecto para los entusiastas de la fotografía submarina</p><p style="text-align:justify;">• Combina buceo de clase mundial con relajación insular tropical</p><h3 style="text-align:justify;"><strong>Más que unas simples vacaciones de buceo, el Escape de Buceo en la Isla de Bunaken te invita a descubrir la increíble biodiversidad marina y la belleza natural que han hecho de Bunaken un destino legendario entre los buceadores de todo el mundo. Cada inmersión, cada atardecer y cada momento pasado en este paraíso tropical crea recuerdos que durarán toda la vida.</strong></h3>', '<ul><li data-list-item-id="eebc7b4e396e8f7cf17ef8a660054c9c3"><p style="text-align:justify;">Traslado al aeropuerto&nbsp;</p></li><li data-list-item-id="e07c8a95ee6f8b05f18abc3c068904131"><p style="text-align:justify;">Habitación (ocupación doble – camas doble/twin)</p></li><li data-list-item-id="ea72b4950372c034d71b5bc788568f7af"><p style="text-align:justify;">Comidas en pensión completa</p></li><li data-list-item-id="e9a36fb5e11ed7803755e801175a21ca7"><p style="text-align:justify;">Paquete de pensión completa (basado en 2 inmersiones matutinas por día durante 2 días de inmersión)</p></li></ul>', '<ul><li data-list-item-id="ec756b43cc417da86cc09e4d40b5fccf2">Alquiler de equipo</li><li data-list-item-id="e18ed9b2769f68528af4b1df7bdda657a">Recargas de nitrox</li><li data-list-item-id="e652fe22505f77dc5bb8cba9be6dee4a2">Inmersiones nocturnas &amp; del pez mandarín</li><li data-list-item-id="ec89e22491c828ef51748a289e4e276f7">Excursiones &amp; actividades opcionales</li><li data-list-item-id="ecb84cba1c33800eb790ef4ec86aa3847">Gastos personales</li><li data-list-item-id="e8eb11ebbeab17718fad53293458bf0da">Impuesto aeroportuario &amp; exceso de equipaje</li><li data-list-item-id="e973813f562b295b4abff7069d5a3fe14">Seguro de viaje</li><li data-list-item-id="e415d746c3ce9f9f2b62c339ce9d53907">Cualquier servicio no mencionado anteriormente</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 38: lihaga-island-white-sand-escape
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '38', 'es', 'Escape a la Playa Blanca de la Isla de Lihaga', '<h2 style="text-align:justify;">Escapa al Paraíso Tropical Escondido de Sulawesi del Norte</h2><p style="text-align:justify;">Descubre la belleza intacta de la Isla de Lihaga, un paraíso tropical aislado donde la fina arena blanca, las aguas turquesas cristalinas y un paisaje insular impresionante crean el escape perfecto de la vida cotidiana.</p><p style="text-align:justify;">Rodeada de las aguas prístinas de Likupang, uno de los principales destinos turísticos de Indonesia, la Isla de Lihaga ofrece un entorno idílico para viajeros que buscan tranquilidad, belleza natural y experiencias tropicales inolvidables. Sin multitudes, sin tráfico, nada más que el relajante sonido del océano, cada momento te invita a reducir el ritmo y abrazar el pacífico ritmo de la vida insular.</p><p style="text-align:justify;">La isla es conocida por su deslumbrante playa de arena blanca y sus excepcionalmente claras aguas que revelan vibrantes arrecifes de coral y colorida vida marina bajo la superficie. Ya sea que elijas nadar en el cálido mar tropical, hacer snorkel entre prósperos jardines de coral, remar por la tranquila laguna, o simplemente relajarte bajo la sombra de las palmeras de coco, Lihaga ofrece una experiencia insular verdaderamente reconfortante.</p><p style="text-align:justify;">Más allá de su belleza natural, la Isla de Lihaga es también un paraíso para fotógrafos y amantes de la playa. Interminables extensiones de arena blanca, vistas panorámicas del océano y espectaculares tonos de azul crean innumerables momentos perfectos para una postal a lo largo del día. Cada rincón de la isla se siente como una postal esperando ser capturada.</p><p style="text-align:justify;">Diseñado para parejas, familias, amigos y viajeros solitarios por igual, este escape insular combina relajación, aventura tropical y la belleza intacta de Sulawesi del Norte en un solo viaje inolvidable.</p><h3 style="text-align:justify;">Por Qué Amarás Este Paquete</h3><p style="text-align:justify;">• Relájate en una de las islas de arena blanca más hermosas de Sulawesi del Norte</p><p style="text-align:justify;">• Nada en aguas turquesas cristalinas</p><p style="text-align:justify;">• Descubre coloridos arrecifes de coral y vida marina tropical</p><p style="text-align:justify;">• Disfruta de una pacífica atmósfera insular lejos de las multitudes</p><p style="text-align:justify;">• Perfecto para snorkel, natación y relajación en la playa</p><p style="text-align:justify;">• Captura impresionantes paisajes tropicales y fotos inolvidables</p><p style="text-align:justify;">• Vive la belleza natural de la región turística de Likupang</p><p style="text-align:justify;">• Ideal para parejas, familias, lunas de miel y amantes de la playa</p><h3 style="text-align:justify;"><strong>Más que un simple escape a la playa, el Escape a la Playa Blanca de la Isla de Lihaga ofrece la oportunidad de reconectar con la naturaleza en una de las islas escondidas más hermosas de Sulawesi del Norte. Desde playas prístinas y aguas turquesas hasta paisajes tropicales inolvidables, cada momento se convierte en un recuerdo que atesorarás mucho después de que termine tu viaje.</strong></h3>', '<ul><li data-list-item-id="ea23d3c92112e60644e5e2271e3753532"><p style="text-align:justify;">Transporte terrestre</p></li><li data-list-item-id="e0ea594d6a88f73886434e73627cfc1ef"><p style="text-align:justify;">Barco privado a la isla de Lihaga</p></li><li data-list-item-id="eade732e4827ee2d27bca1f6a14016d45"><p style="text-align:justify;">Guía turístico experto</p></li><li data-list-item-id="e688d27ccc1439077a5068c64e476b6ad"><p style="text-align:justify;">Conductor &amp; timonel</p></li><li data-list-item-id="ef25650808aa3c32de3a1e39199920a06"><p style="text-align:justify;">Entradas a las atracciones turísticas &amp; estacionamiento</p></li><li data-list-item-id="e7ac148cecef0bb392af14db4b9f574d4"><p style="text-align:justify;">Almuerzo &amp; 1 botella de agua mineral por persona</p></li><li data-list-item-id="eccc9556eef6a2fa87c897c5c43a32269"><p style="text-align:justify;">Servicios turísticos según el itinerario</p></li></ul>', '<ul><li data-list-item-id="ed040cc0dd81d42e795600e22a7bf6536">Boleto de avión</li><li data-list-item-id="eb2e43bfc1813f79cdda31725bf97dbad">Impuesto aeroportuario</li><li data-list-item-id="eec4c3bc7fb908919a5b66c97cde714e5">Mozos</li><li data-list-item-id="ef13b7599a238bc82e6bd5620370064d9">Hotel</li><li data-list-item-id="e7a50082855dcc93d44a0d8bbcef795bb">Propinas para el guía y el conductor</li><li data-list-item-id="e2a39ca8ecbefd244e7980a1f24d1bb28">Excursiones opcionales</li><li data-list-item-id="efae7355dae9278ce19d7a043661cdfd1">Otros gastos fuera del programa del tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 39: gangga-lihaga-snorkeling-escape
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '39', 'es', 'Escape de Snorkel en Gangga &amp; Lihaga', '<h2 style="text-align:justify;">Descubre Dos Paraísos Tropicales en un Solo Viaje Inolvidable</h2><p style="text-align:justify;">Escapa a la impresionante belleza de Sulawesi del Norte y vive dos de las islas tropicales más espectaculares de Likupang en un solo día. Rodeada de aguas cristalinas, vibrantes arrecifes de coral y playas de fina arena blanca, esta aventura de isla en isla ofrece la combinación perfecta de exploración marina y relajación tropical.</p><p style="text-align:justify;">Ubicadas dentro de la mundialmente famosa región turística de Likupang, la Isla de Gangga y la Isla de Lihaga ofrecen cada una su propio encanto único. Bajo la superficie, coloridos jardines de coral y diversa vida marina crean una experiencia de snorkel inolvidable, mientras que sobre el agua, playas prístinas e infinitos tonos de turquesa ofrecen el escenario ideal para relajarse y reconectar con la naturaleza.</p><p style="text-align:justify;">La Isla de Gangga es celebrada por su rica biodiversidad submarina y sus aguas tranquilas y cristalinas, convirtiéndola en uno de los mejores destinos de snorkel de Sulawesi del Norte. A solo un corto trayecto en bote, la Isla de Lihaga recibe a los visitantes con su intacta playa de arena blanca, atmósfera tranquila y paisajes perfectos para una postal que se sienten como un paraíso tropical privado.</p><p style="text-align:justify;">Ya sea que estés nadando en cálidas aguas tropicales, admirando espectaculares paisajes costeros, capturando fotografías inolvidables, o simplemente disfrutando del pacífico ritmo de la vida insular, cada momento está diseñado para crear recuerdos duraderos.</p><p style="text-align:justify;">Diseñado para parejas, familias, grupos de amigos y viajeros solitarios, esta experiencia reúne lo mejor de la belleza marina, el encanto insular y la relajante atmósfera tropical de Likupang en un escape extraordinario.</p><h3 style="text-align:justify;">Por Qué Amarás Este Paquete</h3><p style="text-align:justify;">• Visita dos de las islas tropicales más hermosas de Likupang en un solo día</p><p style="text-align:justify;">• Haz snorkel entre vibrantes arrecifes de coral y colorida vida marina tropical</p><p style="text-align:justify;">• Relájate en prístinas playas de arena blanca rodeadas de aguas turquesas</p><p style="text-align:justify;">• Vive la pacífica atmósfera de las islas escondidas de Sulawesi del Norte</p><p style="text-align:justify;">• Disfruta de espectaculares paisajes insulares y vistas cristalinas del océano</p><p style="text-align:justify;">• Captura increíbles paisajes tropicales y fotografías inolvidables</p><p style="text-align:justify;">• Combina snorkel, recorridos de isla en isla y relajación en la playa en un solo viaje</p><p style="text-align:justify;">• Perfecto para parejas, familias, lunas de miel y amantes de la naturaleza</p><h3 style="text-align:justify;">Más que un simple tour insular, el <strong>Escape de las Dos Islas – Gangga &amp; Lihaga</strong> es una invitación a vivir la belleza tropical de Likupang en su mejor forma. Desde vibrantes ecosistemas submarinos hasta prístinas playas de arena blanca, cada destino revela otra razón por la que Sulawesi del Norte es uno de los escapes insulares más cautivadores de Indonesia.</h3>', '<ul><li data-list-item-id="ec841ebd5e4cd2f22a9ab973c51cd4294"><p style="text-align:justify;">Transporte terrestre</p></li><li data-list-item-id="e0fd2b212b9f3647f5b39e969d280b5b9"><p style="text-align:justify;">Barco privado a las islas de Gangga &amp; Lihaga</p></li><li data-list-item-id="e1955e0bd0b95f1e58e091f47a0f210fd"><p style="text-align:justify;">Equipo de snorkel</p></li><li data-list-item-id="ef86508779b01af9d5d07a6933e8c8b71"><p style="text-align:justify;">Guía turístico, conductor &amp; timonel expertos</p></li><li data-list-item-id="e6053e10c115a87007b280508a6f4332d"><p style="text-align:justify;">Entradas a las atracciones turísticas &amp; estacionamiento</p></li><li data-list-item-id="e9615cc9e5ef3f391f33ab1e8faff78dd"><p style="text-align:justify;">Almuerzo &amp; 1 botella de agua mineral por persona</p></li><li data-list-item-id="e8d83387ff5232b493198cf3640575fe4"><p style="text-align:justify;">Servicios turísticos según el itinerario</p></li></ul>', '<ul><li data-list-item-id="ed040cc0dd81d42e795600e22a7bf6536">Boleto de avión</li><li data-list-item-id="eb2e43bfc1813f79cdda31725bf97dbad">Impuesto aeroportuario</li><li data-list-item-id="eec4c3bc7fb908919a5b66c97cde714e5">Mozos</li><li data-list-item-id="ef13b7599a238bc82e6bd5620370064d9">Hotel</li><li data-list-item-id="e7a50082855dcc93d44a0d8bbcef795bb">Propinas para el guía y el conductor</li><li data-list-item-id="e2a39ca8ecbefd244e7980a1f24d1bb28">Excursiones opcionales</li><li data-list-item-id="efae7355dae9278ce19d7a043661cdfd1">Otros gastos fuera del programa del tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 40: manado-tua-island-trekking-bunaken-escape
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '40', 'es', 'Trekking a la Isla de Manado Tua &amp; Escape a Bunaken', '<h3 style="text-align:justify;">Del Bosque Tropical a las Maravillas Submarinas de Bunaken</h3><p style="text-align:justify;">Vive dos de los entornos naturales más notables de Sulawesi del Norte en un solo día inolvidable — el exuberante paisaje volcánico de Manado Tua y el espectacular mundo marino de Bunaken.</p><p style="text-align:justify;">Emergiendo de las aguas justo frente a la costa de Manado, Manado Tua ofrece una rara oportunidad de vivir el lado más salvaje de Sulawesi del Norte. Su bosque tropical, paisaje volcánico y entorno pacífico crean un escape inmersivo de la ciudad, mientras que la posibilidad de encontrar fauna endémica de Sulawesi añade un emocionante elemento de descubrimiento a la aventura.</p><p style="text-align:justify;">La experiencia continúa bajo la superficie en Bunaken, uno de los destinos marinos más celebrados de Sulawesi del Norte. Rodeado de claras aguas tropicales y un extraordinario escenario submarino, Bunaken ofrece un entorno ideal para descubrir la belleza del ecosistema marino de la región a través de snorkel o buceo opcional.</p><p style="text-align:justify;">Lo que hace especial a esta experiencia es el contraste entre dos mundos completamente diferentes. En un momento estás rodeado de bosque tropical y paisajes volcánicos; al siguiente, estás explorando el vibrante entorno submarino de uno de los destinos marinos más reconocidos de Indonesia.</p><p style="text-align:justify;">Ya sea que busques una aventura ligera, un escape a la naturaleza, o una introducción a la diversidad natural de Sulawesi del Norte, este viaje ofrece una forma emocionante de vivir tanto la <strong>tierra como el mar en un solo día</strong>.</p><h3 style="text-align:justify;">Por Qué Amarás Esta Experiencia</h3><p style="text-align:justify;">• Descubre la belleza natural de la volcánica Isla de Manado Tua</p><p style="text-align:justify;">• Vive la atmósfera del bosque tropical de Sulawesi del Norte</p><p style="text-align:justify;">• Tienes la oportunidad de encontrar fauna endémica de Sulawesi</p><p style="text-align:justify;">• Continúa tu aventura en el espectacular entorno marino de Bunaken</p><p style="text-align:justify;">• Disfruta de snorkel o buceo opcional en Bunaken</p><p style="text-align:justify;">• Vive dos lados completamente diferentes de Sulawesi del Norte en un solo viaje</p><p style="text-align:justify;">• Ideal para amantes de la naturaleza, buscadores de aventura, fotógrafos y viajeros activos</p><p style="text-align:justify;">• Una combinación memorable de exploración del bosque tropical y descubrimiento marino</p><h3 style="text-align:justify;">Más que un simple viaje de trekking o snorkel, el <strong>Trekking a la Isla de Manado Tua &amp; Escape a Bunaken</strong> reúne los dos lados de la belleza natural de Sulawesi del Norte — los paisajes salvajes sobre el agua y el extraordinario mundo marino debajo de ella.</h3>', '<ul><li data-list-item-id="e00fb6c1118e49e21a7f97503eaf992e5"><p style="text-align:justify;">Transporte terrestre privado (automóvil)&nbsp;</p></li><li data-list-item-id="e6716471c34f5fc9b3179bcb936fa58c3"><p style="text-align:justify;">Barco a la isla de Manado Tua - isla de Bunaken</p></li><li data-list-item-id="e7dbd5d5b9349e351d2566cfe3d45e1f5"><p style="text-align:justify;">Guía turístico experto&nbsp;</p></li><li data-list-item-id="ee7e0b2f9144abb63771706ac469d1409"><p style="text-align:justify;">Conductor &amp; timonel&nbsp;</p></li><li data-list-item-id="e5f742e4e693df53a07f0d451ed536d14"><p style="text-align:justify;">Entradas a las atracciones turísticas</p></li><li data-list-item-id="e16a242b2af99118485dc893e4c9eb32e"><p style="text-align:justify;">Estacionamiento, caja de almuerzo&nbsp;</p></li><li data-list-item-id="e4ee5b7dc98d3b764f8675efcd7904bc8"><p style="text-align:justify;">1 botella de agua mineral por persona&nbsp;</p></li><li data-list-item-id="e19afe33283d9f5a1420ae129e922a3cd"><p style="text-align:justify;">Servicios turísticos según el itinerario</p></li></ul>', '<ul><li data-list-item-id="e369b588efdeecf96f0f185253b99bd9d">Boleto de avión&nbsp;</li><li data-list-item-id="ee1063332712c6f3757ec551ca5a90c42">Impuesto aeroportuario</li><li data-list-item-id="e76eb00c159fe609d319cbf81974ed8fd">Servicio de mozos</li><li data-list-item-id="e1cc4535135e2d767b6fafc8aa29d78af">Alojamiento en hotel&nbsp;</li><li data-list-item-id="eaf01991d1adab37bf2ca6f7fd2e7f0bf">Propinas para el guía &amp; el conductor</li><li data-list-item-id="e1cadc73e8b1505883ffb1bf721a2db91">Excursiones opcionales &amp; otros gastos personales no mencionados en el programa</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 41: waruga-heritage-batu-angus-coastal-escape
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '41', 'es', 'Patrimonio de Waruga &amp; Escape Costero a Batu Angus', '<h2 style="text-align:justify;">Descubre el Patrimonio Cultural y la Belleza Volcánica de Sulawesi del Norte</h2><p style="text-align:justify;">Ve más allá del turismo habitual y descubre dos lados fascinantes de Sulawesi del Norte en una sola experiencia memorable. Este viaje reúne el rico patrimonio cultural del pueblo Minahasa con el dramático paisaje volcánico y la vibrante vida marina de Batu Angus.</p><p style="text-align:justify;">Comienza tu descubrimiento con el fascinante patrimonio de <strong>Waruga Sawangan</strong>, donde tradicionales sarcófagos de piedra ofrecen una mirada a la historia y las tradiciones culturales del pueblo Minahasa. Más que un antiguo sitio de entierro, Waruga ofrece una conexión única con las tradiciones e historias que han dado forma a la comunidad local durante generaciones.</p><p style="text-align:justify;">La experiencia luego continúa hacia el impresionante paisaje costero de <strong>Batu Angus</strong>, donde antigua lava volcánica ha creado un entorno natural distintivo a lo largo de la costa. El contraste entre las oscuras formaciones volcánicas, el entorno tropical y las aguas claras del mar crea un paisaje verdaderamente único de Sulawesi del Norte.</p><p style="text-align:justify;">Bajo la superficie, Batu Angus revela otro lado de su belleza natural. Sus claras aguas costeras ofrecen la oportunidad de descubrir coloridos arrecifes de coral, peces tropicales y diversa vida marina mientras disfrutas de una relajante experiencia de snorkel.</p><p style="text-align:justify;">Lo que hace especial a este viaje es la combinación de <strong>cultura, geología, naturaleza y exploración marina</strong> en un solo día. Es una forma ideal de vivir un lado de Sulawesi del Norte que va más allá de sus famosas playas y el turismo tradicional.</p><h3 style="text-align:justify;">Por Qué Amarás Esta Experiencia</h3><p style="text-align:justify;">• Descubre el fascinante patrimonio cultural del pueblo Minahasa</p><p style="text-align:justify;">• Explora el histórico Waruga Sawangan</p><p style="text-align:justify;">• Vive el paisaje volcánico único de Batu Angus</p><p style="text-align:justify;">• Descubre coloridos arrecifes de coral y vida marina tropical</p><p style="text-align:justify;">• Disfruta del snorkel en claras aguas costeras</p><p style="text-align:justify;">• Vive el contraste entre el antiguo patrimonio y el dramático escenario natural</p><p style="text-align:justify;">• Combina descubrimiento cultural, naturaleza y aventura marina en un solo viaje</p><p style="text-align:justify;">• Ideal para amantes de la cultura, entusiastas de la naturaleza, fotógrafos y viajeros activos</p><h3 style="text-align:justify;">Más que un simple tour turístico, el <strong>Patrimonio de Waruga &amp; Snorkel en Batu Angus</strong> ofrece un fascinante viaje a través de las historias, paisajes y belleza natural de Sulawesi del Norte. Desde el antiguo patrimonio Minahasa hasta las costas volcánicas y la vida bajo el mar, cada experiencia revela un lado diferente de este notable destino.</h3>', '<ul><li data-list-item-id="ee44c315611f4315dc32a35e8ba7a8932"><p style="text-align:justify;">Transporte&nbsp;</p></li><li data-list-item-id="e9aebf7e500b9218ae96e4a9735b5887c"><p style="text-align:justify;">Barco &amp; equipo de snorkel</p></li><li data-list-item-id="ea78c4cba10fab0194db11ca30051e78c"><p style="text-align:justify;">Guía turístico, conductor &amp; timonel expertos</p></li><li data-list-item-id="e763a6a58cf17409d04eff769ee730b2b"><p style="text-align:justify;">Entradas a las atracciones turísticas &amp; estacionamiento</p></li><li data-list-item-id="ea46383f45241738ea5e48e7cbee46faa"><p style="text-align:justify;">Almuerzo &amp; 1 botella de agua mineral por persona</p></li><li data-list-item-id="e867486aa2ffffd707bde11fb9e6db2af"><p style="text-align:justify;">Servicios turísticos según el itinerario</p></li></ul>', '<ul><li data-list-item-id="e369b588efdeecf96f0f185253b99bd9d">Boleto de avión&nbsp;</li><li data-list-item-id="ee1063332712c6f3757ec551ca5a90c42">Impuesto aeroportuario</li><li data-list-item-id="e76eb00c159fe609d319cbf81974ed8fd">Servicio de mozos</li><li data-list-item-id="e1cc4535135e2d767b6fafc8aa29d78af">Alojamiento en hotel&nbsp;</li><li data-list-item-id="eaf01991d1adab37bf2ca6f7fd2e7f0bf">Propinas para el guía &amp; el conductor</li><li data-list-item-id="e1cadc73e8b1505883ffb1bf721a2db91">Excursiones opcionales &amp; otros gastos personales no mencionados en el programa</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 21 hari 1 (itinerary 2749)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('2749', 'es', 'Itinerario', '<p style="text-align:justify;">Punto de encuentro a las 8:00 AM con el guía turístico en el <strong>Muelle de Megamas</strong> para un tour de un día a la <strong>Isla de Bunaken</strong>. Desde el Muelle de Megamas, cruce en bote hacia la <strong>Isla de Bunaken</strong> (aproximadamente 30 minutos). Actualmente, Bunaken ha sido hermosamente renovada con su nuevo <strong>Muelle Turístico de Bunaken (New Bunaken)</strong>, más representativo, donde los participantes pueden capturar impresionantes fotos y videos con vistas escénicas de la isla.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Descubre la belleza submarina del Parque Marino de Bunaken, hogar de vibrantes arrecifes de coral y coloridos peces tropicales, a través de actividades <i>opcionales </i>de snorkel o buceo. Los participantes también pueden disfrutar de tiempo libre para relajarse y explorar la serena atmósfera de la playa de la isla. El almuerzo se servirá en un restaurante local frente a la playa.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Después del almuerzo, disfruta de más tiempo libre o continúa con snorkel/buceo (opcional). Por la tarde, regreso al Muelle de Megamas, Manado. Fin del tour.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 19 hari 1 (itinerary 2751)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('2751', 'es', 'Itinerario', '<p style="text-align:justify;">Los participantes serán recogidos en el punto de encuentro por la mañana y trasladados al <strong>Lugar de Rafting</strong> en el <strong>Pueblo de Timbukar,</strong> Sonder. Antes de comenzar la actividad de rafting, los participantes recibirán una breve capacitación, incluyendo movimientos básicos e instrucciones de seguridad para mantener el equilibrio en el bote inflable.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Durante el recorrido de rafting, los participantes estarán acompañados por dos guías de rafting experimentados equipados con equipo de seguridad estandarizado internacionalmente. Mientras navegan los emocionantes rápidos del Río Nimanga, los participantes también podrán disfrutar del impresionante paisaje natural a lo largo del recorrido de aproximadamente 90 minutos.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Después, regreso a la ciudad de Manado con desembarco en el punto de encuentro. Fin del tour.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 17 hari 1 (itinerary 2753)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('2753', 'es', 'Itinerario', '<p style="text-align:justify;">El <strong>Monte Lokon</strong> es una de las montañas más grandes de Tomohon y es un volcán activo que se eleva a 1.580 metros sobre el nivel del mar. Como su nombre lo indica, "Lokon" significa el más antiguo y el más grande. Su cráter activo, conocido como <strong>Cráter Tompaluan</strong>, se encuentra en la base de la montaña.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Desde el punto de recogida, conducirás hacia Tomohon o las faldas del Monte Lokon (aproximadamente 1 hora y 30 minutos), luego continuarás con una caminata de aproximadamente 2 horas para llegar al borde del cráter. Actualmente, la caminata no va más allá del cráter, que se encuentra aproximadamente a la mitad del camino hacia la cima.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">El Monte Lokon ofrece un paisaje natural espectacular y un desafío emocionante para los excursionistas. A lo largo del sendero, puedes disfrutar de vistas impresionantes, incluyendo el hermoso panorama de la ciudad de Tomohon.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Después de la aventura de trekking, continúa hacia un restaurante local para el almuerzo. Después del almuerzo, regreso a la ciudad de Manado con desembarco en el punto designado. Fin del tour.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 15 hari 1 (itinerary 2755)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('2755', 'es', 'Itinerario', '<p style="text-align:justify;">Los participantes serán recogidos por la mañana para un tour a la Playa Rap-Rap. Al llegar, los participantes disfrutarán de una experiencia única en la impresionante Playa Rap-Rap, comenzando con un paseo en canoa por las aguas tranquilas que rodean el exuberante bosque de manglares. En pocos minutos, los participantes se embarcarán en una emocionante búsqueda del <strong>Tarsio</strong>, un fascinante primate diminuto que se encuentra a menudo entre los árboles de manglar.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">La serena atmósfera natural y los sonidos del bosque acompañan este viaje, creando un momento inolvidable en medio de la belleza de la naturaleza de Sulawesi del Norte. Al ver al <strong>Tarsio</strong>, los participantes son libres de tomar fotos y capturar el momento.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Después, el tour continúa de regreso a la costa de Rap-Rap antes de dirigirse hacia el altiplano del Monte Tumpa, donde los participantes pueden ser testigos de un hermoso <strong>atardecer</strong> desde las laderas mientras disfrutan de <strong>varios bocadillos tradicionales de Manado</strong> como plátano frito con salsa de sambal roa, camote frito con azúcar de palma y hielo de frijoles rojos <i>(opcional, a cargo del participante)</i>. Después, los participantes serán trasladados de vuelta al punto de encuentro. Fin del tour.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 14 hari 1 (itinerary 2756)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('2756', 'es', 'Itinerario', '<p style="text-align:justify;">Punto de encuentro en el Monte Tumpa a las 10:00 AM.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">El parapente en el <strong>Monte Tumpa </strong>es una experiencia inolvidable tanto para los amantes de la aventura como para los amantes de la naturaleza. Volando a una altitud de aproximadamente 1.000 metros, sentirás la emocionante sensación de volar libremente como un pájaro mientras disfrutas de vistas impresionantes del paisaje montañoso, exuberantes bosques verdes y el mar azul cristalino debajo.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">El sitio de parapente en el Monte Tumpa es también un lugar seguro e ideal tanto para principiantes como para quienes buscan mejorar sus habilidades de parapente, gracias a sus condiciones climáticas estables y vientos suaves. Estarás acompañado por instructores profesionales de parapente y equipado con equipo de seguridad adecuado.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">El parapente en el Monte Tumpa es una experiencia emocionante pero hermosa que hará que tu viaje a Manado sea verdaderamente inolvidable.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 27 hari 1 (itinerary 4915)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('4915', 'es', 'Itinerario', '<p style="text-align:justify;">Después del desayuno en tu hotel en Manado, sales hacia el <strong>Monte Soputan</strong>, uno de los volcanes más activos de Sulawesi del Norte, reconocido por su dramático paisaje volcánico y sus impresionantes paisajes naturales.</p><p style="text-align:justify;">🕐 <strong>Tiempo de viaje desde Manado hasta la base del Monte Soputan:</strong> aproximadamente <strong>2,5–3 horas en automóvil</strong>, dependiendo del tráfico y las condiciones climáticas.</p><p style="text-align:justify;">A lo largo del viaje, disfruta de pintorescas vistas del campo, plantaciones de coco y los hermosos paisajes montañosos de Sulawesi del Norte, convirtiendo el viaje en sí en parte de la experiencia.</p><p style="text-align:justify;">Al llegar al punto de trekking, prepárate para una emocionante caminata al <strong>Monte Soputan</strong>. La ruta de trekking presenta una combinación única de exuberantes senderos forestales, sabana abierta, formaciones rocosas volcánicas y paisajes espectaculares formados por actividad volcánica pasada.</p><p style="text-align:justify;">🕐 <strong>Duración estimada de la caminata (ida y vuelta):</strong> aproximadamente <strong>4–5 horas</strong>, dependiendo de las condiciones climáticas, el nivel de condición física y el ritmo de caminata.</p><p style="text-align:justify;">📸 Disfruta de impresionantes vistas panorámicas y un dramático terreno volcánico en el camino — una experiencia gratificante tanto para amantes de la naturaleza, fotógrafos y buscadores de aventura.</p><p style="text-align:justify;">Después de completar la caminata, regresa al vehículo y traslado a tu hotel en Manado para un descanso bien merecido.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 26 hari 1 (itinerary 5010)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5010', 'es', 'Itinerario', '<p style="text-align:justify;">Punto de encuentro a las 8:00 AM con el guía turístico en el <strong>Muelle de Megamas </strong>para un tour de un día de <strong>isla en isla. </strong>Desde el Muelle de Megamas, cruce en bote hacia la <strong>Isla de Bunaken </strong>(aproximadamente 30 minutos).&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Al llegar, los huéspedes visitarán el <strong>Parque Marino de Bunaken</strong>, reconocido por sus impresionantes arrecifes de coral y miles de especies de peces coloridos alrededor de la <strong>Isla de Bunaken</strong>. La <strong>Isla de Bunaken</strong> ahora cuenta con un área más atractiva y bien desarrollada, incluyendo el <strong>Muelle Turístico de Bunaken</strong>, donde los participantes pueden tomar fotos con familiares y amigos.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Después, los huéspedes podrán disfrutar de actividades opcionales de snorkel o buceo; también pueden nadar mientras alimentan peces directamente con la mano. El almuerzo se servirá en un restaurante local en la <strong>Isla de Bunaken</strong>.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Después del almuerzo, continúan hacia la <strong>Isla de Siladen</strong> y el <strong>Banco de Arena de Nain</strong>. En cada isla, los participantes pueden capturar momentos en fotos o videos, dar un paseo, y disfrutar de la belleza natural de la <strong>Isla de Siladen</strong> y el <strong>Banco de Arena de Nain</strong>.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Por la tarde, regreso al Muelle de Megamas, Manado. Fin del tour.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 22 hari 1 (itinerary 5018)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5018', 'es', 'Itinerario', '<p style="text-align:justify;">Los participantes del tour serán recogidos por el guía turístico en el punto de recogida e inmediatamente comenzarán el Tour de la Ciudad: dirigiéndose hacia el centro de la ciudad de Manado, el área de Chinatown, y el <strong>Templo Ban Hin Kiong</strong> (el templo más antiguo de Manado, construido en el siglo XVIII, aproximadamente 300 años).&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">El tour también pasará por la <strong>Iglesia de Sentrum</strong> (la primera iglesia protestante de Sulawesi del Norte, un remanente de la era colonial holandesa) y el Monumento de la Segunda Guerra Mundial (un recordatorio de la destrucción de la ciudad de Manado en 1942 por las fuerzas japonesas). El almuerzo se servirá en un <strong>restaurante local con una especialidad de atún</strong>, cocinado al estilo tradicional de Manado.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Después, el tour se dirigirá al área de Ring Road de CitraLand para ver de cerca el encanto del <strong>Monumento de Jesús Bendiciendo</strong> — una estatua de Jesús construida en una posición única inclinada hacia adelante, mirando hacia la ciudad de Manado. Luego, el tour continuará hacia la <strong>Colina de Makatete</strong> — una cima a 200 metros sobre el nivel del mar, que ofrece vistas de la ciudad de Manado, la Isla de Manado, la Isla de Bunaken, la Isla de Siladen, extensiones del mar, y el Monte Klabat, la montaña más alta de Sulawesi del Norte.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">La cena es opcional. Después de la cena, los participantes serán trasladados de vuelta al punto de recogida. El tour concluye.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 20 hari 1 (itinerary 5019)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5019', 'es', 'Itinerario', '<p style="text-align:justify;">Los participantes del tour serán recogidos por la mañana por el guía turístico para un viaje al <strong>Altiplano de Minahasa</strong>, pasando por el área de <strong>Tinoor</strong> donde los participantes pueden disfrutar de una vista de la ciudad de Manado desde una elevación de 500 metros. Al llegar a Tomohon, el grupo visitará el <strong>Taman Wisata Pelangi</strong>, donde podrán admirar la belleza de varias flores coloridas.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">La siguiente parada es el <strong>Mercado Extremo de Tomohon</strong>, donde los participantes pueden observar de cerca varios tipos de carne de animales salvajes, como <i><strong>paniki (murciélago), ratas de bosque, serpientes y otros animales salvajes</strong></i>. En un lugar diferente, los participantes también tendrán la oportunidad de ser testigos del <strong>proceso de cocina en vivo </strong>de pasteles tradicionales de Manado como <strong>cucur, apang gula merah, dodol</strong>, y otros dulces locales.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">A continuación, el tour se dirige al <strong>Bosque de Palmeras de Aren</strong> con lugares fotográficos dignos de Instagram en <strong>Tuur Maasering</strong>. Además de los interesantes lugares fotográficos, los participantes también observarán el proceso de fabricación del <i><strong>licor local </strong></i><strong>\'Cap Tikus\'</strong>, que se produce mediante la fermentación y destilación de la savia del árbol de aren.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">El almuerzo se servirá en un restaurante local junto al <strong>Lago Tondano</strong>. Después del almuerzo, el viaje continúa hacia <strong>Bukit Kasih</strong>, una atracción natural única con cráteres de azufre activos y escaleras que conducen a la cima de la colina, ofreciendo vistas panorámicas y una experiencia cultural distintiva. El área también cuenta con aguas termales de azufre naturales donde los huéspedes pueden nadar o remojar sus pies para relajarse (opcional).&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">El viaje continúa hacia el <strong>Lago Linow</strong>, un lago de azufre conocido por sus colores de agua cambiantes y su hermoso y sereno paisaje (se sirve café o té). Después, regreso a la ciudad de Manado. La cena es opcional. Después de la cena, los participantes serán trasladados al punto de desembarco designado. Fin del tour.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 30 hari 1 (itinerary 5156)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5156', 'es', 'Llegada a Manado - Paradise Golf Resort', '<p style="text-align:justify;">Al llegar al Aeropuerto Internacional Sam Ratulangi de Manado, serás recibido por nuestro equipo y trasladado directamente al Paradise Hotel &amp; Golf Resort. El viaje ofrece el ambiente tranquilo y refrescante de la costa de Sulawesi del Norte.</p><p style="text-align:justify;">Al llegar al resort, check-in y el resto del día puede disfrutarse con las instalaciones del hotel, las vistas del campo de golf, o simplemente el cómodo entorno tropical. El primer día está diseñado como tiempo para relajarse antes de que comience la experiencia de golf a la mañana siguiente.</p><p style="text-align:justify;">Pernoctación en el Paradise Hotel &amp; Golf Resort.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 30 hari 2 (itinerary 5157)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5157', 'es', 'Experiencia Paradise Golf (18 Hoyos)', '<p style="text-align:justify;">Después del desayuno en el hotel, disfruta de una ronda en el Paradise Golf Course, que combina calles desafiantes con impresionante paisaje natural.</p><p style="text-align:justify;">La ronda de 18 hoyos incluye green fee, carrito de golf y caddie, para que puedas concentrarte en tu juego con total comodidad. Después del juego, el tiempo libre puede pasarse relajándote en el resort o participando en actividades opcionales disponibles alrededor del área del hotel.</p><p style="text-align:justify;">Pernoctación en el Paradise Hotel &amp; Golf Resort.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 30 hari 3 (itinerary 5158)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5158', 'es', 'Experiencia Paradise Golf (18 Hoyos)', '<p style="text-align:justify;">Desayuno en el hotel antes de la segunda sesión de golf. Hoy es la oportunidad de volver a jugar el campo y apreciar cómo cada hoyo tiene un carácter propio, en el tranquilo entorno tropical y el aire fresco de Sulawesi del Norte.</p><p style="text-align:justify;">Después de la ronda, disfruta de tiempo libre para descansar, usar las instalaciones del resort, o participar en actividades opcionales como snorkel o un paseo en bote de fondo de cristal disponibles en el área del resort.</p><p style="text-align:justify;">Pernoctación en el Paradise Hotel &amp; Golf Resort.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 30 hari 4 (itinerary 5159)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5159', 'es', 'Salida de Manado', '<p style="text-align:justify;">Después del desayuno y el check-out en el hotel, tendrás tiempo libre antes de la salida.</p><p style="text-align:justify;">A la hora acordada, nuestro equipo te trasladará al Aeropuerto Internacional Sam Ratulangi de Manado para tu vuelo de continuación. Mientras este viaje llega a su fin, esperamos que tu golf en el Paradise Golf Resort permanezca como un grato recuerdo de tu tiempo en Sulawesi del Norte.</p><p style="text-align:justify;"><strong>Fin del Programa</strong></p>', NOW(), NOW())
