-- paket 29 hari 1 (itinerary 5160)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5160', 'es', 'Llegada a Manado - Paradise Golf Resort', '<p style="text-align:justify;">Al llegar al Aeropuerto Internacional Sam Ratulangi de Manado, serás recibido por nuestro equipo y trasladado al Paradise Hotel &amp; Golf Resort en la costa de Sulawesi del Norte. El viaje dura aproximadamente 60–90 minutos, con hermoso campo y costa en el camino.</p><p style="text-align:justify;">Al llegar al resort, check-in y el resto del día puede disfrutarse relajándote en su entorno tranquilo, usando las instalaciones del hotel, o disfrutando de las vistas del campo de golf que domina el mar. El primer día está diseñado como tiempo para relajarse antes de que comiencen las actividades principales a la mañana siguiente.</p><p style="text-align:justify;">Pernoctación en el Paradise Hotel &amp; Golf Resort.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 29 hari 2 (itinerary 5161)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5161', 'es', 'Experiencia Paradise Golf (18 Hoyos)', '<p style="text-align:justify;">Después del desayuno, disfruta de una ronda en uno de los mejores campos de golf de Sulawesi del Norte. El campo combina calles desafiantes con aire marino fresco y panoramas tropicales agradables de recorrer.</p><p style="text-align:justify;">La ronda de 18 hoyos incluye green fee, carrito de golf y caddie, para que puedas jugar con total comodidad. Después, el tiempo libre puede pasarse descansando, usando las instalaciones del resort, o simplemente relajándote en el tranquilo entorno tropical.</p><p style="text-align:justify;">Pernoctación en el Paradise Hotel &amp; Golf Resort.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 29 hari 3 (itinerary 5162)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5162', 'es', 'Experiencia de Avistamiento de la Isla de Bunaken', '<p style="text-align:justify;">Después del desayuno y el check-out del resort, se continúa hacia la ciudad de Manado y el Muelle de Megamas. Desde aquí cruzarás en bote hacia la Isla de Bunaken, un viaje de aproximadamente 45 minutos.</p><p style="text-align:justify;">Al llegar a Bunaken, tómate tiempo para explorar el área remodelada de New Bunaken, con sus muchos lugares atractivos que dan directamente al mar azul de Sulawesi. La isla ofrece hermosos paisajes de playa, un ambiente tropical tranquilo, y numerosos lugares ideales para la fotografía y simplemente para disfrutar de la belleza natural.</p><p style="text-align:justify;">Para quienes deseen explorar más, hay disponibles opcionalmente snorkel o buceo para experimentar el reconocido Parque Marino de Bunaken. El almuerzo se sirve con pescado a la parrilla fresco y el sambal dabu-dabu característico de Manado.</p><p style="text-align:justify;">Por la tarde, regreso a Manado y continuación hacia tu hotel seleccionado en el centro de la ciudad para el check-in y el descanso.</p><p style="text-align:justify;">Pernoctación en un hotel seleccionado en Manado.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 29 hari 4 (itinerary 5163)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5163', 'es', 'Salida de Manado', '<p style="text-align:justify;">Después del desayuno en el hotel, tendrás tiempo libre antes de la salida. A la hora acordada, nuestro equipo te recogerá y te trasladará al Aeropuerto Internacional Sam Ratulangi de Manado para tu vuelo de continuación.</p><p style="text-align:justify;">Mientras este viaje llega a su fin, esperamos que el golf junto al mar y la belleza de la Isla de Bunaken permanezcan como un grato recuerdo de tus vacaciones en Sulawesi del Norte.</p><p style="text-align:justify;"><strong>Fin del Programa</strong></p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 32 hari 1 (itinerary 5221)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5221', 'es', 'Llegada a Manado – Traslado a la Isla de Bangka', '<p style="text-align:justify;">Al llegar al Aeropuerto Internacional Sam Ratulangi de Manado, serás recibido por nuestro equipo y comenzarás el viaje hacia el muelle para el cruce a la Isla de Bangka. El traslado combinado por tierra y mar hacia el resort dura aproximadamente 2 horas, siguiendo la hermosa costa norte de Sulawesi con vistas al mar y sus encantadoras islas tropicales.</p><p style="text-align:justify;">Al llegar al <strong>Dive Resort</strong>, check-in y tiempo libre para relajarte, pasear por los alrededores, o disfrutar del ambiente tranquilo de la playa. La cena se sirve en el resort antes de descansar y prepararte para la aventura submarina que comienza a la mañana siguiente.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 32 hari 2 (itinerary 5222)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5222', 'es', 'Experiencia de Buceo en Bangka', '<p style="text-align:justify;">Después del desayuno, disfruta del buceo en una selección de sitios alrededor del Archipiélago de Bangka, un área conocida por su combinación de corales blandos coloridos, corales duros saludables, y extraordinaria biodiversidad marina.</p><p style="text-align:justify;">Las aguas de Bangka tienen un carácter propio, combinando el buceo de pared característico de Bunaken con el muck diving del Estrecho de Lembeh. Durante las inmersiones podrás encontrar una amplia variedad de peces tropicales, vida marina macro, y espectaculares formaciones submarinas.</p><p style="text-align:justify;">Una vez terminadas las inmersiones del día, regreso al resort y tiempo libre para relajarte en el ambiente pacífico de la isla.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 32 hari 3 (itinerary 5223)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5223', 'es', 'Experiencia de Buceo en Bangka', '<p style="text-align:justify;">Desayuno en el resort antes de continuar explorando el mundo submarino de Bangka. Hoy visitarás diferentes sitios de buceo que ofrecen paisajes variados, desde arrecifes coloridos y pináculos submarinos hasta paredes sumergidas que albergan una amplia variedad de especies marinas tropicales.</p><p style="text-align:justify;">Con más de 40 sitios de buceo repartidos por el Archipiélago de Bangka, cada inmersión trae algo nuevo tanto para principiantes como para buceadores experimentados.</p><p style="text-align:justify;">Regreso al resort por la tarde y tiempo para relajarte en la playa o en las instalaciones del resort.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 32 hari 4 (itinerary 5224)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5224', 'es', 'Experiencia de Buceo en Bangka', '<p style="text-align:justify;">Después del desayuno, continúa la aventura de buceo para explorar más de la belleza submarina del Archipiélago de Bangka. El área es considerada uno de los mejores destinos de buceo de Sulawesi del Norte, con aguas claras y un ecosistema marino que permanece notablemente bien preservado.</p><p style="text-align:justify;">Disfruta de esta última oportunidad de observar la riqueza de la vida marina tropical, los arrecifes de coral saludables, y los panoramas submarinos que hacen de Bangka una joya escondida para los buceadores en Indonesia.</p><p style="text-align:justify;">Después de las inmersiones, regreso al resort para una tarde relajante y tu última cena en la isla.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 32 hari 5 (itinerary 5225)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5225', 'es', 'Isla de Bangka - Salida', '<p style="text-align:justify;">Después del desayuno y el check-out, el viaje de regreso a Manado comienza con un traslado en bote hacia el continente, continuando hacia el Aeropuerto Internacional Sam Ratulangi de Manado o tu hotel seleccionado en la ciudad.</p><p style="text-align:justify;">Mientras este viaje llega a su fin, esperamos que la exploración de la belleza submarina del Archipiélago de Bangka permanezca como un recuerdo inolvidable y una nueva historia de uno de los mejores destinos de buceo de Sulawesi del Norte.</p><p style="text-align:justify;"><strong>Fin del Programa</strong></p>', NOW(), NOW())
