-- paket 33 hari 1 (itinerary 5226)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5226', 'es', 'Llegada a Manado - Traslado a la Isla de Lembeh', '<p style="text-align:justify;">Al llegar al Aeropuerto Internacional Sam Ratulangi de Manado, serás recibido por nuestro equipo y comenzarás directamente el viaje hacia el muelle para el cruce a la Isla de Lembeh. El traslado hacia el resort dura aproximadamente 1 hora y 40 minutos, combinando viaje terrestre y traslado en bote a lo largo de la hermosa costa de Sulawesi del Norte.</p><p style="text-align:justify;">Al llegar al resort, check-in y tiempo libre para descansar, pasear por los alrededores, o disfrutar de la tranquilidad de la Isla de Lembeh, conocida como uno de los mejores destinos de buceo del mundo. La cena se servirá en el resort antes de descansar y prepararte para la aventura submarina que comienza a la mañana siguiente.</p><p style="text-align:justify;">&nbsp;</p>', NOW(), NOW())
