-- paket 33 hari 2 (itinerary 5227)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5227', 'es', 'Experiencia de Buceo en el Estrecho de Lembeh', '<p style="text-align:justify;">Después del desayuno, la aventura de buceo comienza en una selección de sitios en el Estrecho de Lembeh, conocido como uno de los mejores lugares de muck diving del mundo. Su fondo de arena negra volcánica crea un hábitat único que alberga una asombrosa variedad de especies marinas raras y exóticas.</p><p style="text-align:justify;">Durante las inmersiones podrás encontrar diversas criaturas apreciadas por los fotógrafos submarinos, desde peces sapo y nudibranquios hasta especies difíciles de encontrar en otro lugar. Después de dos inmersiones matutinas, regreso al resort para tiempo libre y cena.</p>', NOW(), NOW())
