-- paket 36 hari 2 (itinerary 5253)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5253', 'es', 'Experiencia de Buceo en el Estrecho de Lembeh', '<p style="text-align:justify;">Después del desayuno, la aventura submarina comienza con dos inmersiones matutinas en algunos de los mejores sitios del Estrecho de Lembeh. Este destino es conocido como uno de los lugares principales del mundo para el muck diving y la fotografía macro, con su fondo de arena negra volcánica formando un hábitat único para una gran cantidad de especies marinas raras.</p><p style="text-align:justify;">Durante las inmersiones podrás encontrar criaturas inusuales como peces sapo, nudibranquios y caballitos de mar, junto con otros sujetos exóticos buscados por fotógrafos submarinos de todo el mundo. Después de las inmersiones, regreso al resort para almuerzo y tiempo libre.</p>', NOW(), NOW())
