-- paket 39 hari 1 (itinerary 6223)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6223', 'es', 'Itinerario', '<p style="text-align:justify;">Después del desayuno, nuestro equipo te recogerá en tu hotel en la ciudad de Manado. El viaje continúa hacia el Muelle Serei Likupang, con paisajes costeros y rurales típicos de Sulawesi del Norte en el camino. Al llegar al muelle, abordarás un bote privado hacia las aguas alrededor de la Isla de Gangga, uno de los mejores destinos de snorkel en el área de Likupang. Aquí podrás disfrutar de arrecifes de coral prístinos, una abundancia de peces tropicales coloridos y aguas claras con excelente visibilidad.</p><p style="text-align:justify;">Después del snorkel, se continúa hacia la Isla de Lihaga, conocida por su suave arena blanca y su mar turquesa. Disfruta de tiempo para nadar, relajarte en la orilla, caminar alrededor de la isla, o capturar el momento en varios lugares fotográficos con impresionantes paisajes tropicales de fondo. El almuerzo se servirá en la Isla de Lihaga en un ambiente tranquilo y natural.</p><p style="text-align:justify;">Por la tarde, regreso en bote al Muelle Serei Likupang antes de continuar por tierra hacia la ciudad de Manado. Antes de regresar a tu hotel, parada en un centro de recuerdos de Manado para comprar delicias locales, artesanías y recuerdos. Después serás trasladado a tu hotel, llevando contigo una experiencia inolvidable de las dos islas tropicales más hermosas de Likupang.</p><p style="text-align:justify;"><strong>Fin del Tour</strong></p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 24 hari 1 (itinerary 6888)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6888', 'es', 'Llegada – Cascada de Tunan – Reserva Natural de Tangkoko', '<p style="text-align:justify;">Llegada a Manado por la mañana. Encuentro con nuestro guía, luego continúas para dirigirte a la <strong>Cascada de Tunan</strong>, esta cascada se encuentra en el <strong>Pueblo de Talawan</strong>. La fuente de la <strong>Cascada de Tunan</strong> proviene del río sobre la montaña que fluye bastante rápido a través de acantilados empinados con una altura de aproximadamente 86 metros. La atmósfera del bosque natural aún prístino e intacto añade a la belleza alrededor del objeto de turismo natural <strong>Cascada de Tunan</strong>.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Conducimos directamente hacia el <strong>Parque Nacional de Tangkoko</strong> (si llegas por la tarde, omite el viaje a la Cascada de Tunan y ve directamente al pueblo de Batu Putih en Tangkoko). Al final de la tarde, una breve caminata por el bosque en busca de la gran estrella del parque: el Tarsio, el mamífero más pequeño del planeta. El Homestay de Tangkoko es donde pasarás la noche.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 24 hari 2 (itinerary 6889)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6889', 'es', 'Tour de un Día Completo a Tangkoko', '<p style="text-align:justify;">Después del desayuno en el homestay, comienza a explorar las especies endémicas de Sulawesi del Norte en la Reserva Natural de Tangkoko. Busca al Macaco Negro Crestado (mono negro nativo de Sulawesi del Norte), otro Tarsio (el primate más pequeño del mundo), el Oso Cuscús, y numerosas aves. El parque nacional es hogar de la mayor densidad de Cálaos del mundo, incluyendo el Cálao Rinoceronte. Después del almuerzo, iremos a otra excursión por la selva de Tangkoko por la tarde. Pernoctación en el homestay.&nbsp;</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 24 hari 3 (itinerary 6890)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6890', 'es', 'Waruga Sawangan – Tour del Altiplano de Minahasa', '<p style="text-align:justify;">Después del desayuno, check-out y conducción hacia el altiplano, luego continúas hacia <strong>Waruga Sawangan</strong>, con una parada en la antigua tumba del pueblo Minahasa (Era de la Piedra Gigante). Almuerzo en el <strong>Lago Tondano</strong>. Continúas hacia Tomohon para ver el <strong>mercado tradicional</strong>, después la industria de casas de madera desmontables del <strong>Pueblo de Woloan</strong> (los lugareños aquí crean exquisitas casas de madera al estilo Minahasa que se desmontan y se envían fuera del pueblo), y <strong>Kai\'santi Tomohon</strong> que es una parada fotográfica con un telón de fondo escénico del Monte Lokon &amp; arrozales verdes.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Pasamos la tarde en el <strong>Lago Linow</strong> tomando café o té. Check-in en tu habitación en un resort en Tomohon.&nbsp;</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 24 hari 4 (itinerary 6891)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6891', 'es', 'Mt. Mahawu – Traslado al Aeropuerto', '<p style="text-align:justify;">Después del desayuno en el hotel, check-out. Encuentro con nuestro guía, luego continúas hacia el <strong>cráter del Mt. Mahawu</strong>. Después de una caminata de 10 minutos hasta el borde del cráter, serás recompensado con una vista impresionante de Tomohon y Manado, así como de las islas más allá; en el fondo del cráter, los visitantes pueden ver un lago humeante y sentir el olor a azufre de las pozas. Después, serás acompañado por nuestro guía turístico al aeropuerto para el traslado de salida.&nbsp;</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 25 hari 1 (itinerary 6892)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6892', 'es', 'Llegada – Altiplano de Minahasa – Reserva Natural de Tangkoko', '<p style="text-align:justify;">Llegada a Manado por la mañana. Encuentro con nuestro guía, luego continúas hacia el <strong>cráter del Mt. Mahawu</strong>. Después de una caminata de 10 minutos hasta el borde del cráter, serás recompensado con una vista impresionante de Tomohon y Manado, así como de las islas más allá. Después, visita al <strong>pueblo de Woloan</strong>, el centro de la industria de casas tradicionales desmontables, y parada en el <strong>Templo Budista Pagoda</strong>, que es una parada fotográfica con un telón de fondo escénico del Monte Lokon. Relájate en los magníficos colores multicolores del <strong>Lago Linow</strong> para disfrutar de la tarde en un agradable restaurante junto al lago tomando café o té.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">La caminata continúa hacia <strong>Waruga Sawangan</strong>, con una parada en la antigua tumba del pueblo Minahasa (Era de la Piedra Gigante). Toma el camino hacia Tangkoko. (Si llegas por la tarde, omite el viaje al Altiplano de Minahasa y ve directamente al pueblo de Batu Putih en Tangkoko.) El Homestay de Tangkoko es donde pasarás la noche.&nbsp;</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

