-- paket 25 hari 3 (itinerary 6894)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6894', 'es', 'Traslado al Aeropuerto', '<p style="text-align:justify;">Después del desayuno en el hotel, check-out. Visita a la ciudad para comprar recuerdos si el tiempo lo permite. Después, serás acompañado por nuestro guía turístico al aeropuerto para el traslado de salida. El tour ha terminado, gracias.&nbsp;</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 13 hari 1 (itinerary 6895)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6895', 'es', 'Llegada – Tour de la Ciudad de Manado – Colina de Makatete – SunBae Manado', '<p style="text-align:justify;">Al llegar al Aeropuerto Sam Ratulangi de Manado, el grupo será recibido por el guía turístico y comenzará un tour por la ciudad de Manado. Visita al centro de la ciudad, la <strong>Chinatown</strong>, y el <strong>Templo Ban Hin Kiong</strong> - el templo más antiguo de Manado, construido en el siglo XVIII (aproximadamente 300 años).&nbsp;Se continúa pasando por la <strong>Iglesia de Sentrum</strong>, la primera iglesia protestante de Sulawesi del Norte de la era holandesa, y el <strong>Monumento de la Segunda Guerra Mundial</strong>, que conmemora la destrucción de Manado en 1942 por las fuerzas japonesas.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">El tour luego continúa hacia el área de Ring Road de <strong>CitraLand</strong> para ver el <strong>Monumento de Jesús Bendiciendo</strong>, una estatua de Jesús construida en una posición única inclinada hacia adelante mirando hacia la ciudad de Manado.&nbsp;Después, visita a la <strong>Colina de Makatete</strong> - ubicada a 200 metros sobre el nivel del mar, ofreciendo vistas panorámicas de la ciudad de Manado, la <strong>Isla de Manado Tua</strong>, la <strong>Isla de Bunaken</strong>, la <strong>Isla de Siladen</strong>, el mar abierto, y el <strong>Monte Klabat</strong>, el pico más alto de Sulawesi del Norte.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Cena opcional en un restaurante local. Después de la cena, visita a <strong>SunBae</strong>, uno de los puntos de encuentro de moda junto al mar de Manado, donde los huéspedes pueden disfrutar del ambiente nocturno junto con varios bocadillos y bebidas de numerosos puestos de comida (opcional). Después, traslado al hotel para el check-in y el descanso.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 13 hari 2 (itinerary 6896)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6896', 'es', 'Tour de Avistamiento de Bunaken – Fábrica Local de Café – Tour de Compras', '<p style="text-align:justify;">Después del desayuno en el hotel, los participantes serán recogidos por el guía y se dirigirán hacia la <strong>Isla de Bunaken</strong>. Desde el hotel, traslado al Muelle de Megamas y cruce en bote hacia Bunaken durante aproximadamente 30 minutos. La Isla de Bunaken ahora cuenta con el nuevo <strong>Muelle Turístico de Bunaken (New Bunaken)</strong>, ofreciendo un lugar más encantador y fotogénico para fotos y videos.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Después, los participantes serán llevados a explorar la belleza del <strong>Parque Marino de Bunaken</strong>, reconocido por sus vibrantes arrecifes de coral y diversa vida marina tropical. Los participantes podrán disfrutar de actividades <i>opcionales</i><strong> de snorkel o buceo</strong>, o simplemente dar un paseo tranquilo relajándose y disfrutando del ambiente de la playa de Bunaken.&nbsp; Almuerzo opcional en un restaurante local. Después del almuerzo, los huéspedes tendrán tiempo libre adicional para snorkel/buceo opcional.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Regreso al Muelle de Megamas y continuación hacia la visita de una <strong>fábrica local de producción de café</strong>, donde los participantes podrán probar los sabores auténticos del café de Sulawesi del Norte. Después, se continúa hacia una <strong>zona de compras de recuerdos</strong> que ofrece una gran variedad de especialidades de Manado (o regreso al hotel primero y recogida nuevamente antes de la cena). Cena opcional en un restaurante local, seguida del traslado de regreso al hotel.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 13 hari 3 (itinerary 6897)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6897', 'es', 'Traslado al Aeropuerto – Salida', '<p style="text-align:justify;">Después del desayuno y el check-out en el hotel, los participantes serán recogidos por el guía y trasladados directamente al aeropuerto para su vuelo de regreso. Fin del tour.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 12 hari 1 (itinerary 6898)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6898', 'es', 'Llegada – Tour de la Ciudad de Manado – Colina de Makatete – SunBae Manado', '<p style="text-align:justify;">Al llegar al Aeropuerto Sam Ratulangi de Manado, el grupo será recibido por el guía turístico y comenzará un tour por la ciudad de Manado. Visita al centro de la ciudad, la <strong>Chinatown</strong>, y el <strong>Templo Ban Hin Kiong</strong> - el templo más antiguo de Manado, construido en el siglo XVIII (aproximadamente 300 años).&nbsp;Se continúa pasando por la <strong>Iglesia de Sentrum</strong>, la primera iglesia protestante de Sulawesi del Norte de la era holandesa, y el <strong>Monumento de la Segunda Guerra Mundial</strong>, que conmemora la destrucción de Manado en 1942 por las fuerzas japonesas.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">El tour luego continúa hacia el área de Ring Road de <strong>CitraLand</strong> para ver el <strong>Monumento de Jesús Bendiciendo</strong>, una estatua de Jesús construida en una posición única inclinada hacia adelante mirando hacia la ciudad de Manado.&nbsp;Después, visita a la <strong>Colina de Makatete</strong> - ubicada a 200 metros sobre el nivel del mar, ofreciendo vistas panorámicas de la ciudad de Manado, la <strong>Isla de Manado Tua</strong>, la <strong>Isla de Bunaken</strong>, la <strong>Isla de Siladen</strong>, el mar abierto, y el <strong>Monte Klabat</strong>, el pico más alto de Sulawesi del Norte.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Cena opcional en un restaurante local. Después de la cena, visita a <strong>SunBae</strong>, uno de los puntos de encuentro de moda junto al mar de Manado, donde los huéspedes pueden disfrutar del ambiente nocturno junto con varios bocadillos y bebidas de numerosos puestos de comida (opcional). Después, traslado al hotel para el check-in y el descanso.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 12 hari 2 (itinerary 6899)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6899', 'es', 'Tour del Altiplano de Minahasa', '<p style="text-align:justify;">Después del desayuno en el hotel, los participantes serán recogidos por el guía turístico para una excursión de un día completo al <strong>Altiplano de Minahasa</strong>, pasando por el área de Tinoor donde los huéspedes pueden disfrutar de vistas panorámicas de la ciudad de Manado desde una elevación de 500 metros.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Al llegar a Tomohon, visita al <strong>Taman Wisata Pelangi</strong>, donde los participantes podrán admirar la belleza de varias flores coloridas. Se continúa hacia el <strong>Mercado Extremo de Tomohon</strong>, donde los huéspedes podrán ver varios tipos de carne de animales salvajes como murciélagos, ratas de bosque, serpientes y otros animales exóticos. En un lugar separado, los huéspedes también tendrán la oportunidad de ser testigos del <strong>proceso de cocina en vivo</strong> de bocadillos tradicionales de Manado como <i>kue cucur</i>, <i>apang gula merah</i>, <i>dodol</i>, y otras delicias locales.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">El tour continúa hacia <strong>Tuur Maasering</strong>, un bosque de palmeras de aren con varios lugares fotográficos dignos de Instagram. Aquí, los participantes también podrán observar la producción tradicional del licor local <strong>"Cap Tikus"</strong>, producido mediante la fermentación y destilación de la savia del árbol de aren.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Almuerzo opcional en un restaurante local. Después del almuerzo, el viaje continúa hacia <strong>Bukit Kasih</strong>, una atracción natural única con cráteres de azufre activos y escaleras que conducen a la cima de la colina, ofreciendo vistas panorámicas y una experiencia cultural distintiva. El área también cuenta con aguas termales de azufre naturales donde los huéspedes pueden nadar o remojar sus pies para relajarse (opcional).</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Después, visita al <strong>Lago Linow</strong>, un lago de azufre conocido por sus colores de agua cambiantes y su hermoso paisaje, donde se servirá café o té. Regreso a la ciudad de Manado. Cena opcional en un restaurante local, seguida del traslado de regreso al hotel.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

