-- paket 10 hari 4 (itinerary 6916)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6916', 'es', 'Isla de Lihaga – Pueblo Turístico de Budo', '<p style="text-align:justify;">Después del desayuno en el hotel, los participantes serán recogidos por el guía turístico y viajarán al área de Likupang, a aproximadamente 1 hora y 20 minutos del centro de la ciudad de Manado. La primera parada es el <strong>Puerto de Serei</strong>, y al llegar, se continúa en bote durante aproximadamente 15 minutos hacia la <strong>Isla de Lihaga</strong>.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">En la <strong>Isla de Lihaga</strong>, los participantes podrán disfrutar de sus impresionantes playas de arena blanca y suave, explorar la isla, y tomar fotos en varios lugares hermosos y dignos de Instagram. Los huéspedes también pueden unirse a actividades opcionales como snorkel, canoa o buceo. El almuerzo se servirá en la isla. Después del almuerzo, los participantes tendrán tiempo libre adicional para relajarse en la playa.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">En el camino de regreso a Manado, se hace una parada en el <strong>Pueblo Turístico de Budo</strong>, donde los huéspedes pueden disfrutar de un hermoso atardecer acompañado de delicias locales de plátanos fritos y coco fresco. Cena opcional en un restaurante local, seguida del traslado de regreso al hotel.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 10 hari 5 (itinerary 6917)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6917', 'es', 'Traslado al Aeropuerto – Salida', '<p style="text-align:justify;">Después del desayuno y el check-out en el hotel, los participantes serán recogidos por el guía y trasladados directamente al aeropuerto para su vuelo de regreso. Fin del tour.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 28 hari 1 (itinerary 6922)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6922', 'es', 'Llegada a Manado - Paradise Golf Resort', '<p style="text-align:justify;">Al llegar al Aeropuerto Internacional Sam Ratulangi de Manado, serás recibido por nuestro equipo y trasladado directamente al Paradise Hotel &amp; Golf Resort, ubicado a lo largo de la costa de Sulawesi del Norte en un entorno tranquilo y paisaje refrescante.</p><p style="text-align:justify;">El viaje hacia el resort dura aproximadamente 60–90 minutos. Al llegar, check-in y el resto del día es libre para descansar o disfrutar de las instalaciones del resort. Disfruta del ambiente relajado, el aire fresco y las vistas del campo de golf que se extiende por un hermoso paisaje tropical.</p><p style="text-align:justify;">Pernoctación en el Paradise Hotel &amp; Golf Resort.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 28 hari 2 (itinerary 6923)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6923', 'es', 'Experiencia Paradise Golf (18 Hoyos)', '<p style="text-align:justify;">Después del desayuno en el hotel, es hora de disfrutar de una ronda en uno de los mejores campos de golf de Sulawesi del Norte.</p><p style="text-align:justify;">Juega 18 hoyos completos con carrito de golf y caddie incluido. El campo combina calles desafiantes con impresionantes panoramas naturales, creando una ronda agradable tanto para golfistas experimentados como para principiantes.</p><p style="text-align:justify;">Después del juego, eres libre de relajarte en el resort, disfrutar del entorno, o pasar tiempo con la familia y compañeros de viaje.</p><p style="text-align:justify;">Pernoctación en el Paradise Hotel &amp; Golf Resort.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 28 hari 3 (itinerary 6924)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6924', 'es', 'Escape a la Playa Blanca de la Isla de Lihaga', '<p style="text-align:justify;">Después del desayuno, se continúa hacia el Puerto de Serei y cruce en bote privado hacia la Isla de Lihaga, una de las islas tropicales más hermosas de Sulawesi del Norte, conocida por su arena blanca excepcionalmente fina y aguas turquesas cristalinas.</p><p style="text-align:justify;">Disfruta de tiempo para relajarte en la playa, nadar, tomar fotos, o simplemente disfrutar de la belleza intacta de la isla. Para quienes desean más actividad, hay disponibles opcionalmente snorkel, canoa y paseos en bote de fondo de cristal para explorar el paisaje submarino alrededor de la isla.</p><p style="text-align:justify;">El almuerzo se sirve en la isla con una especialidad de Sulawesi del Norte de pescado a la parrilla fresco acompañado del sambal dabu-dabu característico de Manado. Después de disfrutar de la Isla de Lihaga, regreso al Puerto de Serei y continuación hacia el hotel.</p><p style="text-align:justify;">La tarde es libre para descansar y disfrutar del ambiente del resort.</p><p style="text-align:justify;">Pernoctación en el Paradise Hotel &amp; Golf Resort.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 28 hari 4 (itinerary 6925)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6925', 'es', 'Salida de Manado', '<p style="text-align:justify;">Después del desayuno y el check-out en el hotel, tendrás tiempo libre antes de la salida.</p><p style="text-align:justify;">A la hora acordada, nuestro equipo te trasladará al Aeropuerto Internacional Sam Ratulangi de Manado para tu vuelo de continuación.</p><p style="text-align:justify;">Mientras este viaje llega a su fin, esperamos que el golf y la belleza de la Isla de Lihaga permanezcan como un grato recuerdo de tus vacaciones en Sulawesi del Norte.</p><p style="text-align:justify;"><strong>Fin del Programa</strong></p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 34 hari 1 (itinerary 6936)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6936', 'es', 'Llegada a Manado', '<p style="text-align:justify;">Al llegar al Aeropuerto Internacional Sam Ratulangi de Manado, serás recibido por nuestro equipo y trasladado a tu hotel o resort seleccionado para el check-in. El viaje hacia tu alojamiento dura aproximadamente 30–60 minutos dependiendo de su ubicación.</p><p style="text-align:justify;">El resto del día es tuyo para descansar, disfrutar de las instalaciones del hotel, o relajarte en el ambiente costero de Sulawesi del Norte en preparación para la aventura submarina que comienza a la mañana siguiente.</p><p style="text-align:justify;">Pernoctación en tu hotel o resort seleccionado.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 34 hari 2 (itinerary 6937)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6937', 'es', 'Experiencia de Buceo en Bunaken', '<p style="text-align:justify;">Después del desayuno, se continúa hacia el Parque Marino de Bunaken, ampliamente considerado uno de los mejores destinos de buceo de Indonesia. Viajando en bote de buceo, visitarás una selección de sitios para explorar espectaculares paredes de coral, coloridos jardines de coral, y un ecosistema marino rico en vida.</p><p style="text-align:justify;">Bunaken es reconocido por su extraordinario buceo de pared, excelente visibilidad, y la posibilidad de ver tortugas verdes y tortugas carey, una amplia variedad de peces de arrecife tropicales, y depredadores como barracudas y tiburones de arrecife. Después de las inmersiones, regreso al hotel para almuerzo y tiempo libre.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 34 hari 3 (itinerary 6938)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6938', 'es', 'Experiencia de Buceo en Bunaken', '<p style="text-align:justify;">Desayuno antes de regresar a explorar la belleza submarina de Bunaken. Hoy visitarás diferentes sitios de buceo, cada uno con carácter propio, combinando jardines de coral, paredes de arrecife, y abundante vida marina.</p><p style="text-align:justify;">Aprovecha la oportunidad de observar una amplia variedad de especies marinas tropicales, desde peces de arrecife coloridos hasta pequeñas criaturas que se escoden entre los corales. Después del programa de buceo, regreso al hotel para descansar y disfrutar de una tarde relajante.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 34 hari 4 (itinerary 6939)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6939', 'es', 'Cascada de Tunan &amp; Tour de Fauna Salvaje de Tangkoko', '<p style="text-align:justify;">Después del desayuno, viaje hacia el área de Talawaan para visitar la Cascada de Tunan, escondida en lo profundo del bosque tropical. Cayendo desde una altura de aproximadamente 86 metros, ofrece un entorno natural refrescante y es una de las joyas escondidas de Sulawesi del Norte.</p><p style="text-align:justify;">El viaje continúa hacia la Reserva Natural de Tangkoko, el área de conservación de fauna salvaje más conocida de Sulawesi del Norte. Acompañado por un guardaparques local experimentado, harás una caminata ligera por el bosque tropical en busca de especies endémicas como el Yaki (macaco negro crestado de Sulawesi), el tarsio, el cálao, y el cuscús que viven libremente en su hábitat natural.</p><p style="text-align:justify;">Después de esta experiencia única con la fauna salvaje, regreso a Manado y a tu hotel.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 34 hari 5 (itinerary 6940)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6940', 'es', 'Salida de Manado', '<p style="text-align:justify;">Después del desayuno y el check-out, serás recogido y trasladado al Aeropuerto Internacional Sam Ratulangi de Manado según tu horario de vuelo.</p><p style="text-align:justify;">Mientras este viaje llega a su fin, esperamos que la exploración de la belleza submarina de Bunaken y el encuentro con la fauna endémica de Sulawesi en Tangkoko permanezcan como un recuerdo inolvidable de tu estancia en Sulawesi del Norte.</p><p style="text-align:justify;"><strong>Fin del Programa</strong></p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 16 hari 1 (itinerary 6973)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6973', 'es', 'Itinerario', '<p style="text-align:justify;">Todos los participantes serán recogidos para un viaje a la <strong>Cascada de Tunan</strong>, ubicada en el <strong>Pueblo de Talawaan</strong>. La fuente de agua de la Cascada de Tunan proviene de un río de montaña que fluye con fuerza por un acantilado empinado de aproximadamente <strong>86 metros de altura</strong>. El bosque prístino y el entorno natural realzan la belleza de esta pintoresca atracción natural.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Después, los participantes disfrutarán del almuerzo en un restaurante local. El viaje continúa hacia la <strong>Reserva Natural de Tangkoko</strong>. Relájate y disfruta del hermoso paisaje mientras pasas por pequeños pueblos en el camino hacia una de las áreas de conservación más importantes de Indonesia.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Ubicada a unos <strong>20 kilómetros al noroeste de Bitung</strong>, la reserva se encuentra entre colinas y valles. Al llegar, serás recibido por un <strong>guardaparques local</strong>, quien te guiará a través del bosque en busca de varias especies de fauna salvaje que deambulan libremente en su hábitat natural. Mantén tu cámara lista — podrías encontrar al <strong>Macaco Negro Crestado de Sulawesi (Yaki)</strong>, al <strong>Tarsio</strong> (el primate más pequeño del mundo), así como a <strong>Cálaos</strong> y <strong>Cuscús</strong> (marsupiales de ojos grandes).&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Después de la exploración de la fauna salvaje, regreso a Manado. Fin del tour.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 38 hari 1 (itinerary 7358)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('7358', 'es', 'Itinerario', '<p style="text-align:justify;">Después del desayuno, nuestro equipo te recogerá en tu hotel en la ciudad de Manado. El viaje continúa hacia el Muelle Serei Likupang, con paisajes costeros y rurales típicos de Sulawesi del Norte en el camino. Al llegar al muelle, abordarás un bote privado hacia la Isla de Lihaga, una isla tropical conocida por su suave arena blanca, aguas turquesas y entorno intacto.</p><p style="text-align:justify;">En la Isla de Lihaga, disfruta de tiempo libre para relajarte en la playa, nadar en aguas claras, o caminar alrededor de la isla capturando su belleza natural desde sus mejores miradores. Para quienes deseen algo más activo, hay disponibles opcionalmente snorkel, canoa y buceo para disfrutar del paisaje submarino bien preservado. El almuerzo se sirve en la isla en medio de la tranquilidad de los trópicos.</p><p style="text-align:justify;">Por la tarde, regreso en bote al Muelle Serei Likupang y continuación hacia la ciudad de Manado. Antes de regresar a tu hotel, parada en un centro de recuerdos de Manado para comprar delicias locales, artesanías y recuerdos de Sulawesi del Norte. Después de las compras, serás trasladado de vuelta a tu hotel.</p><p style="text-align:justify;"><strong>Fin del Tour</strong></p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 18 hari 1 (itinerary 7359)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('7359', 'es', 'Itinerario', '<p style="text-align:justify;">Los participantes serán recogidos por la mañana para un tour al <strong>Monte Mahawu</strong>, ubicado aproximadamente 1 hora y 15 minutos de la ciudad de Manado. El Monte Mahawu es una atracción popular para turistas y excursionistas que visitan Manado. El sendero de caminata consiste en aproximadamente 150 escalones de cemento, lo que hace que el ascenso sea relativamente fácil. En el camino, los participantes encontrarán barandillas metálicas que pueden usarse como apoyo durante el ascenso. Al llegar a la cima, los participantes pueden disfrutar de impresionantes vistas panorámicas de la Isla de Manado Tua, Bunaken y la ciudad de Manado.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">El tour luego continúa hacia el <strong>Cumbre</strong> de la <strong>Colina de Tetetana</strong>, un destino turístico recientemente desarrollado en Tomohon. Además de ofrecer vistas panorámicas de cuatro regiones de la Provincia de Sulawesi del Norte, los visitantes también pueden disfrutar de la belleza de la colina, rodeada de coloridos jardines de flores.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Después, el grupo se dirigirá a un restaurante local para el almuerzo. Después del almuerzo, los participantes regresarán a la ciudad de Manado y serán desembarcados en el punto de recogida designado. Fin del tour.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

