-- paket 37 hari 2 (itinerary 7475)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('7475', 'es', 'Experiencia de Buceo en Bunaken', '<p style="text-align:justify;">Después del desayuno, la aventura de buceo comienza con una selección de los mejores sitios en el Parque Marino de Bunaken. El área es famosa por sus espectaculares paredes de coral verticales, coloridos jardines de coral, y extraordinaria biodiversidad marina.</p><p style="text-align:justify;">Durante las inmersiones podrás ver tortugas verdes y tortugas carey descansando contra las paredes de coral, una amplia variedad de peces tropicales, y depredadores como barracudas y tiburones de arrecife pasando cerca. Después del programa de buceo y el almuerzo, regreso al resort para relajarte en la playa o disfrutar de las instalaciones del resort.</p>', NOW(), NOW())
