-- paket 37 hari 3 (itinerary 7476)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('7476', 'es', 'Descubrir Más del Paraíso Submarino de Bunaken', '<p style="text-align:justify;">Desayuno antes de continuar explorando el mundo submarino de Bunaken. Hoy visitarás sitios de buceo adicionales con un carácter diferente, desde amplios jardines de coral y hermosas pendientes de arrecife hasta las paredes profundas por las que el Parque Marino de Bunaken es conocido.</p><p style="text-align:justify;">Además de su vida marina más grande, Bunaken también es hogar de muchas pequeñas criaturas fascinantes como nudibranquios, peces león, caballitos de mar, camarones, y peces escorpión que se escoden entre los corales. Después de las inmersiones, regreso al resort y tiempo libre para relajarte en el ambiente pacífico de la isla.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

