-- paket 23 hari 1 (itinerary 7481)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('7481', 'es', 'Llegada – Exploración de la Cascada de Tunan', '<p style="text-align:justify;">Llegada a Manado por la mañana. Encuentro con nuestro guía, luego continúas para dirigirte a la&nbsp;<strong>Cascada de Tunan</strong>, esta cascada se encuentra en el&nbsp;<strong>Pueblo de Talawan</strong>. La fuente de la&nbsp;<strong>Cascada de Tunan</strong>&nbsp;proviene del río sobre la montaña que fluye bastante rápido a través de acantilados empinados con una altura de aproximadamente 86 metros. La atmósfera del bosque natural aún prístino e intacto añade a la belleza alrededor del objeto de turismo natural&nbsp;<strong>Cascada de Tunan</strong>.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">&nbsp;Conducimos directamente hacia el&nbsp;<strong>Parque Nacional de Tangkoko</strong>&nbsp;<i>(si llegas por la tarde, omite el viaje a la Cascada de Tunan y ve directamente al pueblo de Batu Putih en Tangkoko)</i>. Al final de la tarde, una breve caminata por el bosque en busca de la gran estrella del parque: el Tarsio, el mamífero más pequeño del planeta. La Villa Santuario de Tangkoko es donde pasarás la noche.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 23 hari 2 (itinerary 7482)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('7482', 'es', 'Tour de un Día Completo a Tangkoko', '<p style="text-align:justify;">Después del desayuno en el homestay, comienza a explorar las especies endémicas de Sulawesi del Norte en la Reserva Natural de Tangkoko. Busca al Macaco Negro Crestado (mono negro nativo de Sulawesi del Norte), otro Tarsio (el primate más pequeño del mundo), el Oso Cuscús, y numerosas aves. El parque nacional es hogar de la mayor densidad de Cálaos del mundo, incluyendo el Cálao Rinoceronte.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Después del almuerzo, iremos a otra excursión por la selva de Tangkoko por la tarde. Pernoctación en el homestay.&nbsp;</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 23 hari 3 (itinerary 7483)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('7483', 'es', 'Waruga Sawangan – Tour del Altiplano de Minahasa', '<p style="text-align:justify;">Después del desayuno, check-out y conducción hacia el altiplano, luego continúas hacia&nbsp;<strong>Waruga Sawangan</strong>, con una parada en la antigua tumba del pueblo Minahasa (Era de la Piedra Gigante). Almuerzo en el&nbsp;<strong>Lago Tondano</strong>. Continúas hacia Tomohon para ver el&nbsp;<strong>mercado tradicional</strong>, después la industria de casas de madera desmontables del&nbsp;<strong>Pueblo de Woloan</strong>&nbsp;(los lugareños aquí crean exquisitas casas de madera al estilo Minahasa que se desmontan y se envían fuera del pueblo), y&nbsp;<strong>Kai\'santi Tomohon</strong>&nbsp;que es una parada fotográfica con un telón de fondo escénico del Monte Lokon &amp; arrozales verdes.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Pasamos la tarde en el&nbsp;<strong>Lago Linow</strong>&nbsp;tomando café o té. Check-in en tu habitación en un resort en Tomohon.&nbsp;</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 23 hari 4 (itinerary 7484)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('7484', 'es', 'Trekking al Mt. Mahawu – Isla de Bunaken', '<p style="text-align:justify;">Después del desayuno en el hotel, check-out. Encuentro con nuestro guía, luego continúas hacia el&nbsp;<strong>cráter del Mt. Mahawu</strong>. Después de una caminata de 10 minutos hasta el borde del cráter, serás recompensado con una vista impresionante de Tomohon y Manado, así como de las islas más allá; en el fondo del cráter, los visitantes pueden ver un lago humeante y sentir el olor a azufre de las pozas. Después del almuerzo, traslado en bote a la isla de Bunaken (aproximadamente 45 minutos en bote).&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">El&nbsp;<strong>Parque Marino de Bunaken</strong>&nbsp;es un parque marino en Sulawesi del Norte, Indonesia, al este de la Isla de Bunaken. Este parque marino es bien conocido por su impresionante paisaje submarino. El Parque Marino de Bunaken, con un área de aproximadamente 89.065 hectáreas, es un destino popular para buceadores y aficionados al snorkel de todo el mundo. El alojamiento se proporcionará en Resorts en la Isla de Bunaken&nbsp;</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 23 hari 5 (itinerary 7485)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('7485', 'es', 'Isla de Bunaken (Natación / Snorkel)', '<p style="text-align:justify;">Disfrutamos libremente de los placeres del mar en uno de los sitios de snorkel más hermosos de Indonesia. Estamos en medio de un magnífico ecosistema con más de 500 tipos de coral y aproximadamente 1.500 especies de peces, tiburones de arrecife inofensivos, y las tortugas se avistan con frecuencia alrededor de la isla.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;"><strong>Nota:</strong> <i>como opción, es posible alquilar equipo de snorkel y hacerlo desde la playa o reservar una excursión en bote. También son posibles las salidas de buceo (reserva y pago en el lugar)&nbsp;</i></p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 23 hari 6 (itinerary 7486)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('7486', 'es', 'Traslado al Aeropuerto', '<p style="text-align:justify;">Después del desayuno en el hotel, check-out. Traslado en bote a Manado, luego serás acompañado por nuestro guía turístico al aeropuerto para el traslado de salida. El tour ha terminado, gracias.&nbsp;</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 40 hari 1 (itinerary 7763)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('7763', 'es', 'Itinerario', '<p style="text-align:justify;">Después del desayuno, serás recogido en tu hotel en el centro de la ciudad de Manado y llevado al <strong>Muelle de Bahowo</strong>. Desde el muelle, el viaje continúa en bote privado hacia la <strong>Isla de Manado Tua</strong>.</p><p style="text-align:justify;">Al llegar a la isla, la aventura comienza con una caminata al Monte Manado Tua de aproximadamente 3 horas. El sendero pasa por bosque tropical y plantaciones del pueblo de nuez moscada, clavo de olor, coco, plátano, mango y otros cultivos tropicales. En el camino, podrás disfrutar del entorno natural y, con un poco de suerte, ver fauna endémica de Sulawesi como el <strong>Tarsio, Yaki (macaco negro crestado) y varias aves endémicas</strong>.</p><p style="text-align:justify;">Después de la caminata, el viaje continúa en bote hacia el <strong>Parque Nacional de Bunaken</strong>. Disfruta de tiempo para explorar la belleza del mar de Bunaken, con snorkel o buceo como actividades opcionales. Se servirá un almuerzo empacado que se puede disfrutar a bordo del bote.</p><p style="text-align:justify;">Después de Bunaken, regreso al <strong>Muelle de Bahowo</strong>, luego serás trasladado a tu hotel en la ciudad de Manado.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 41 hari 1 (itinerary 7765)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('7765', 'es', 'Itinerario', '<p style="text-align:justify;"><strong>Mañana &ndash; Recogida &amp; Waruga Sawangan</strong><br>Serás recogido en tu hotel en el área de la ciudad de Manado y partirás hacia <strong>Waruga Sawangan</strong>, un antiguo complejo funerario Minahasa que alberga cientos de waruga de piedra. Aquí podrás aprender sobre la historia, las tradiciones y el patrimonio cultural del pueblo Minahasa.</p><p style="text-align:justify;"><strong>Batu Angus &amp; Snorkel</strong><br>El viaje continúa hacia <strong>Batu Angus</strong>, una impresionante zona costera formada por flujos de lava volcánica en el pasado distante. Después del almuerzo en un restaurante local, disfruta de tiempo para explorar las aguas de Batu Angus mediante snorkel. El agua clara te permite observar arrecifes de coral, peces tropicales y diversa vida marina.</p><p style="text-align:justify;"><strong>Tarde &ndash; Regreso a Manado</strong><br>Después de disfrutar de la playa y las actividades de snorkel, se continúa hacia la ciudad de Manado. Serás trasladado a tu hotel y el tour concluye.</p><p style="text-align:justify;"><strong>Fin del Tour.</strong></p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();
COMMIT;

